INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2ad806e6-5f7c-53e2-a01b-60582d2c45b0', '0ac55b91-002b-57e3-af49-cea7b9c1b229', '769dff44-991b-53a5-a1ad-ba8140407411', 2, 2, 'ቅጠል ለፍሬ ጌጥ ያገለግላልና ቅጠሉ ካልለመለመ ፍሬ አያፈራም፤ የሰው ራሱ የጽድቅ ፍሬ ነውና ፍሬ የሌለው በጎ ሥራ የለውም።'),
  ('bb0a26f6-22f8-5117-abb3-5556386d13c1', '0ac55b91-002b-57e3-af49-cea7b9c1b229', '769dff44-991b-53a5-a1ad-ba8140407411', 3, 3, 'ጽድቅን ቢሠራ ቅንነትን ያፈራል፤ እግዚአብሔርም እውነትንና ቅንነትን በሚሠራ ሰው ደስ ይለዋል።'),
  ('dbc83117-3c14-5421-a0ed-05705dda9acd', '0ac55b91-002b-57e3-af49-cea7b9c1b229', '769dff44-991b-53a5-a1ad-ba8140407411', 4, 4, 'ለሚጸልይም ጸሎቱንና የአንደበቱን ዋጋ ይሰጠዋል፤ ጻድቁንም ስለ ሠራው ጽድቅ አይበድለውም።'),
  ('103a5367-249f-5730-ae4f-f529b5038e59', '0ac55b91-002b-57e3-af49-cea7b9c1b229', '769dff44-991b-53a5-a1ad-ba8140407411', 5, 5, 'እግዚአብሔር ጻድቅ ነውና፤ ጽድቅንም ይወድዳልና ኃጥኡን ስለ ሠራው ክፉ ሥራ ያለ ንስሓ አያጸድቀውም፤ የሰውም ሁሉ ነፍስ በእጁ ተይዟልና፥ ሰማይንና ምድርንም የሚገዛ ነውና በፍርድ ለባለጠጋና ለድሃ ፊት አያዳላም።'),
  ('15742550-a809-53b5-a4e3-f5602329dbb2', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 1, 1, 'ዓለሙን ሁሉ ከአለመኖር ፈጠረ፤ ተራሮችንና ኮረብቶችንም ፈጽሞ አዘጋጀ፥ ምድርንም በውኃ ላይ አጸናት፤ እንዳትነዋወጥም በአሸዋ ወሰናት፤ በመጀመሪያ የእግዚአብሔር ቃሉ “ብርሃን ይሁን” ብሏልና።'),
  ('26b3e739-063d-57fe-ad9e-5828ff8a66ed', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 2, 2, 'ዓለም በጨለማ ሳለ ብርሃን ሆነ፤ እግዚአብሔርም ሥራውን ሠራ፤ በሚገባና በተስተካከለ ዓለምን አዘጋጅቶ አጸናት፤ ምሽትና ጨለማ ይሁን አለ፤ ምሽትና ጨለማም ሆነ።'),
  ('3ec3cad2-9943-53d7-a92b-0f0dd8d68e4c', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 3, 3, 'ዳግመኛም እግዚአብሔር ብርሃን ይሁን አለ፤ ነጋ፤ ብርሃንም ሆነ፤ የላይኛውንም ውኃ ወደ ሰማይ ከፍ ከፍ አደረገው።'),
  ('8048a258-6bea-5ff4-afbb-f1282244b4d5', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 4, 4, 'እንደ ድንኳንም ዘረጋው፤ በነፋስም አጸናው፤ የታችኛውንም ውኃ በባሕሩ ጥልቅ በታች አኖረው።'),
  ('6118abcb-dbe8-5c4f-a95b-63e174e4eb4b', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 5, 5, 'የባሕሩንም ቍልፍ በአሸዋ ዘጋው፤ ወደ ታችም እንዳይሰጥሙ በመንፈሱ አጸናቸው፤ አራዊትንና እንስሳትንም በውስጧ አኖራቸው፤ ታላላቆች እንስሳትንም፤ ቍጥር የሌላቸው የሚታዩና የማይታዩትንም በውስጧ አኖራቸው።'),
  ('3e2d1c19-64bc-56ae-ab6f-3111e7f390db', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 6, 6, 'በሦስተኛው ቀን እግዚአብሔር በምድር ላይ አትክልትን፥ ሣሩን ሁሉ፥ እንጨቶችን፥ በየወገናቸው የሚያፈሩ ፍሬዎችንም፥'),
  ('0202b1ce-c06e-5f3c-a8db-48d327d04f01', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 7, 7, 'ሊያዩትም ያማረ፥ ሊበሉትም የጣፈጠ ፈጠረ፤ የሕይወት ዛፍን፥ ሣርንም፥ ዘሩ ከውስጡ የሚገኝ ተክልንም ሁሉ ፈጠረ። ለከብቶችና ለአውሬዎች፥ ለወፎችም መብልን ፈጠረ፤ ለፈጠረውም ሁሉ ምግብን ሰጠ።'),
  ('cf44edff-7b92-55f0-a69b-c53db849afe0', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 8, 8, 'ማታም ሆነ፤ ነጋም፤ በአራተኛዪቱም ቀን እግዚአብሔር በሰማይ ጠፈር ብርሃን ይሁን አለ፤ እግዚአብሔርም ፀሐይን፥ ጨረቃንና ከዋክብትን ፈጠረ። በምድር ላይ ያበሩ ዘንድ፥ መዓልትና ሌሊትንም ይመግቧቸው ዘንድ በሰማይ ጠፈር ሾማቸው።'),
  ('6cd9f78a-9fce-5a75-ae1a-86279fe2917d', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 9, 9, 'ከዚህም በኋላ ፀሐይ፥ ጨረቃና ከዋክብት፥ መዓልትና ሌሊትም ተፈራረቁ።'),
  ('8fe7620f-bf3e-5876-a97a-e72838530a10', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 10, 10, 'በአምስተኛዪቱም ቀን እግዚአብሔር በውኃ ውስጥ የሚኖሩ አራዊትንና እንስሳትን ሁሉ ፈጠረ፤ በሰማይ ላይ የሚበሩ ወፎችንም ሁሉ፥ የሚታየውንና የማይታየውን፥ ይህንም ሁሉ እግዚአብሔር ፈጠረ።'),
  ('079b30b7-4b11-5f44-a3af-c43146e7a11b', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 11, 11, 'በስድስተኛዪቱም ቀን አውሬዎችንና እንስሳትን፥ ትሎችንም ፈጠረ፤ ሁሉንም ፈጥሮና አዘጋጅቶ አዳምን በአርአያውና በምሳሌው ፈጠረው።'),
  ('5443b55c-3a60-5d11-a29e-d2dd71d80b77', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 12, 12, 'የፈጠራቸውን እንስሳትና አውሬዎችን ሁሉ ይነግሥባቸው ዘንድ ሰጠው፤ ዳግመኛም እንስሳትንና አራዊትን ሁሉ፥ ዓሣዎችንም ሁሉ፥ በባሕር ያሉ ዓሣ አንበሪዎችንም ሁሉ ሰጠው።'),
  ('bebc6bf5-60d0-5166-a750-39d3fcfd213f', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 13, 13, 'በምድር ላይ ያሉ ላሞችን ሁሉና በጎችንም፥ የሚታየውንና የማይታየውን እንስሳ ሁሉ ሰጠው።'),
  ('3c4fd657-d565-5f03-a23e-fad3d910e55a', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 14, 14, 'በመልኩና በምሳሌው የፈጠረው አዳምንም በገነት አኖረው፤ ይበላ ዘንድ፥ ገነትንም ይኰተኵታት ዘንድ፥ በዚያ እግዚአብሔርን ያመሰግነው ዘንድ አዘዘው።'),
  ('25931813-13dc-570e-a9d9-e28393862790', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 15, 15, 'የእግዚአብሔርንም ትእዛዝ እንዳያፈርስ ሞትን ከሚያመጣ፥ ክፉና በጎንም ከሚያሳውቅ ዛፍ እንዳይበላ አዘዘው።'),
  ('bbb50df7-49e3-5b74-ae24-73c74bf1d588', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 16, 16, '“ከዚያ ዛፍ በበላችሁ ጊዜ ሞትን ትሞታላችሁ” ብሏልና።'),
  ('682abc12-27b7-5cd3-a021-e30811842c01', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 17, 17, 'እናታችን ሔዋን በእባብ ማሳት ተሸንግላ ከዚያ ከዕፀ በለስ በላች፤ ለአባታችን ለአዳምም ሰጠችው።'),
  ('6447feb6-845f-5886-a137-af312a472d82', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 18, 18, 'ከዚያም ዛፍ በላ፤ በራሱና በልጆቹም ላይ ሞትን አመጣ።'),
  ('90ee3ac7-68a0-50c6-a2ca-0b83ccb1fb2e', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 19, 19, 'ትእዛዙን አፍርሷልና፥ እግዚአብሔር ከእርሱ አትብላ ብሎ ካዘዘው ከዚያም ከዕፀ በለስ በልትዋልና እግዚአብሔር በአባታችን በአዳም ላይ ተቈጣ፤ ከገነትም አስወጥቶ ሰደደው፤ ያርሳት ዘንድ፥ በፊቱም ወዝ የድካሙን ዋጋ ይበላ ዘንድ ትእዛዙን በአፈረሰ ጊዜ ስለ እርሱ የረገማትን፥ አሜከላና እሾህን የምታበቅል ያችን ምድር ሰጠው።'),
  ('d1a6cd25-9b06-5bc5-a264-37c7729753c7', 'f71712c5-b3ec-50ae-a796-03582f287120', '9760ef1a-21c1-5567-ac7e-64a50d220f17', 20, 20, 'እግዚአብሔርም ወደዚች ምድር በአወጣው ጊዜ አዳም ወደ ኀዘንና ወደ ልብ ትካዜ ተመለሰ። ምድርንም ያርሳት ዘንድ፥ በፊቱ ወዝ፥ በልፋትና በድካምም ይበላ ጀመር።'),
  ('e7f250c0-ef6e-5704-a4ca-f29a1b392b6b', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 1, 1, 'ከዚህም በኋላ ልጆቹ በዙ፤ ከእነርሱም እግዚአብሔርን የሚያመሰግኑትና የሚያከብሩት፥ ትእዛዙንም የማያፈርሱ ነበሩ።'),
  ('e85e4082-db47-5f47-ad34-13fac6449b70', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 2, 2, 'የሆነውንና የሚሆነውን የሚናገሩ ነቢያትም ነበሩ፤ ከልጆቹም ሐሰት የሚናገሩ፥ ሰውንም የሚበድሉ ኀጢአተኞች ነበሩ፤ የአዳም የበኸር ልጁ ቃየል ክፉ ሆነ፤ ወንድሙ አቤልንም ገደለው።'),
  ('35fc4149-369d-5a91-ae67-4d9039b5956c', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 3, 3, 'ወንድሙን አቤልንም ስለ ገደለ እግዚአብሔር በቃየል እጅግ ተቈጣ፤ ደሙንም ስለ ጠጣች እግዚአብሔር ምድርን ተቈጣት።'),
  ('67cbb04b-a17c-5f72-a5c8-a3bfe0aeab4c', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 4, 4, 'እግዚአብሔርም ቃየልን፥ “ወንድምህ አቤል ወዴት አለ?” አለው ቃየልም በልቡ ትዕቢት “የወንድሜ የአቤል ጠባቂ እኔ ነኝ?” አለ።'),
  ('e6894426-a5c2-579b-aa0d-284f2a7eeb86', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 5, 5, 'አቤልም ጻድቅ ነበረ፤ ቃየል ግን ደጉን ሰው ወንድሙን አቤልን በመግደል ኃጥእ ሆነ።'),
  ('ac820ae8-ad58-5058-a368-f3d7b1f62a9e', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 6, 6, 'ዳግመኛም ጻድቅ ሴት ተወለደ፤ አዳም ሠላሳ ሴቶችንና ሠላሳ ወንዶችን ወልዷልና። ከእነርሱም ደጋጎች ነበሩ፤ ክፉዎችም ነበሩ።'),
  ('139530ae-e316-5ce9-a9ff-d122c3a3bae6', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 7, 7, 'ከእነርሱም ነቢያትና ጻድቃን ነበሩ፥ ከእነርሱም ኃጥኣንና ሸንጋዮች ነበሩ።'),
  ('0f8c62cc-6c32-5589-ae95-96ce7ee18a38', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 8, 8, 'ከእነርሱም የአባታቸውን የአዳምን ፈቃድ፥ ከአዳም ጀምሮ የእግዚአብሔርን ትእዛዝ እስከ ጠበቀ እስከ ጻድቁ ኖኅ ድረስ፥ ለልጁ ለሴት የነገረውንም ሁሉ የሚፈጽሙ ደጋጎችና ቡሩካን ነበሩ።'),
  ('a468acab-2c92-54cb-a9fd-8c0ecc7cfc90', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 9, 9, 'እርሱም ለልጆቹ የእግዚአብሔርን ሕግ አስጠበቃቸው፤ የእግዚአብሔርንም ሕግ እንዳያፈርሱ አባታቸው ኖኅ እንደ ነገራቸው እነርሱም ለልጆቻቸው ይነግሩ ዘንድ፥ የእግዚአብሔርንም ሕግ ይጠብቁ ዘንድ አደራ አላቸው።'),
  ('23a2d94c-3888-525f-afc0-20664fa7bce2', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 10, 10, 'እነርሱም ከእነርሱ በኋላ ለልጆቻቸው እያስተማሯቸው ኖሩ።'),
  ('6616d254-5040-591b-ad86-1d5b64b62652', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 11, 11, 'ሰይጣን ግን አባቶቻቸውን ለመቃብር በአደረሱ፥ ሥዕል ባለባቸው ጣዖታት አድሮ፥ እሺ የሚሉትን ሰዎች ሲወጋቸውና ሲናገራቸው ኖረ፤ ያም የክፋት መምህር ያዘዛቸውን ሁሉ ሲያደርጉ ኖሩ።'),
  ('351a6bda-eba3-507c-af38-5396c5dd3995', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 12, 12, 'የእግዚአብሔርንም ፈቃድ የሚፈጽም ጻድቅ አብርሃም እስኪነሣ ድረስ እንደ ሥርዐታቸው ጣዖቱን ሲያመልኩ ኖሩ።'),
  ('099c20af-04ea-5364-afa5-d84d4a0e1bf9', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 13, 13, 'እግዚአብሔርም ከእርሱ ጋራ በእሳትና በአውሎ ቃል ኪዳን አደረገ። ከዘመዶቹ ተለይቶ በጽድቅ መንገድ መሔድን እርሱ ቀድሞአልና።'),
  ('a60d494a-39a6-5efb-a413-5d682cb04ab6', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 14, 14, 'እግዚአብሔርም ለእርሱና ለልጆቹ ምድረ ርስትን እስከ ዘለዓለም ድረስ ይሰጣቸው ዘንድ ማለለት።'),
  ('062b668e-059b-5cf2-a59f-9ce745808ed3', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 15, 15, 'እንዲሁም ለይስሐቅ የአባቱን የአብርሃምን ርስት ይሰጠው ዘንድ ማለለት፤ ለያዕቆብም እንዲሁ የአባቱን የይስሐቅን ርስት ይሰጠው ዘንድ ማለለት፤'),
  ('b54ef382-6cb8-533a-a6f4-0155acad74fa', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 16, 16, 'ከእነርሱም በኋላ ዘራቸውን የያዕቆብን ልጆች ከዐሥራ ሁለቱ ነገደ እስራኤል ነገሥታትና ካህናት አደረጋቸው፤ ባረካቸው፤ “ብዙ፥ የብዙ ብዙም ሁኑ” አላቸው።'),
  ('74cd805c-a0eb-501c-a9c6-dd971fbc55be', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 17, 17, 'የአባቶቻቸውንም ርስት ሰጣቸው፤ ነገር ግን እየመገባቸው፥ በሁሉም እየወዳደቸው ሳለ እግዚአብሔርን ማሳዘን አልተዉም።'),
  ('ca11ec8b-1c6f-5fb7-af23-5bf97761cf5d', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 18, 18, 'ባጠፋቸውም ጊዜ ያንጊዜ ይፈልጉታል፤ ተመልሰውም ወደ እግዚአብሔር ይገሠግሣሉ፤ እግዚአብሔርም ይወድዳቸዋልና ይቅር ይላቸዋል።'),
  ('685a2a29-4f38-59d3-a2df-dac2b6a2fe6d', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 19, 19, 'ስለ ራሳቸውም አይደለም፤ ስለ አባቶቻቸው ነው እንጂ፥ ለፈጠረው ሁሉ መሓሪና ይቅር ባይ ነውና።'),
  ('93d48d6b-4e4c-50a8-a3b6-be2da4e398ee', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 20, 20, 'የተራበች ሰውነትንም ያጠግብ ዘንድ ቀኝ እጁን በበረከት ይዘረጋል፤ ለምግብ እህልን ያበዛ ዘንድ ለምሕረት ዐይኑን ይገልጣል።'),
  ('7fc6f3d9-471b-51ec-a6d8-de9872d57f8c', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 21, 21, 'ለቍራዎች ጫጩቶችና ለሚጠሩት ሁሉ ምግብን ይሰጣቸዋል፤ ወደ እርሱም በጮሁ ጊዜ፥ የእስራኤልን ልጆች ከጠላቶቻቸው እጅ ያድናቸዋል።'),
  ('8413ddf6-938f-5d3c-a1ab-986a34a202cf', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 22, 22, 'ዳግመኛም ያሳዝኑት ዘንድ ይመለሳሉ፤ እርሱም በዙሪያቸው ያሉ ጠላቶቻቸውን አሕዛብን ልኮ ያጠፏቸዋል፥ ይገድሏቸዋል፥ ይማርኳቸዋልም።'),
  ('5d3f975d-904f-5126-a37a-334008f391fe', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 23, 23, 'ዳግመኛም በጩኸትና በልቅሶ ወደ እግዚአብሔር ይጮኻሉ፤ እርሱም ረዳትን ይልክላቸዋል፤ በነቢያት እጅም ያዳነበት ጊዜ አለ።'),
  ('624a54d3-85b2-5f7e-aa01-1a94309857e5', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 24, 24, 'በመሳፍንትም እጅ ያዳነበት ጊዜ አለ፤ እግዚአብሔርንም ባሳዘኑት ጊዜ ጠላቶቻቸው አስገበሯቸው፤ ማረኳቸውም።'),
  ('134c2bcd-c701-5882-ac3f-79f747030489', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 25, 25, 'ዳዊትም ተነሥቶ ከኢሎፍላውያን እጅ አዳናቸው፤ ዳግመኛም እግዚአብሔርን አሳዘኑት፤ የሚያስጨንቋቸውንም አስነሣባቸው።'),
  ('8dedec38-9990-56b9-a6aa-415df38cde10', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 26, 26, 'በዮፍታሔም እጅ ያዳነበት ጊዜ አለ፤ ዳግመኛም ያዳናቸውን እግዚአብሔርን ዘነጉት። እግዚአብሔር ፍዳውን አምጥቶባቸዋልና ክፉ የሆኑ፥ መከራን የሚያጸኑባቸውን፥ ፈጽመውም የሚማርኳቸውን ጠላቶችን ይልክባቸዋል።'),
  ('7b3c02fa-c0d0-596b-a0cc-f6d969921d7e', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 27, 27, 'ዳግመኛም በተጨነቁ ጊዜ ወደ እርሱ ጮሁ፤ እርሱም በጌዴዎን እጅ አዳናቸው፤ ዳግመኛም በእጃቸው ሥራ እግዚአብሔርን አሳዘኑት።'),
  ('583da9a8-24f8-5d8d-aa1f-d5a25ece7ae4', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 28, 28, 'እርሱም ዳግመኛ የሚያሰቃዩአቸውን ላከባቸው፤ ተመልሰውም ወደ እግዚአብሔር አለቀሱ፤ ጮኹም።'),
  ('757754ef-c613-5c90-ad87-d42baaec72cd', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 29, 29, 'ዳግመኛም በሶምሶን እጅ አዳናቸው፤ ጥቂትም ዐረፉ። አስቀድመውም በሠሩት ክፋታቸው እግዚአብሔርን ያሳዝኑት ዘንድ ተነሡ።'),
  ('dfec874b-f611-51d5-a3eb-b564e66eeccc', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 30, 30, 'እርሱም ዳግመኛ የሚያስጨንቋቸውን ሌሎችን ላከባቸው። ዳግመኛም ረዳትን ይልክላቸው ዘንድ ወደ እግዚአብሔር ጮሁ፤ አለቀሱም፤ በባርቅና በዲቦራም እጅ አዳናቸው።'),
  ('6abef87e-ca87-5a72-a535-4d4bc36ca8f5', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 31, 31, 'ዳግመኛም እግዝአብሔርን እያመለኩት ጥቂት ዘመን ኖሩ፤ ዳግመኛም ረሱት፤ በቀደመ ክፋታቸውም እግዚአብሔርን አሳዝኑት።'),
  ('11921ba6-46b0-54f5-a28c-599b5635b29a', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 32, 32, 'እርሱም የሚያስጨንቋቸውን ሌሎችን ላከባቸው፤ ዳግመኛም በዮዲት እጅ አዳናቸው፤ ዳግመኛም ጥቂት ወራት ተቀምጠው እንደ ቀደመው እግዚአብሔርን በክፋታቸው ያሳዝኑት ዘንድ ተነሡ።'),
  ('65a675bf-4b75-55d2-acb8-5da429a312c2', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 33, 33, 'እርሱም የሚገዟቸው አሕዛብን አስነሣባቸው፤ እነርሱም ወደ እግዚአብሔር ጮሁ፤ አለቀሱም፤ በማታትዩና በልጆቹ እጅ በቤት ማዕዘን ላይ አዳናቸው።'),
  ('f4cc67f5-9001-5868-aba2-812ca766fddc', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 34, 34, 'የይሁዳን ሀገር ይወጋ ዘንድ የመጣው አሂሜሌክ የረዓይታዊውን ራስ መትቶታልና፤ ያም ራዓይታዊ በሞተ ጊዜ ሠራዊቱ ተበተኑ፤ ሸሹም፤ የእስራኤልም ልጆች እስከ ኢያቦቅ ወጉአቸው፤ ከእነርሱም አንድ እንኳ የሚሸሽ አላስቀሩም።'),
  ('8fedb7ec-08e7-53bc-a0f1-77d3f6d45e4c', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 35, 35, 'ከዚህ በኋላ ጥቂት ቈይተው እግዚአብሔርን ያሳዝኑት ዘንድ ተነሡ፤ እርሱም የሚገዟቸው አሕዛብን አስነሣባቸው፤ ዳግመኛም ወደ እግዚአብሔር ጮሁ፤ አለቀሱም፤ እግዚአብሔርም ሁልጊዜ አሳዝነውታልና፥ ሕጉንም ረስተዋልና እግዚአብሔር ጩኸታቸውንና ልቅሷቸውን ቸል አለ።'),
  ('1e14b505-3ba6-51d0-a667-bbd92ebaa8b6', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 36, 36, 'ማርከውም ከካህናቶቻቸው ጋር ወደ ከለዳውያን ሀገር ወሰዷቸው።'),
  ('d212cc67-2345-57cc-a66c-d6ce74175885', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 37, 37, 'በዚያም ኀጢአትን እየሠሩ፥ ጣዖትንም እያመለኩ ከዳተኞች የእስራኤል ልጆች እግዚአብሔርን ማሳዘንን አልተዉም። ከማረኩዋቸው ከአሕዛብም ጋር ተቀላቀሉ።'),
  ('0bdcd0d8-00c3-51dd-a1bd-46709a0f9f88', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 38, 38, 'እግዚአብሔርም በዚያ በኀጢአታቸው አንድ ጊዜ ያጠፋቸው ዘንድ ተቈጣ፤ በንጉሡም ሣጥን እልፍ ወርቅን አግብቶ በታወቀች ቀን ያጠፋቸው ዘንድ በነገረው ጊዜ ከሕንደኬ ጀምሮ እስከ ኢትዮጵያ ድረስ በፋርስ ሀገር ልጆቻቸውን እንዳያስቀር በንጉሡ በአርጤክስስ ልቡና ቍጣን አሳደረ።'),
  ('b63e7140-1841-5337-aefa-d8826c2f6e48', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 39, 39, 'እንዲህም አደረገ፥ በንጉሡ ፈቃድ የመልእክት ደብዳቤ ጻፈ፤ ወደ ፋርስም ሀገር ያደርስ ዘንድ በእጁ ያለ ማኅተምን ሰጠው።'),
  ('053f3b45-a5e7-5e1b-a855-cab8920f4def', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 40, 40, 'ንጉሥ እንዳዘዘ ሊያጠፋቸው በወደደባት ባንዲት ቀን ያጠፋቸው ዘንድ ማኅተምን ሰጠው፤ ብዝበዛቸውን ወርቁንና ብሩን ግን ወደ ንጉሡ ሣጥን ያገቡ ዘንድ አዘዘ።'),
  ('a90b267a-017c-541f-a21e-c03b42264ab0', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 41, 41, 'ያንጊዜም የእስራኤል ልጆች ይህን በሰሙ ጊዜ ወደ እግዚአብሔር ፈጽመው ጮሁ፤ አለቀሱም፤ ለመርዶክዮስም ነገሩት፤ መርዶክዮስም ለአስቴር ነገራት።'),
  ('2b2e975f-158f-57d0-a9de-d783f591942f', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 42, 42, 'አስቴርም“ጹሙ፤ ጸልዩም፤ የእስራኤል ልጆች ወገኖችም ሁሉ ባላችሁበት ቦታ ወደ እግዚአብሔር ጩሁ” አለች።'),
  ('db598a3f-f64b-5a0c-ae38-de8015f3845a', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 43, 43, 'መርዶክዮስም ማቅ ለበሰ፤ በራሱም ትቢያን ነሰነሰ፤ የእስራኤልም ልጆች ባሉበት ሀገር ጾሙ፤ ጸለዩም፤ ንስሓም ገቡ።'),
  ('277d5613-1d5c-5322-ada9-b6ca3c351753', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 44, 44, 'አስቴርም እጅግ አለቀሰች፤ ንግሥትም ስትሆን ማቅ ለበሰች፤ ትቢያንም ነሰነሰች፤ ራሷንም ተላጨች፤ የፋርስም ንግሥታት እንደሚያደርጉት ሽቱን አልተቀባችም፤ በጥልቅ ልቡናዋም ወደ አባቶችዋ ፈጣሪ ወደ እግዚአብሔር ጮኸች፤ አለቀሰችም።'),
  ('862f562c-173f-57c9-a1b5-283f854f8493', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 45, 45, 'ስለዚህም በፋርስ ንጉሥ በአርጤክስስ ፊት ሞገሰን ሰጣት፤ ስለ አባቶችዋም ፈጣሪ ታላቅ ግብዣን አደረገች።'),
  ('5b370df3-e390-5a5c-a9ba-c4d797041501', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 46, 46, 'ንጉሡና ሐማም አስቴር ወደ አዘጋጀችው ምሳ ገቡ፤ በዚያም በመርዶክዮስ ላይ ያደርግ ዘንድ እንደ ወደደ እግዚአብሔር ለሐማ ፍዳውን ከፈለው፤ በረጅም እንጨት ላይም ሰቀሉት።'),
  ('41fb3c3a-f9a1-51e1-ac5c-467781091761', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 47, 47, 'በፈቃዳቸው ሁሉ እንዳሉ እስራኤልን ይተዋቸው ዘንድ፥ እንዳያስገብሯቸውም፥ እንዳይቀሟቸውም፥ እንዳይበድሏቸውም፥ ገንዘባቸውንም እንዳይወስዱባቸው የንጉሡ ደብዳቤ ተላለፈ።'),
  ('59e9ab5a-a5d2-5b01-abe4-f41fcc74531b', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 48, 48, 'ሀገራቸውን እንዳያጠፉ፥ ከብቶቻቸውንም እንዳይማርኩ፥ ነገር ግን በፋርስ ሀገር ሁሉ ይወድዷቸውና ያከብሯቸው ዘንድ ደብዳቤው ተላለፈ። በንስሓ ወደ እርሱ በለመኑና በጮኹ ጊዜ እግዚአብሔር እስራኤልን እንዲህ ይቅር ይላቸዋልና።'),
  ('2149073d-32e4-582b-a60c-0bbe0afa138d', '81bac29b-39be-58db-a662-ceac83d812fa', '1b6020e4-2a0f-5253-abe2-1407c01f02a0', 49, 49, 'ባሳዘኑትም ጊዜ የሚያስጨንቋቸው አሕዛብን ያስነሣባቸዋል፤ ያንጊዜም ረዳታቸውን ይልክላቸው ዘንድ መከራ ከሚያጸኑባቸው ከአሕዛብም እጅ ያድናቸው ዘንድ ፈጽመው ያለቅሳሉ፤ ይጮኻሉም።'),
  ('7b01e5bd-f64b-5ba9-af84-6530720fdb16', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 1, 1, 'የግብፅም ሰዎች የእስራኤልን ልጆች በጭንቅ፥ ጡብ በማሠራት፥ በሚያሠሩአቸውም ሥራ ሁሉ፥ ያለ ገለባ ጭቃ በማስረገጥ በአስጨነቋቸው ጊዜ፥'),
  ('09de4b8d-c0fb-5739-ab59-3faa479d4612', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 2, 2, 'ሠሪዎችን የሚያፋጥኑ አለቆችንም በእነርሱ ላይ ሾመው ባሠሯቸው ጊዜ የግብፅን ጡብ ሁሉ ከመሥራት ያድናቸው ዘንድ ወደ እግዚአብሔር ጮሁ።'),
  ('5f0502cb-998e-5068-a133-4a999a7ecf94', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 3, 3, 'የዚያን ጊዜም የሚረዷቸውን ሙሴንና አሮንን ላከላቸው፤ ከግብፅ ንጉሥ ከፈርዖን አገዛዝ ቤት ወገኖቹን ያወጡ ዘንድ እግዚአብሔር ልኳቸዋልና ከጡብ ሥራ አዳኗቸው፤ ለእግዚአብሔር እንዳይገዙ፥ በምድረ በዳም መሥዋዕት እንዳይሠዉ በትዕቢቱ እስራኤልን ማሰናበት እንቢ ብሏልና።'),
  ('e7216d3a-156e-5c80-a99b-ddb521ebb47e', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 4, 4, 'እግዚአብሔርም ትዕቢተኞችን ቸል ይላቸዋልና ፈርዖንን ስለ ትዕቢቱ ከሠራዊቱ ጋር በኤርትራ ባሕር አሰጠመው።'),
  ('bf5aa169-6348-56d4-af74-ba4a8b6350c9', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 5, 5, 'እንዲሁም ነገሥታትና መኳንንት ሲሆኑ የእግዚአብሔርን ቃል ቸል የሚሉ፥ ፈቃዱንም ይፈጽሙለት ዘንድ፥ በበጎም ነገር ለሚያገለግሉ ሰዎች ደመወዛቸውን ይሰጧቸው ዘንድ፥ ገናና ስሙንም ያከብሩ ዘንድ በሾማቸውና በአነገሣቸው ሁሉ መልካም ያልሠሩትን ቸል ይላቸዋል።'),
  ('597ebc94-b584-51ea-a987-0c769606cadd', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 6, 6, '“መንግሥቴን ቢያቀኑ መንግሥታቸውን አቀናላቸዋለሁ ይላል ሁሉን የሚችል እግዚአብሔር።'),
  ('b9fce4e0-9708-5660-a4ed-2b27a22a63b5', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 7, 7, 'መልካም አድርጉልኝ፤ እኔም መልካም አደርግላችኋለሁ፤ ትእዛዜን ጠብቁ፤ እኔም ሰውነታችሁን እጠብቃለሁ፤ በትእዛዜ ሒዱ፤ እኔም እንደ ልቡናችሁ እሔዳለሁ።'),
  ('8a4dc4eb-cebf-50bc-ac71-23899dbe9e87', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 8, 8, 'እኔን ውደዱ፤ እኔም ሕይወታችሁን እወድዳለሁ፤ ወደ እኔ ተጠጉ፥ እኔም አጸናችኋለሁ።'),
  ('4d37b915-d0f0-5ac3-a947-25acf6314cd8', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 9, 9, 'በእኔ እመኑ፤ እኔም አድናችኋለሁ ይላል ሁሉን የሚችል እግዚአብሔር።'),
  ('c57bb915-96b3-51c6-a854-7bdfa5d617d1', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 10, 10, 'እናንተ አግድም አግድም አትሒዱ፤ እናንተ ቅረቡኝ፤ እኔም እቀርባችኋለሁ፤ ቀና መንገዶችን እወድዳለሁና ይላል ሁሉን የሚችል እግዚአብሔር። ኃጥኣንና ከዳተኞች፥ እጆቻችሁን አንጹ፤ የልቡናችሁንም ክፋት አስወግዱ፤'),
  ('c34dbc85-31af-5348-af51-c928a75a678d', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 11, 11, 'እኔም ቍጣዬን ከእናንተ አርቃለሁ፤ በይቅርታና በምሕረትም እመለስላችኋለሁ።'),
  ('2432fdc6-65af-5f3c-ae49-26b99b8b3484', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 12, 12, 'በደልን የሚሠሩ ወንጀለኞች ጠላቶችንም ከእናንተ አርቃለሁ፤ ባሪያዬ ዳዊትን ከተገናኙት ከጠላቶቹ ከብዙ ተንኰላቸው፥ አርበኛ ከሆነ ከጎልያድም እጅ፥ ይገድለውም ዘንድ ከፈለገው ከሳኦል እጅ፥ መንግሥቱን ይወስድ ዘንድ ከወደደ ከልጁ ከአቤሴሎምም እጅ እንዳዳንሁት፥'),
  ('f3b03e66-6bbd-53b9-ab1f-b12ec9ff59f8', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 13, 13, 'ሕጌን የሚጠብቁ፥ ፈቃዴንም የሚፈጽሙ ሰዎችንም እንደ እርሱ አድናቸዋለሁ፤ ክብርንም አወርሳቸዋለሁ፤ በዚህም ዓለም በሚመጣውም ዓለም ደስ ይላቸው ዘንድ በሁሉ ላይ አነግሣቸዋለሁ።”'),
  ('86e7c8e0-7ebf-5ecc-a48b-56fd8243c522', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 14, 14, 'እርሱ ሕጻን ሆኖ ሳለ ከሕጻንነቱ ጀምሮ በአማረ አኗኗሩ እግዚአብሔር እንደ መረጠው እንደ ሳሙኤል በአማረ አኗኗራቸው እግዚአብሔርን ካገለገሉ ቡሩካን ነገሥታት ጋር አንድ ይሆናሉ።'),
  ('c34ae4eb-e15d-5a91-a22d-a7e2fa9ff070', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 15, 15, 'ሥራው መልካም ለሆነ ለአረጋዊው ካህን ለኤሊ ይነግረው ዘንድ በእግዚአብሔር አምላክ ማደሪያ ሲያገለግል ለነቢዩ ሳሙኤል ነገረው።'),
  ('5f7b1bc1-0b10-5b41-a83c-4bfcf366081f', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 16, 16, 'በእግዚአብሔርም ቤት እያገለገለ በአደገ ጊዜ በእግዚአብሔር ትእዛዝ ሕዝቡን እንዲሾምና ነገሥታቱን እንዲቀባ አደረገው። እግዚአብሔርም ከእስራኤል ልጆች የመረጠውን ወገን ይሾም ዘንድ ወድዶታልና የፈጠረው የእግዚአብሔርን ፈቃድ በፈጸመ ጊዜ በእጁ ቅብዐ መንግሥትን ሰጠው።'),
  ('9b122a93-c6ab-5235-ae94-b1f86b628e58', 'e367c938-9f89-587e-adf3-5a651efbe3e2', '425d760b-a08a-5fd3-aa30-2ef28287b22a', 17, 17, 'ሳኦልም በመንግሥቱ ሳለ እግዚአብሔር ነቢዩ ሳሙኤልን እንዲህ አለው፥ “ከይሁዳ ወገን የተወለደ የዕሤይ ልጅ ዳዊትን ወድጄዋለሁና ሒድና ቅባው።”'),
  ('0bd1f798-1821-5c75-a04b-c0cafc857f1f', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 1, 1, '“ቃሌን ስለ ተላለፈ አሳዝኖኛልና የሳኦልን ወገን ጠላሁ።'),
  ('5b703185-e697-57fe-a2ad-3d8555a156cf', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 2, 2, 'እኔም ቸል አልሁት፤ ዳግመኛም ቃሌን አልጠበቀምና ከወገኑ አላነግሥም።'),
  ('5f653e6f-7641-5b37-ab36-86c23e980dc7', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 3, 3, 'እንደዚሁም ቃሌን ከማይጠብቁ፥ በሕጌና በሥርዐቴ ከማይሔዱ መንግሥቴንና ስጦታዬን እስከ ዘለዓለሙ ድረስ ከልጆቻቸው እከለክላለሁ።'),
  ('c2566c79-f23b-58de-a4c8-88d94bf15f26', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 4, 4, 'ባገነንኋቸው ጊዜ አያገኑኝምና፥ በአከበርኳቸውም ጊዜ አያከብሩኝምና አጠፋቸዋለሁ እንጂ ደግሜ ላከብራቸው አልመለስም።'),
  ('d1aa9931-57eb-5009-a884-5a5704b37a0c', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 5, 5, 'በጎ ነገርን ባደረግሁላቸውም ጊዜ አያደርጉልኝም፤ ይቅር ባልኋቸውም ጊዜ ይቅር አይሉልኝም።'),
  ('89d0b9ee-d87b-5180-a315-11d19fbb79c0', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 6, 6, 'በሁሉም ላይ ገዢ ባደረግኋቸው ጊዜ ገዢ አላደረጉኝም፤ ከሁሉ ይልቅ ባከበርኋቸውም ጊዜ አያከብሩኝም፤ ትእዛዜንም አይጠብቁም።'),
  ('a4d59793-bce3-5b8f-ac29-d67e1e3d0d42', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 7, 7, '“እኔም የሰጠኋቸውን ስጦታ ነሳኋቸው፤ በቍጣዬም እንደ ማልሁ አልመልስላቸውም፤ ሁሉን የሚችል እግዚአብሔር እንዲህ ይላል፦ ያከበረኝን አከብረዋለሁ፤ የወደደኝንም እወድደዋለሁ።'),
  ('79f56e07-c735-564d-a463-49c057089e5d', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 8, 8, 'ያላከበሩኝን፥ ሕጌንም ያልጠበቁትን ከሰጠኋቸው ስጦታ እለያቸዋለሁ።'),
  ('d291af8a-e112-568d-a3a7-eb73f2c83ba6', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 9, 9, 'ሁሉን የሚችል እግዚአብሔር እንዲህ ይላል፦ የወደደኝን እወድደዋለሁ፤ ያገነነኝንም አገንነዋለሁ፤'),
  ('a680bbe4-3a7d-592a-a6a1-777d03e9967d', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 10, 10, 'እኔ እግዚአብሔር ሁሉን የምችል ነኝና በላይ በሰማይ፥ በታችም በምድር ከእጄ የሚያመልጥ የለም፤ የምገድል፥ የማድንም፥ የምገርፍ፥ ይቅርም የምል እኔ እግዚአብሔር ነኝና።'),
  ('cbc43401-dfd1-5319-ac3b-55976c359cd3', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 11, 11, 'ክብርና ገናናነትም የእኔ ነው፤ የወደድሁትን አከብረዋለሁ፤ የጠላሁትንም አዋርደዋለሁ፤ የምፈርድና የምበቀል እኔ ነኝና።'),
  ('77f34b5f-9198-5e1e-a77d-1963c3f1f6b2', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 12, 12, '“የሚወድዱኝንና ስሜን ሁልጊዜ የሚጠሩትን ይቅር የምል እኔ ነኝ፤ ለባለጠጋውና ለድሃው ምግብ የምመግብ እኔ ነኝ።'),
  ('8a3431e9-934e-508e-a32b-650a18c33900', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 13, 13, 'ሰውን ብቻ አይደለም፤ ነገር ግን ወፎችንና እንስሶችን፥ በባሕር ያሉ ዓሣዎችንና አውሬዎችን፥ እባቦችንም እመግባለሁ።'),
  ('a4d8b353-a835-5567-afb3-0d982b1b375e', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 14, 14, 'አዞዎችንና ዓሣ አንበሪዎችን፥ ሽኮኮዎችንና ጉማሬዎችን፥ አቈስጣንም እመግባለሁ።'),
  ('e2883b55-ec8a-55ff-a453-5890a4efc542', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 15, 15, 'በውኃ ውስጥ የሚንቀሳቀሰው ሁሉ፥ በአየር ላይ የሚበርረውም ሁሉ የኔ ነው።'),
  ('d415746c-ed7a-523d-a05e-d5be7801f87b', 'f45bbed4-6af3-5ca7-a821-369fc78fe269', 'cba2ba9e-192f-5960-aaa4-f709e5a2115e', 16, 16, 'በሚገባና በሚያስፈልግ ሁሉ እኔን ለሚፈልጉኝ ሁሉ የምመግብ እኔ ነኝ።'),
  ('d9a872a4-f6d5-5acd-a435-8aec66f269ed', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 1, 1, '“ነገሥታት ያለ እኔ ፈቃድ አይነግሡም፤ ጦም አዳሪዎችም ያለ ትእዛዜ አይደኸዩም፤ ኀይለኞችም ያለ ትእዛዜ አይበረቱም።'),
  ('458578e2-952e-5617-a92a-c1d884def745', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 2, 2, 'እኔ ለዳዊት ባለሟልነትን ለሰሎሞንም ጥበብን ሰጠሁት፤ ለሕዝቅያስም ዘመኖችን ጨመርሁለት።'),
  ('52753d57-3d2d-584c-a08d-7203c3c885d5', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 3, 3, 'የጎልያድንም ዘመን አሳነስሁ፤ ለሶምሶንም ኀይልን ሰጠሁት፤ ዳግመኛም ኀይሉን አደከምሁ።'),
  ('4a7425c0-6700-5870-a92d-01ecc2ff2b0b', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 4, 4, 'ባርያዬ ዳዊትንም ከረዓይታዊው ከጎልያድ እጅ አዳንሁት።'),
  ('18f581f5-95ef-5026-a160-2f6e01565552', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 5, 5, '“ዳግመኛም ከንጉሡ ከሳኦል እጅ፥ እንደዚሁም ከሚቃወመው ከሌላው ረዓይታዊ እጅ፥ ከሚቃወሙትና ከሚጠሉትም ሁሉ እጅ አዳንሁት፤ ትእዛዜን ጠብቋልና።'),
  ('4d340d47-3ee1-5e71-adaf-a4f8c091f8e4', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 6, 6, 'እኔም እርሱን ወደድሁ፤ ትእዛዜን የሚጠብቁ ነገሥታትንና መኳንንትንም እወዳድቸዋለሁ፤ እነርሱም ደስ አሰኝተውኛልና በጠላቶቻቸው ላይ ኀይልንና ድልን እሰጣቸዋለሁ።'),
  ('117453ba-6773-5ece-ab99-147fb2cb0665', '2d0c939b-c620-52be-ae3a-1858f353217f', 'e143405c-8e01-52eb-aea9-b7abffa94189', 7, 7, 'ዳግመኛም የአባቶቻቸውን ምድር ይወርሱ ዘንድ ለአባቶቻቸው የማልሁላቸውን የነጻችና የበራች ምድረ ርስትን እሰጣቸዋለሁ።'),
  ('af5dc31b-132c-5090-a525-1642b1cadd21', 'cab9bafb-a24e-5663-af56-533c98019d46', 'ab33f9e3-0c5a-5d3e-a08c-d0778beac5ca', 1, 1, '“እናንተም ነገሥታትና መኳንንት፥ ቃሌን ስሙ፤ ትእዛዜንም ጠብቁ ይላል ሁሉን የሚችል እግዚአብሔር። የጠበቅኋቸውና ያዳንኋቸው፥ ከወላጆቻቸው ጀምሮ ያሳደግኋቸው፥ በሚፈልጉት ሁሉ የመገብኋቸው፥'),
  ('228c5a6f-3005-551f-a249-501373b5d8fb', 'cab9bafb-a24e-5663-af56-533c98019d46', 'ab33f9e3-0c5a-5d3e-a08c-d0778beac5ca', 2, 2, 'ወደ ምድርም አዝመራ ያገባኋቸው፥ እንደሚገባም የምድርን በረከት የመገብኋቸው፥ ያልተከሉትን የወይኑን ተክልና የዘይቱን ፍሬ፥ ያልቈፈሩትን የጠራ የውኃ ጕድጓድ፥'),
  ('ebc51676-8f7c-56a6-ac65-66892271d9cf', 'cab9bafb-a24e-5663-af56-533c98019d46', 'ab33f9e3-0c5a-5d3e-a08c-d0778beac5ca', 3, 3, 'የማሩን ወለላ፥ የበጊቱንም ወተት፥ ከስንዴው ፍትግ ጋር የጌጡን ልብስና ለእነርሱ የሚያስፈልገውን ሁሉ የሰጠኋቸው፥ አምላካቸው እግዚአብሔር ስሆን፥ እንደ አሳዘኑኝና ሌሎች አማልክትን እንደ አመለኩ እንደ እስራኤል ልጆች አታሳዝኑኝ።'),
  ('9a49dd25-9b8e-5146-a07b-21d6378f0ba4', 'cab9bafb-a24e-5663-af56-533c98019d46', 'ab33f9e3-0c5a-5d3e-a08c-d0778beac5ca', 4, 4, 'ከለመኑኝም ያልሰጠኋቸው አልነበረም።'),
  ('8ddcb079-8654-5ed8-a9d9-c21a9a0585ce', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 1, 1, '“ዳግመኛም ዳዊት፦ ሰዎች የመላእክትን እንጀራ በሉ ብሎ እንደ ተናገረ በምድረ በዳ መናን መገብኋቸው፤ በሚገባና በእውነት ያመልኩኝ ዘንድ ይኽን ሁሉ አደረግሁላቸው።'),
  ('81a2b428-bf5c-5e00-a1f5-e937daf740b3', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 2, 2, 'እነርሱ ግን አላመለኩኝም፤ እኔም ቸል አልኋቸው ይላል ሁሉን የሚችል እግዚአብሔር። አሳዘኑኝ የእኔም ባልሆነ መንገድ ሔዱ።'),
  ('227d053a-f577-5979-a047-ed31d7fb66de', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 3, 3, 'እኔም እንደ ሥራቸው እከፍላቸዋለሁ። አምልኮቴን ቸል ብለዋልና፥ በምክሬና በሥርዐቴም አልጸኑምና እንደ እጃቸው ሥራ ቸል አልኋቸው፤ ወደ ገሃነም ቅጣትም አወርዳቸዋለሁ።'),
  ('9f1eaa00-e86f-5eaa-ac37-899a55816c67', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 4, 4, 'ትእዛዜንም አልጠበቁምና፥ እኔም እቈጣቸዋለሁና በምድር ዘመናቸውን አሳንሳለሁ።'),
  ('eb1901d7-f7f6-5332-a096-58221ff26547', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 5, 5, 'ንጉሥ ሆይ! አንተም የምትሞትና የምትፈርስ፥ ነገ ትልና ብስባሽ ትቢያ የምትሆን ሰው አይደለህምን።'),
  ('51d7b92e-51ae-5c98-a8cc-fb1769db0ee8', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 6, 6, 'ዛሬ ግን ለዘለዓለም እንደማይሞት ሰው ትመካለህ፤ ትኰራለህም።'),
  ('be326e46-3b7d-5c23-a999-1a3689bfcb7b', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 7, 7, 'አንተስ ዛሬ ደኅና ሁነህ የምትታይ ነገ ግን የምትሞት ሰው ነህ ይላል ሁሉን የሚችል እግዚአብሔር።'),
  ('05ddc695-7024-54e7-a408-6a86eeab2381', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 8, 8, 'ትእዛዜንና ቃሌን ብትጠብቅ ግን ማደሪያቸው ብሩህ ከሆነ፥ ዘውዶቻቸውም ከአማሩ፥ ዙፋኖቻቸውም የብርና የወርቅ ከሆኑ፥ በእነርሱም ላይ የሚቀመጡ ሰዎች ያጌጡ ከሆኑና ፈቃዴን ከአደረጉ ከከበሩ ነገሥታት ጋራ ቅድስት ከተማን አወርስሃለሁ።'),
  ('c4f45473-5f89-5496-a866-96fb81f30e4a', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 9, 9, 'በጎ ሥራን ለሚሠሩ ሰዎች የቀረበች ማደሪያ በምትሆን በከተማውም ውስጥ ደስ ይላችኋል።'),
  ('c6a78f20-c378-5e94-a38a-d34677dc690f', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 10, 10, 'ክፋት ለሚሠሩ ሰዎች ግን ክቡራን ነገሥታት ወደሚገቡባት ወደዚያች ከተማ ይገቡ ዘንድ አይገባቸውም።'),
  ('df9d00b2-9f17-537c-a29d-95f62eea1bb8', '52981f81-7af4-5080-abe0-722366da864d', 'fc51f009-92ee-5dba-acd2-658d6b04a6e0', 11, 11, 'ቃሌንና ሥርዐቴን አልጠበቁምና ይላል ሁሉን የሚችል እግዚአብሔር።”'),
  ('a607651a-8a4a-55af-a74a-488dba61c5ad', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 1, 1, 'የሜዶን መንግሥት ትጠፋለች፤ የሮም መንግሥት ግን በመቄዶንያ መንግሥት ላይ ፈጽማ ትጸናለች፤ የነነዌም መንግሥት በፋርስ መንግሥት ላይ ትጸናለች።'),
  ('01644b32-5963-5990-ad5d-07bb887a0d9b', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 2, 2, 'የኢትዮጵያ መንግሥትም በእስክንድርያ መንግሥት ላይ ትጸናለች፤ የሞዓብም መንግሥት በአማሌቅ ላይ ትጸናለች።'),
  ('b76d1e4d-4188-5acd-a56e-fd28db5f5c56', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 3, 3, 'ወንድም በወንድሙ ላይ ይነሣል፤ ይተላለቁም ዘንድ እንደ ተናገረ እግዚአብሔር በቀልን ያደርጋል።'),
  ('8cb61361-5b48-541b-aca5-8e53d30dfa89', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 4, 4, 'እንዲህም አለ፥ “መንግሥት በመንግሥት ላይ፥ ሕዝብም በሕዝብ ላይ፥ ሀገርም በሀገር ላይ ይነሣል።'),
  ('5b88ce57-a36c-5471-ac29-55ba4ac0e716', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 5, 5, 'ክርክርም ይሆናል፤ ሰልፍ፥ ረኀብ ፥ ቸነፈር፥ ንውጥውጥታ፥ ድርቅም ይሆናል፤ ሰላምና ፍቅርም ይጠፋልና የእግዚአብሔር መቅሠፍት በእርሷ ላይ ይወርዳል።'),
  ('f725de43-fe64-5718-a228-71d2df4a47ca', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 6, 6, 'ከምሥራቅ እስከ ምዕራብ እንደሚታይ መብረቅም የምታስፈራ የእግዚአብሔር ቀን በድንገት በደረሰች ጊዜ፥'),
  ('798966cc-e244-5265-ac4c-38b6cffa359e', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 7, 7, 'የዚያን ጊዜ ሰው ሁሉ እንደ ሥራውና እንደ እጁ ድካም፥ እንደ ሥራውም ፍሬ ይቀበላል፤ እርሱ እግዚአብሔር እንዲህ ብሏልና፥ በፍርድ ቀንና እግራቸው በሚሰነካከልበት ቀን እበቀላቸዋለሁ፥ ለጥፋት የሚቈጠሩበት ቀን ደርሷልና።'),
  ('f13e8037-cd4e-5b65-a7d1-1ff3068d681f', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 8, 8, '“የዚያን ጊዜ እግዚአብሔር በሕጉ የማይሄዱ ክፉ አድራጊዎችን በዘለዓለም ኵነኔ ያጠፋቸዋል፤ የይሁዳና የቆጵሮስ፥ የሰማርያና የደማስቆ፥ የባቢሎንም ሕዝብ፥'),
  ('3599736a-572b-5c6e-ac16-4eee1ea0c2c3', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 9, 9, 'በምዕራብ ደሴትም የሚኖሩ ሕንደኬና ኖባ፥ ሳባና ግብፅም፥ ኢትዮጵያም በእነርሱም የሚኖሩ ሁሉ።'),
  ('96ab9efc-74f7-575f-a6b4-d8ddb493be68', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 10, 10, 'ያንጊዜም ሰማይንና ምድርን የምገዛ፥ ክብርንና መወደድን የምሰጥ፥ የምገድልና የማድንም እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('32b80a51-fa04-5070-a322-65197a4261c6', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 11, 11, 'ፀሐይን የማወጣ፤ ወደ መግቢያውም የምልከው እኔ ነኝ፤ ክፉውንና በጎውንም የማመጣ እኔ ነኝ።'),
  ('157b56bb-6716-5587-aae1-edac52620403', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 12, 12, 'የደከማችሁበትን ገንዘብ፥ የላሞቻችሁንና የበጎቻችሁን መንጋም የሚበሉ የማታውቋቸውን አሕዛብ የማመጣ እኔ ነኝ።'),
  ('a49c39db-9612-5bed-a8f9-15f8ac8c3242', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 13, 13, '“ልጆቻችሁንም በፊታችሁ እየቀጠቀጡ ይማርኳቸዋል፤ እነርሱንም ማዳን አትችሉም። የእግዚአብሔርም መንፈስ ስላላደረባችሁ፥ የሰማችሁትንም የእግዚአብሔርን ትእዛዝ አልፈራችሁምና ወዛችሁንና ልምላሜያችሁን ይበላሉ።'),
  ('eb44b980-28f4-575f-af58-a926d949e292', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 14, 14, 'በአንተ ላይ የእግዚአብሔርን መንፈስ አያለሁና ብሎ ናቡከደነፆር ለነቢዩ ዳንኤል እንደ ነገረው የእግዚአብሔር መንፈስ ያደረበት ሰው ሁሉን ያውቃል።'),
  ('fcb6eea8-c4d2-5f69-af58-cd4b98b0928a', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 15, 15, 'የእግዚአብሔርም መንፈስ ያደረበት ሰው ሁሉን ያውቃልና የተሰወረው ይገለጥለታል፤ የተገለጠውንና የተሰወረውንም ሁሉ ያውቃል እንጂ ከእግዚአብሔር መንፈስ የሚሰወር የለም።'),
  ('b3c9ecb9-42ac-5066-ae5e-f5375c7a7d4a', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 16, 16, 'እኛ ግን ነገ የምንሞት ሰዎች ነንና ሰውረን የሠራነው ሥራ ሁሉ ይገለጣል።'),
  ('bb9e924c-b414-5152-ac82-014bdc586240', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 17, 17, 'ወርቅንና ብርንም በእሳት እንደሚፈትኑት የእግዚአብሔርን ትእዛዝ አልጠበቁምና ኃጥኣን እንዲሁ በኋለኛዪቱ ቀን ይፈተናሉ።'),
  ('15132463-718a-5df4-a158-41036689b934', '12a23260-7b9d-524f-a702-dcb09ba915e7', 'afbb34c3-b615-550f-acf0-63231cb54855', 18, 18, 'የዚያን ጊዜም የእስራኤል ልጆች ሁሉና የአሕዛብ ሁሉ ሥራዎቻቸው ይፈተናሉ።'),
  ('719f5adb-938f-5c38-ae13-76fb9b84af6f', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 1, 1, '“አባቱና እናቱ ለሞቱበት ልጅ እውነተኛ ፍርድ ስላልፈረዳችሁ እግዚአብሔር በእናንተ ላይ ይቈጣልና የእስራኤል ኀያላን ወዮላችሁ።'),
  ('613dcd17-9bbe-53db-a706-b845289f2cf6', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 2, 2, 'ጧትና ማታ ወደ መሸተኛ ቤት የምትሔዱና የምትሰክሩ፥ ፍርድንም የምታዳሉ፥ አባትና እናት የሞቱበትን ልጅና የባልቴቷን ፍርድንም የማትሰሙ፥ በኀጢአትና በመዳራትም የምትኖሩ ወዮላችሁ።”'),
  ('c13cfd79-f285-5c7a-a521-46e5acf6c175', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 3, 3, 'እግዚአብሔር የእስራኤልን ኀያላን እንዲህ ይላቸዋል፥ “በትእዛዜ ካልሄዳችሁ፥ ቃሌንም ካልጠበቃችሁ እኔ የምወደውንም ካልወደዳችሁ ወዮላችሁ!'),
  ('c9eb3753-bfa1-59f4-a7af-75d7ee62d652', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 4, 4, 'እኔም መቅሠፍትንና ጥፋትን፥ መከራንም አመጣባችኋለሁ፤ ነቀዝና ብልም እንደ በላው ትጠፋላችሁ፤ ፍለጋችሁም በአውራጃዎቻችሁ አይገኝም።'),
  ('fa12c521-9798-564d-a40c-1e0dbe773a52', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 5, 5, 'ሀገራችሁ ምድረ በዳ ትሆናለች፤ ቀድሞ ያያትም ሁሉ እጁን ያጨበጭባል፤ ይህች ሀገር በረከትንና መልካምን ሁሉ የተመላች አልነበረችምን? እግዚአብሔር፦ በሚኖሩባት ሰዎች ኀጢአት እንዲህ አደረጋትን?” እያለ በእርስዋ ይደነቃል።'),
  ('cf993f71-4fa5-57e5-ab35-0c045d99afae', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 6, 6, 'እግዚአብሔር በምድር ትቢያ እስኪያዋርዳት ድረስ ልቧን አኵርታለችና፤ ራሷንም ከፍ ከፍ አድርጋለችና፤ አንገቷንም አስረዝማለችና በውስጥዋም ስለሚኖሩት ሰዎች ትዕቢት ምድረ በዳ ሆናለችና፥ እሾህና አሜኬላም በቅሎባታልና ወዮላት።'),
  ('cf868bea-164f-5b62-a22c-c6619d5a7206', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 7, 7, 'ሙጃንና አስተናግርንም አበቀለች፤ ምድረ በዳና በረሃም ሆነች፤ አውሬዎችም በውስጧ ይኖሩባታል።'),
  ('b63582b0-777d-5e36-a9d5-7d9574dfb905', 'd4caca93-f995-550f-a30e-8ffa3e31197d', 'f379d6cd-2f99-51f8-a858-3e4a1ca59716', 8, 8, 'በውስጥዋም ለሚያልፉ የምታስፈራ ሆነች፤ የእግዚአብሔር ቍጣ ወድቆባታልና፥ ስለ ልቡናዋ ትዕቢትና ስለሚኖሩባት ሰዎችም ክፋት ከመዓቱ ጽዋዕ ጠጥታለችና።'),
  ('fb843057-b011-5400-a224-12cfcd48f3db', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 1, 1, 'የመቄዶን ሰዎች፥ አትመኩ፤ አማሌቃውያንም፥ አንገታችሁን አታስግጉ፤ የሚበቀላችሁ እግዚአብሔር አለና።'),
  ('cc12355a-88f6-55b2-ad40-6cdc5f1aba71', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 2, 2, 'እስከ ሰማይ ከፍ ከፍ ብትሉ እስከ ሲኦል ትወርዳላችሁና።'),
  ('eb485ef5-8412-513e-a4cf-dd1128ab5546', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 3, 3, 'እስራኤል ቀድሞ በሞዓብና በሜዶን መንግሥት ወደ ግብፅ ሀገር በገቡ ጊዜ “ትገዳደሩት ዘንድ በእግዚአብሔር መገዳደር አይገባምና አትመኩ” አለ።'),
  ('85994827-3c7d-5671-a26f-cb04a53bf7b0', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 4, 4, '“አንተም ይስማኤላዊ የባርያ ልጅ! ያንተ ወዳልሆነው አንገትህን ለምን ታስረዝማለህ? በምድርስ ይፈረድባት ዘንድ በተነሣ ጊዜ በፍርድ ቀን እግዚአብሔር እንደሚፈርድብህ አታስብምን?'),
  ('89715a4b-157d-5c8d-a4f9-aba48d61caed', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 5, 5, 'የዚያን ጊዜም እንደ እጅህ ሥራ ትቀበላለህ፤ ልቡናህንስ ለምን ከፍ ከፍ ታደርጋለህ? አንገትህንስ ለምን ታስረዝማለህ? ይላል ሁሉን የሚገዛ እግዚአብሔር።'),
  ('b0d3a7bf-847e-511a-a126-8cac3c521302', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 6, 6, 'ወገኖችህ ያልሆኑትን አንተ እንደ ተገዳደርህ እኔም አንተን እገዳደርሃለሁ፤ ክፉ ትሠራ ዘንድ የወደድኸውን ታደርጋለህና በላክሁህም ቦታ ቸል እልሃለሁ።'),
  ('ae52acdc-219b-5427-aba7-9414958f37eb', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 7, 7, 'እኔም በአንተ ላይ እንዲሁ አደርጋለሁ ይላል ሁሉን የሚችል እግዚአብሔር። አንተም በጎ ብታደርግ፥ እኔ የምወደውንም ብትወድድ የለመንኸኝን ሁሉ እሰማሃለሁ።'),
  ('05e5fd84-6d65-5864-acee-05dd42946803', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 8, 8, 'ፈቃዴንም ብታደርግ ፈቃድህን አደርጋለሁ፤ ጠላቶችህንም እቃወምልሃለሁ፤ ሥራህን፥ ዘርህንና ልጆችህንም እባርክልሃለሁ።'),
  ('3bcccec3-22a8-5701-ad8b-0b0736742be6', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 9, 9, 'የላሞችህንና የበጎችህን መንጋ እባርክልሃለሁ፤ በትእዛዜም ብትሄድ፥ እኔም የምወደውን ብታደርግ እጅህን ያኖርህበትን ሁሉ እባርካለሁ ይላል ሁሉን የሚችል እግዚአብሔር።'),
  ('09c1be4e-7633-536d-a94e-f20b91496140', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 10, 10, '“ፈቃዴን ባታደርግ፥ በትእዛዜና በሕጌ ባትሔድ ግን ቀድሞ የተነገረው ይህ ሁሉ መከራ ያገኝሃል፤ በትእዛዜ አልታገሥህምና በሕጌም አልሔድህምና ሁልጊዜ ከምትመጣብህ ቍጣዬ ማምለጥ አትችልም።'),
  ('31df719c-0625-55a4-a467-133d5b3002e8', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 11, 11, 'እኔ የወደድሁትንም አልወደድህምና፤ እኔም ካለመኖር ወደ መኖር አምጥቼ የፈጠርሁህ ሲሆን እኔን ከማመስገንና ከማምለክ ቸል ብለሃል።'),
  ('190ec024-967d-5734-a9d2-729320bef716', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 12, 12, 'የወደድኸውን ሁሉ ታደርግ ዘንድ በበታችህ በአሉት ዘንድ ክብርንና ጌትነትን ሰጠሁህ። ትገድልና ታድን ዘንድ፥ ትሠራና ታፈርስም ዘንድ፥ ታከብርና ታዋርድም ዘንድ፥ ከፍና ዝቅም ታደርግ ዘንድ የአንተ ነበር።'),
  ('f19e8a2a-2a57-5e32-a932-f3fca4682f56', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 13, 13, 'የእግዚአብሔርንም ፈቃድ ብታደርግ፥ በትእዛዙም ብትሔድ፥ በጌትነቱ ከእርሱ ጋራ ደስ ይልህ ዘንድ ቅድስት ሀገርንም ከወረሱ ሰዎች ጋር ተካፋይ ትሆን ዘንድ ይወድድሃል።'),
  ('8938d202-9a17-55e7-a1ec-5e7152a917c2', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 14, 14, 'እርሱ እንዲህ ብሏልና፦ ቢታገሡኝ ክብርንና መወደድን አወርሳቸዋለሁ፥ በቤተ መቅደሴም ደስ አሰኛቸዋለሁ፤ እንደ ቍርባን መሥዋዕትም የተመረጡና የተወደዱ ይሆናሉ ይላል ሁሉን የሚችል እግዚአብሔር።”'),
  ('ca2ecd07-82d4-57d6-ae55-cc58d24504f0', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 15, 15, 'ከሞት ወደ ሕይወት ትሻገሩ ዘንድ መልካም ማድረግንና የድኅነት መንገድን ቸል አትበሉ።'),
  ('81003ebe-a1ec-5790-a66d-461580b61c80', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 16, 16, 'በጎ ሥራ የሚሠሩትን ግን እግዚአብሔር ከክፉ ሁሉ እንደ ጠበቀው እንደ ኢዮብ ባሮቹ ይሆኑ ዘንድ እግዚአብሔር በበጎው ሁሉ ይጠብቃቸዋል።'),
  ('df51b6a7-8a12-598e-a7cb-c8abec26e41a', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 17, 17, 'ነገሥታቱን በገደላቸው ጊዜ እንደ አዳነው እንደ አብርሃም፥ ጣዖት ያስመልኩት ዘንድ በማታና በጧት በቀንና በሌሊት ሰውነቱን ሲያውኳት ከነበሩ፥ አብርሃም ከኖረባቸው ከከናኔዎን እጅና ከፈርዖን እጅ እንዳዳነው እንደ ሙሴም፤'),
  ('0c5cc187-ee3e-5544-a914-cc4c92dbc194', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 18, 18, 'እርሱ ግን የእነርሱ ወደ ሆኑ ጣዖታቱ ሲስቡት እንቢ እያለ ይታገሥ ነበረ።'),
  ('fca2baf5-9b93-5b7b-aa17-30ff12b83f92', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 19, 19, 'እርሱም እንቢ ይላቸው ነበረ፤ የፈጠረው እግዚአብሔርንም ያመልከው ነበረ። ከልጅነቱ ጀምሮ እርሱን ያመነው አብርሃም ለእግዚአብሔር የታመነ ወዳጁ ነበረና።'),
  ('90dcaefb-84bd-5ca9-a1c9-03aa0d461e70', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 20, 20, 'እግዚአብሔርን ፈጽሞ ይወደው ነበርና እስኪሞት ድረስ እግዚአብሔርን ማምለክን አላጓደለም፤ እስከሚሞትበትም ቀን ድረስ ከትእዛዙ አልተላለፈም፤ የእግዚአብሔርንም ትእዛዝ ይጠብቁ ዘንድ ለልጆቹ አስተማረ።'),
  ('3037610c-cc35-5310-a40c-8b561e9abf5b', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 21, 21, 'እነርሱም አባታቸው አብርሃም እንደ አደረገ ከአግዚአብሔር ትእዛዝ አልተላለፉም፤ “በምድር አብርሃም የሚባል ወዳጅ አለኝ” ብሎ ለመላእክት እንደ ነገራቸው እግዚአብሔር ስለ እነርሱ የተናገረላቸው ባሮቹ የአብርሃም ልጆች ይስሐቅና ያዕቆብ ከእግዚአብሔር ሕግ አልተላለፉም።'),
  ('cfa55439-0103-5b60-a35c-760f7cf4df1d', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 22, 22, '“አብርሃም ወዳጄ ነው፤ ይስሐቅም ባለሟሌ ነው፤ ያዕቆብም ልቡናዬ የወደደችው ነው፤ በእነርሱም ዘንድ ተመሰገንሁ ይላል ሁሉን የሚችል እግዚአብሔር፤”'),
  ('d84429f1-4dfa-5fbc-aa8d-dabc30188d69', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 23, 23, 'የእስራኤልንም ልጆች ፈጽሞ ሲወድዳቸው እነርሱ ግን ዘወትር ሲያሳዝኑት ኖሩ፤ እርሱም ሲታገሣቸው፥ በምድረ በዳም መና ሲመግባቸው ኖረ።'),
  ('85bbaf33-a90b-5ede-ae7f-6390702ad266', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 24, 24, 'ልብሶቻቸውም አላረጁም፤ የዕውቀት እንጀራ መናንም ተመግበዋልና እግሮቻቸው አልነቁም።'),
  ('ed979867-19f1-5b55-a7fb-2327a0ff64c2', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 25, 25, 'ልቡናቸው ግን ሁል ጊዜ ከእግዚአብሔር ይርቅ ነበር፤ ከጥንትም ጀምሮ ክፋትን የሚሠሩ ነበሩና ለመዳን ተስፋ አልነበራቸውም።'),
  ('131076d3-8318-5458-a69b-fdd50c90ec4e', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 26, 26, 'እንደ ጠማማ ቀስትም ሆኑ እንጂ በአማረ አኗኗራቸው እግዚአብሔርን እንዳገለገሉት እንደ አባቶቻቸው እንደ አብርሃምና እንደ ይስሐቅ፥ እንደ ያዕቆብም አልሆኑም፤ በጣዖታቸው በተራራውና በኰረብታው ላይ ሁልጊዜ ያሳዝኑት ነበር፤ በተራራው ላይ፥ በዋሻውና በዛፎቹም ሥር ይበሉ ነበር።'),
  ('f7c27de8-db54-5e5b-a59c-644acb39c517', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 27, 27, 'ፍሪዳ ያርዱ ነበር፤ መሥዋዕትም ይሠዉ ነበር፤ በእጃቸውም ሥራ ደስ ይላቸው ነበር፤ ተረፈ መሥዋዕቱንም ይበሉ ነበር፤ የመጠጡንም ቍርባን ፍላቂ ይጠጡ ነበር፤ ከአጋንንትም ጋራ ይዘፍኑና ይጫወቱ ነበር።'),
  ('e980f816-4aca-5387-ab03-7810c1374f8b', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 28, 28, 'አጋንንትም ጨዋታቸውንና ዘፈናቸውን ሁሉ፥ ስካራቸውንም ሁሉ ያደንቁላቸው ነበር፤ ያለልክም ዝሙትን ይሠሩ ነበር፤ እግዚአብሔር የማይወደው ቅሚያንና ስስትንም ያደርጉ ነበር።'),
  ('fc8b2645-51b6-50aa-a441-d32ed9745ee4', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 29, 29, 'ለከነዓን ጣዖት ለበዓልና ለምድያም ጣዖት፥ ለኤሎፍሊ ጣዖታት ለዳጎንና ለአጵሎን፥ ለአርጤማዴስና ለሰራጵዮን፥'),
  ('519f35a0-64a8-536b-aeb2-eb53529ff668', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 30, 30, 'በዙሪያቸውም ላሉ ለአሕዛብም ጣዖታት ሁሉ መሥዋዕት ይሠዉ ነበር። አሕዛብም እንደሚያደርጉት በአዩትና በሰሙት ሁሉን ያመልኩ ነበር፤ አሕዛብም የሚያደርጉትን ጨዋታቸውንና ዘፈናቸውን፥ ድንፋታቸውንም ያደርጉ ነበር።'),
  ('7c8e3f2e-d3c8-5a2c-a2f1-c97c04489bed', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 31, 31, 'እግዚአብሔርን እናመልከዋለን የሚሉ የእስራኤል ሕዝብ እንደዚሁ ያደርጉ ነበር። የእግዚአብሔርን ትእዛዛት ይጠብቁ ዘንድ፥ ጣዖትንም ከማምለክ ይርቁ ዘንድ፥'),
  ('74a00fe5-819a-5846-ac35-a57a45adfdd9', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 32, 32, 'የሁዳዱን እህል ከመገባቸው፥ ወደ ምድሩም አዝመራ ካወጣቸው፥ ከማጓም ማሩን ከአጠገባቸው፥ መናውንም ከመገባቸው፥ ካባቶቻቸው ፈጣሪ በቀር ሌሎች አማልክትን እንዳያመልኩ ሙሴ በኦሪት የነገራቸውን ትእዛዙንና ሕጉን ግን አያደርጉም ነበር።'),
  ('3a43593d-54ba-566d-acfc-dd0eaf37a8c7', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 33, 33, 'የተመኙትንና የፈለጉትን አይነሳቸውም ነበር፤ እርሱም አምላካቸው ነውና የወደዱትን ይመግባቸው ነበር።'),
  ('72ba416d-f5dc-5e89-ac0d-7a98f1713630', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 34, 34, 'እነርሱ ግን እግዚአብሔርን ማሳዘን አልተዉም፤ ደስ ባሰኛቸው ጊዜ እግዚአብሔርን ይዘነጉት ነበር።'),
  ('a2a47e17-6799-5c73-a504-4704463a62ea', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 35, 35, 'መቅሠፍትንም ባመጣባቸው ጊዜ ወደ እርሱ ይጮሁ ነበር፤ ካገኛቸውም መከራ ያድናቸው ነበር፤ ዳግመኛም በግልጥ ደስ ይላቸው ነበር፤ ብዙ ዘመንም ይኖሩ ነበር።'),
  ('8f01eccf-ec1d-5789-ae5d-bc3232c3ebf7', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 36, 36, 'ወዲያውም እንደ ቀድሞው እግዚአብሔርን ያሳዝኑት ዘንድ ፈጽመው ልባቸውን ይመልሱ ነበር፤ ያጠፏቸውም ዘንድ በዙሪያቸው ያሉ አሕዛብን ያስነሣባቸው ነበር፤ አስጨንቀውም ያስገብሩአቸው ነበር።'),
  ('06e0978a-0223-5309-a56e-e31601b03594', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 37, 37, 'ዳግመኛም ተመልሰው ወደ ፈጣሪያቸው ወደ እግዚአብሔር ፈጥነው ይጮሁ ነበር።'),
  ('4281454b-962f-51e4-a76d-b7eae979031f', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 38, 38, 'እርሱም ይቅር ይላቸው ነበር፤ በአማረ አኗኗራቸው ከጥንት ጀምሮ እግዚአብሔርን ስለ አገለገሉትና መሐላውን ስለ አጸናላቸው ስለ አባቶቻቸው ስለ ኖኅ፥ ስለ አብርሃምና ስለ ይስሐቅ፥ ስለ ያዕቆብም ነው እንጂ ስለ ራሳቸው አይደለም።'),
  ('978d57f1-04e5-510e-a3a0-e4a77d7bc335', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 39, 39, 'እንደ ሰማይ ከዋክብትና እንደ ባሕር አሸዋ ዘራቸውን ያበዛ ዘንድ የወደዱትንና ትእዛዙን የጠበቁትን ወደዳቸው።'),
  ('0cc998c2-deca-5045-a002-e4c9bf768c29', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 40, 40, 'እንደ ባሕር አሸዋ ያላቸው በሙታን ትንሣኤ ጊዜ ከእስራኤል ልጆች ተለይተው ወደ ገሃነም የሚገቡ የኃጥኣን ነፍሳት ናቸው።'),
  ('686d46b2-9cae-5bde-af9c-20b4b49dc21e', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 41, 41, 'በሰማይ ላይ እንደሚያበሩ ከዋክብት ናቸው የተባሉት ግን ከእስራኤል ልጆች ወገን የጻድቃን ነፍሳት ናቸው። እግዚአብሔር አብርሃምን እንዲህ ብሎታልና፥ “ሌሊት ወደ ሰማይ እይ፤ መቍጠርም ትችል እንደ ሆነ የሰማይን ከዋክብት ቍጠራቸው፤ እንደዚሁም ልጆችህ ጻድቃን እንደ ሰማይ ከዋክብት በመንግሥተ ሰማይ ያበራሉ።'),
  ('55b42c6f-836a-527a-a3e6-f4319fc985f0', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 42, 42, '“ዳግመኛም ወደ ባሕሩና ወደ ወንዙ ዳርቻ ተመልከት፤ በአሸዋው ውስጥ ያለውንም እይ፤ መቍጠርም ትችል እንደ ሆነ ቍጠር፤ በሙታን ትንሣኤ ጊዜ ወደ ገሃነም የሚወርዱ ልጆችህ እንደዚሁ ናቸው፤”'),
  ('fc387e49-0188-5416-a60e-6f94e22e495d', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 43, 43, 'አብርሃምም በእግዚአብሔር አመነ፤ ስለዚህም ጽድቅ ሆኖ ተቈጠረለት፤ በምድርም ተስፋው ደረሰለት፤ ሚስቱ ሳራም ከአረጀች በኋላ ወንድ ልጅ ይስሐቅን አገኘች።'),
  ('2ecaa245-7b94-5847-a4f1-23d3f366271f', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 44, 44, 'ዳግመኛም ስለ እምነቱ በሰማያት መንግሥትን ያገኛል። ሙታን እንደሚነሡ፤ በጎ ሥራን የሠሩም ወደ ዘለዓለም ሕይወት፥'),
  ('6151dc59-1ab0-5433-a525-10da93775742', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 45, 45, 'ክፉ የሠሩም በሙታን ትንሣኤ ጊዜ ወደ ዘለዓለም ቅጣት እንደሚሔዱ አምኖአልና። በጎ ሥራ የሠሩ ጻድቃን ግን ከእርሱ ጋር ለዘለዓለም ይነግሣሉ።'),
  ('6c0cc280-b037-57ce-a310-1b29bf34c2e9', 'd8f8619f-5854-59f0-a4ad-51958483def1', 'df204e58-ca33-574a-a80f-5167276057d6', 46, 46, 'ክፉ የሠሩም ለዘለዓለም ይፈረድባቸዋል አሜን፥ አሜን።'),
  ('46e4d6e3-5c54-5018-a27a-d0bc1581c5f5', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 1, 1, 'መቃቢስ አይሁድን በሶርያ በሁለቱ ወንዞች መካከል አግኝቶ ከኢያቦቅ ጀምሮ እስከ ኢየሩሳሌም አደባባይ ድረስ በሸለቆዎቻቸው እንደ ገደላቸው፥ ቅድስቲቱንም ከተማ እንዳጠፋት የሚናገር መጽሐፍ ይህ ነው።'),
  ('677afb5e-28e4-5f08-adea-3bcae771b000', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 2, 2, 'ከሰማርያ ጀምሮ እስከ ኢየሩሳሌም አደባባይ ድረስ፥ እስከ አውራጃዋም ሁሉ ድረስ ሰፍረዋልና ከጥቂቶች በቀር ሳያስቀሩ በጦር ገደሉ። ኤዶማውያንና ሶርያውያን፥ አማሌቃውያንም የኢየሩሳሌምን ከተማ ካጠፋው ከሞዓብ ሰው ከመቃቢስ ጋር አንድ ሆነዋልና።'),
  ('ccf0f0dc-9f44-578d-a9ad-ff1afb195205', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 3, 3, 'የእስራኤልም ልጆች በበደሉ ጊዜ ሞዓባዊውን መቃቢስን አስነሣባቸው፤ እርሱም ሁሉን በሰይፍ ገደላቸው።'),
  ('00dbf5ef-3558-5445-a82f-ec62b8cebb33', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 4, 4, 'ስለዚህም ነገር የእግዚአብሔር ጠላቶች በቅድስት ከተማው ላይ ደነፉ፤ በወንጀላቸውም ተማማሉ።'),
  ('11fe5adb-fda9-56ad-a2c2-5c36c3b88437', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 5, 5, 'ኤዶማውያንና ኢሎፍላውያንም ሰፈሩ፤ የእግዚአብሔርን ቃል ስለ ተገዳደሩ እርሱ ልኳቸዋልና የእግዚአብሔርን ከተማ ይበቀሉ ጀመር።'),
  ('941326d8-f747-59f5-a36a-68b2fde1033a', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 6, 6, 'የዚያም የመቃቢስ ሀገሩ የሞዓብ ሬማት ናት፤ ከሀገሩም በኀይል ተነሥቶ አብረውት ከአሉ ሰዎች ጋራ ተማማለ።'),
  ('e6648819-348d-5a9c-a563-968b305bba97', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 7, 7, 'የእግዚአብሔርንም ከተማ ያጠፉ ዘንድ በመስጴጦምያ-ጌላቡሄ ሸለቆዎች እስከ ሶርያ ድረስ ሰፈሩ፤ በዚያም ኢሎፍላውያንንና አማሌቃውያንን ለመነ፤ በወንጀልም ከእርሱ ጋራ አንድ ይሆኑ ዘንድ ብዙ ወርቅንና ብርን፥ ፈረሶችንና ሠረገላዎችን ሰጣቸው።'),
  ('79df55e2-847e-5441-aabf-0ae2b0af9c92', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 8, 8, 'በአንድነትም መጥተው አንባዪቱን ናዷት፤ በውስጧ የሚኖሩ ሰዎች ደምንም እንደ ውኃ አፈሰሱ።'),
  ('bae1b8ff-2a83-5175-a7bb-8b9b836558ae', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 9, 9, 'ኢየሩሳሌምንም እንደ ተክል ጠባቂ ጎጆ አደረጓት፤ በውስጧም ድምፅ አሰማባት፤ እግዚአብሔርም የማይወድደውን የክፋት ሥራ ሁሉ አደረገ፤ ጽድቅንና ቅድስናን የተመላች የእግዚአብሔርንም ከተማ አረከሱ።'),
  ('74e165f3-6f21-5e32-aba8-0e6d2779436c', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 10, 10, '“የባሮችህን እሬሳ ለሰማይ ወፎች ምግብ አደረጉ። የጻድቃንህንም ሥጋ ለምድረ በዳ አራዊት መብል አደረጉ።”'),
  ('173a222a-436d-5a7d-ab0a-9aff77e7c3c2', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 11, 11, 'ባልቴቲቱንና የሙት ልጁን ቀሙ፤ ሰይጣን እንዳስተማራቸው እግዚአብሔርን ሳይፈሩ አድርገዋልና ኵላሊትንና ልቡናን የሚመረምር እግዚአብሔር እስኪቈጣ ድረስ በፀነሱ ሴቶች ሆድ ያለውን ፅንስ አወጡ።'),
  ('dad9e767-ada7-5b32-a129-9394444797aa', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 12, 12, 'በእግዚአብሔር ሕዝብም ላይ ክፉን ስለ አደረጉ ደስ እያላቸው ወደ ሀገራቸው ተመለሱ፤ ከቅድስት ከተማ የማረኩትንም ምርኮ ወሰዱ።'),
  ('d5d2a24c-e7b6-54a7-a8f7-072499fe7b41', '2f76e6ba-4cc1-51e3-a928-5736026982ce', '276c001e-f228-5617-a44a-d0a5f9005f57', 13, 13, 'ተመልሰውም ወደ ቤታቸው በገቡ ጊዜ ደስታን፥ ዘፈንንና ጭብጨባን አደረጉ።'),
  ('300059d1-4579-55fe-a889-dce805b3acc9', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 1, 1, 'ረአይ የሚሉት ነቢይ እንዲህ አለው፥ “በጊዜው ብርሃን ዛሬ ጥቂት ደስ ይበልህ፤ የእስራኤል ቅዱስ እግዚአብሔርም ባልተጠራጠርኸው መቅሠፍት ይበቀልህ ዘንድ አለው።'),
  ('269251ef-83c0-59f2-a809-21790015e51d', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 2, 2, 'ፈረሶች ፈጣኖች ናቸው፤ ስለዚህም በሩጫ አመልጣለሁ ትላለህን?'),
  ('edf0ce1b-e15a-5dfa-ab89-e9f1ea92e0a5', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 3, 3, 'እኔስ የሚከተሉህ ሰዎች ከአሞሮች ይፈጥናሉ፤ ከጥፋትና ከሚመጣብህ ከእግዚአብሔር ቍጣ አታመልጥም እልሃለሁ።'),
  ('eceda6e6-1c78-5b80-ae7f-935380d968d9', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 4, 4, 'የብረት ልብስ እለብሳለሁ፤ የጦር መወርወርና የቀስትም መንደፍ አይችለኝም ትላለህን? የእስራኤል ቅዱስ እግዚአብሔርም የምበቀልህ በጦር መወርወር አይደለም ይላል፤ ነገር ግን ከጦር መወርወርና ከቀስት ንድፈት የሚከፋ ጽኑ የልብ በሽታን፥ እከክንና ቍርጥማትን አመጣብሃለሁ፤'),
  ('e157674c-362e-562a-a7ed-6a8fd9b671a2', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 5, 5, 'ቍጣዬን አነሣሥተሃልና፥ የልብ በሽታን አመጣብሃለሁ፤ የሚረዳህም ታጣለህ፤ ስም አጠራርህንም ከምድር እስካጠፋው ድረስ ከእጄ አታመልጥም።'),
  ('02795e8a-08f5-529a-a200-32700b920e03', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 6, 6, 'አንገትህን አደንድነሃልና ራስህንም በከተማዬ ላይ ከፍ ከፍ አድርገሃልና፥ ይህን ነገር እንደ ዐይን ጥቅሻ ፈጥኜ ባደረግሁ ጊዜ እኔ ፈጣሪህ እግዚአብሔር እንደ ሆንሁ ታውቀኛለህ፤ አንተ በፊቴ እሳት እንደሚበላው በነፋስ ፊት እንዳለ ሣር ነህና፥ ዓውሎ ነፋስም ከምድር አፍሶ እንደሚበትነው ትቢያ ነህና አንተ በእኔ ዘንድ እንዲሁ ነህ።'),
  ('df1252ae-5ecc-573c-ae6a-b9e57c0c6021', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 7, 7, 'ቍጣዬን አነሣሥተሃልና፥ ፈጣሪህንም አላወቅህምና እኔም የአንተ የሆነውን ሁሉ ቸል እለዋለሁ፤ በአንባህም ሁሉ ላይ የሚጠጋውን አላስቀርም።'),
  ('df589d93-6035-5600-a5a0-22dceddad4af', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 8, 8, 'አሁንም ከሠራኸው ክፋት ሁሉ ተመለስ፤ ብትመለስ፥ በእግዚአብሔርም ፊት ፈጽመህ በልቅሶና በኀዘን ብትናዘዝ፥ በንጹሕ ልቡናም ወደ እርሱ ብትለምን በፊቱ የሠራኸውን ኀጢአትህን ሁሉ እግዚአብሔር ይቅር ይልሃል።”'),
  ('29a714f8-b272-513d-ad43-7fc950eb9384', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 9, 9, 'የዚያን ጊዜም መቃቢስ ትቢያ ለብሶ ስለ ኀጢአቱ በእግዚአብሔር ፊት አለቀሰ። እግዚአብሔር ተቈጥቶታልና።'),
  ('c263aaee-33ea-56e1-aec5-97c5e1dc8f3d', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 10, 10, 'እግዚአብሔርም በነቢዩ ቃል የተናገረውን መቅሠፍት እንደማያዘገይ ዐወቀ። ዐይኖቹ የተገለጡ ናቸውና አይተኛም፤ ዦሮውም የተከፈተ ነውና ቸል አይልም፤ የተናገረውንም ቃል ሐሰት አያደርግምና በአንዲት ጊዜ እንደ ዐይን ጥቅሻ ፈጥኖ ያደርጋታል።'),
  ('41cfa22d-b8c2-5700-a54e-f202b8582ce0', '49072399-1063-557a-a045-873ce4e2acbe', '59491c32-1775-5b7c-a3c5-44459f67a308', 11, 11, 'ልብሱንም ጥሎ ማቅ ለበሰ፤ በራሱም ላይ ትቢያ ነሰነሰ፤ ስለ ሠራውም ክፋት በፈጣሪው በእግዚአብሔር ፊት ጮኸ፤ አለቀሰም።'),
  ('8fd32ca1-0e93-52d2-aa88-3730c390d791', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 1, 1, 'የሞዓብ ሬማት ለሶርያ ቅርብ ናትና ነቢዩ ነገረው።'),
  ('c8e5410c-0bc1-5b54-ac15-fede83b7d3b4', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 2, 2, 'ጕድጓድም ቈፍሮ እስከ አንገቱ ገባ፤ መራራ ልቅሶንም አለቀሰ፤ በእግዚአብሔር ፊት ስለ ሠራው ኀጢአቱም ንስሓ ገባ።'),
  ('d74af4a8-db89-59f8-a3fb-bcb7d622b866', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 3, 3, 'እግዚአብሔርም ነቢዩን እንዲህ አለው፤ “ከይሁዳ ሀገር ወደ ሬማት ወደ ሞዓቡ ሹም ወደ መቃቢስ ተመለስ። እግዚአብሔርም እንዲህ ይላል በለው፦ በኀይሌ ጽናትና በሠራዊቴ ቅድስቲቱን ከተማ አጠፋኋት እንዳትል ከተማዬን ታጠፋ ዘንድ የአንተ ፈጣሪ እኔ እግዚአብሔር በፈቃዴ ላክሁህ እንጂ ይህን ነገር ያደረግኸው አንተ አይደለህም፤'),
  ('df50af69-8788-520e-a8fe-fd9a105868da', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 4, 4, 'በስስትዋ ሁሉ፥ በክዳትዋና በሴሰኝነትዋም አሳዝናኛለችና።'),
  ('3d4e1916-4443-5830-a75b-f362bbf00479', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 5, 5, 'እኔም ቸል ብዬ በአንተ እጅ አሳልፌ ሰጠኋት፤ አንገትህን ስለ አደነደንህ፥ ከተማዪቱንም በእጄ ብርታት ከበብኋት ስለምትል ስለ አንተ አይደለም። አሁንም ስለ ወለድሃቸው ልጆችህ እግዚአብሔር ኀጢአትህን ይቅር አለህ።'),
  ('b6ec9a4f-538e-5ba8-a832-2fb088fd2a51', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 6, 6, 'አሁንም በፍጹም ልቡናህ ጨክነህ ንስሓ ግባ። የሚጠራጠሩ ሰዎች ንስሓ ለመግባት አይጨክኑምና ተጠራጣሪ አትሁን።'),
  ('dedfae98-5546-53e9-a8ad-f19486f73aa0', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 7, 7, 'ነገር ግን በፍጹም ልቡናቸው ንስሓ የሚገቡ፥ ስለ ክፋታቸውም ንስሓ በገቡበት ሁሉ ወደ ጥመትና ወደ ኀጢአት የማይመለሱ ሰዎች ብፁዓን ናቸው።'),
  ('3f14390c-8fa9-5ae6-ada9-69a088331e74', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 8, 8, 'በልቅሶና በኀዘን፥ በብዙ ልመናና በስግደትም ወደ ፈጠራቸው ወደ እግዚአብሔር ለመመለስ የሚጨክኑም ብፁዓን ናቸው፤ ንስሓ የገቡትን ከሳታችሁ በኋላ ንስሓ የገባችሁ እናንተ የእኔ ናችሁ ብሏቸዋልና፤'),
  ('78ad6109-b102-58aa-a025-eb4b6b35ee21', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 9, 9, 'ትዕቢተኛውንም ከሳተ በኋላ በንስሓ ወደ እርሱ በተመለሰ ጊዜ ስለ ፍርሀትህና ስለ ድንጋጤህ ኀጢአትህን ይቅር እልሃለሁ አለው፤ የአባትን ኀጢአት በልጆች ላይ እስከ ሦስተኛና እስከ አራተኛ ትውልድ የማመጣ፥ ለሚወድዱኝ፥ ሕጌንም ለሚጠብቁ ግን ለእነርሱ እስከ ሺህ ትውልድ ድረስ ምሕረትን የማደርግ ፈጣሪህ እግዚአብሔር እኔ ነኝና።'),
  ('70ba835a-7c3f-5fef-a35f-a77e9e6d6bfc', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 10, 10, 'አሁንም ስለ ወለድኻቸው ስለ እነዚህ ልጆች ከአንተ ጋራ ያለውን ቃል ኪዳኔን እጠብቃለሁ፤ ስለ ሠራኸው ኀጢአትህም ያደረግኸውን ንስሓ እቀበላለሁ ይላል ሁሉን የሚችል የእስራኤል ቅዱስ እግዚአብሔር።”'),
  ('1532c6f1-d951-54e4-a447-0662866ccd22', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 11, 11, 'ያንጊዜም ከጕድጓዱ ወጣ፤ “እኔ እግዚአብሔርን አሳዝኜዋለሁና የወደድኸውን አድርገኝ እንጂ ከአንተ እንዳልለይ እግዚአብሔር እንዲህና እንዲህ ያድርገኝ ብሎ ለነቢዩ ሰገደ፤ ለእኛ ሕግ የለንምና እንደ አባቶች በትእዛዙ አልሄድሁም፤ አባቶቻችንም እንዳስተማሩን ጣዖት እንደምናመልክ አንተ ታውቃለህ።'),
  ('6078512d-78ea-512b-a587-3761f4d5d47f', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 12, 12, 'እኔ በኀጢአቴና በልቡናዬ ትዕቢት የሔድሁ፥ በአንገቴ ደንዳናነትም ፈጣሪዬን ያሳዘንሁ ኀጢአተኛ ነኝና። እስከ አሁንም ድረስ የእግዚአብሔርን ነቢያት ቃል አልሰማሁም ነበር፤ ባዘዘኝም በሕጉና በትእዛዙ አልኖርሁም።”'),
  ('3df629d9-94c0-5b57-a269-f3f7ff60f8c8', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 13, 13, 'ነቢዩም መልሶ፥ “ከእናንተ አስቀድሞ ከወገናችሁ ኀጢአቱን የታመነ የለምና ዛሬ ንስሓህን እንደ ተቀበለ ዐወቅሁ” አለ።'),
  ('0b91ceea-3755-5c51-a075-9f4d861c9c55', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 14, 14, 'ከእንግዲህ ወዲያ ግን ጣዖት ማምለክን ተው፤ መመለስህ እውነተኛ ይሆን ዘንድ እግዚአብሔርን ወደ ማወቅ ተመለስ፤ ከነቢዩም እግር በታች ሰገደ፤ ነቢዩም አነሣው፤ የሚገባውንም በጎ ሥራ ሁሉ አዘዘው።'),
  ('ce287c5a-b8e4-56a8-aa75-d2f068ae2473', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 15, 15, 'እግዚአብሔርም እንዳዘዘው አደረገ፤ ወደ ቤቱም ተመለሰ።'),
  ('635e38cf-e091-5ec8-ad82-3c733c6d902f', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 16, 16, 'ያም መቃቢስ አእምሮውን አስተካከለ፤ ከቤቱም ጣዖቱንና ጥንቆላውን፥ ጣዖት የሚያመልኩ ሰዎችንና ሟርተኞችን፥ ጠንቋዮችንም አስወገደ፤'),
  ('5895bf08-eebf-5825-a094-530f97700485', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 17, 17, 'ከኢየሩሳሌም ያመጣቸውንም የምርኮ ልጆች አባቶቻቸው እንደሚያደርጉ የእግዚአብሔርን ትእዛዝ ሁሉ፥ ሥርዐቱንና ሕጉንም ያደርጉ እንደ ሆነ ጧትና ማታ ይመረምራቸው ነበር።'),
  ('6d252b4c-4be9-587f-ae6b-fc20155c4b7b', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 18, 18, 'ከተማረኩትም ልጆች ከዐዋቂዎቹ በቤቱ ሾመ።'),
  ('e0cffdac-7592-5f46-a65d-6b4cc5ee1215', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 19, 19, 'ዳግመኛም የእስራኤል ልጆች የሚያደርጉትን የእግዚአብሔርን ሕግ ያስተምሯቸው ዘንድ ወደ መኝታው የሚገቡ፥ ታናናሽ ቅምጥል ልጆቹን የሚጠብቁ ዐዋቂዎችን ከታናናሾቹ ሾመ፤ ሥርዐቱንና ሕጉን፥ አምልኮቱንና ፍርዱን፥ ሞዓባውያንም የሚያደርጉትን ሥርዐት ሁሉ ከምርኮ ልጆች ይሰማ ነበር።'),
  ('57fce7d0-24a4-5555-ae77-fc24df66b410', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 20, 20, 'መስጊዳቸውን፥ ጥንቆላቸውንና ጣዖቶቻቸውን፥ ጧትና ማታ ከሰቡት ከፍየሎች ጠቦቶችና ከበጎች መንጋዎች፥ ለጣዖታቱ የሚሠዋውን መሥዋዕቱንና ወይኑንም ያጠፋ ነበር።'),
  ('c947eeae-01ee-5724-a5e3-482390e26c50', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 21, 21, 'በቀትርና በሰዓት በሥራው ሁሉ ይሰግድላቸውና ያመልካቸው ነበር፤ ይለምናቸውና ይተማመናቸውም ነበር፤ እንዲሁም ከመንገዱ በተመለሰ ጊዜ ይለምናቸው ነበር፤ የጣዖታቱ ካህናትም በነገሩት ሁሉ ፈቃዳቸውን ያደርግ ነበር።'),
  ('8cae811b-b695-51e3-a963-68aeb3c5ef85', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 22, 22, 'በነገሩ ሁሉ የሚያድኑት ይመስለው ነበርና የነገሩትን ሁሉ አይንቅም ነበር።'),
  ('d2f877b3-6a75-5a55-a784-3a4014486573', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 23, 23, 'ያ መቃቢስ ግን የእነርሱን መንገድ ተወ።'),
  ('edeb58c4-2402-5602-a5b0-7b241a1d561d', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 24, 24, 'ነቢይ የሚሉት የረኣዩን ነገር ከሰማ በኋላም በንስሓ መንገዱን አሣመረ፤ በዚያም ወራት ወገኖቹ ሁሉ ከእስራኤል ልጆች ይልቅ መንገዳቸውን አሣመሩ፤ የእስራኤል ልጆች አንድ ጊዜ ያሳዝኑት ነበርና በቀሠፋቸውም ጊዜ ዐውቀው ወደ እግዚአብሔር ይጮኹ ነበርና።'),
  ('ce9408be-6ae5-5383-a522-7ae6e91ddb66', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 25, 25, 'መከራ በሚያጸኑባቸው በአሕዛብ እጅ ተይዘው እንደ ተዋረዱ፥ ወደ እርሱም እንደ ጮሁ በሰማ ጊዜ የአባቶቻቸውን መሐላ አስቦ የዚያን ጊዜ ስለ አባቶቻቸው ስለ አብርሃምና ስለ ይስሐቅ፥ ስለ ያዕቆብም ይቅር ይላቸው ነበር።'),
  ('e9bf61f7-3eb9-52ed-ac4c-a7d93cb9b368', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 26, 26, 'በአዳናቸውም ጊዜ ያዳናቸውን ይረሱት ነበር፤ ጣዖታቱንም ወደ ማምለክ ይመለሱ ነበር።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('caa80407-318a-514c-a414-070ffde263aa', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 27, 27, 'ያንጊዜም በመከራ የሚያሠቃዩአቸው አሕዛብን ያስነሣባቸው ነበር፤ በአሠቃዩአቸውና ባሳዘኑአቸውም ጊዜ ወደ እግዚአብሔር ይጮሁ ነበር፤ የዚያን ጊዜም ራርቶ ይቅር ይላቸው ነበር። የእጁ ፍጥረት ስለ ሆኑ ይወድዳቸው ነበርና።'),
  ('f103b495-bff2-5f36-a5b9-acac127abf85', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 28, 28, 'ዳግመኛም በሚጠብቃቸው ጊዜ በዙሪያቸው ያለ ጣዖትን በማምለክና በክፉው የእጃቸው ሥራ ያሳዝኑት ዘንድ ይመለሱ ነበር።'),
  ('575a5c06-7bf7-5f8c-a30a-33468e662c33', '8633880b-614f-50d2-a962-4cad898f656f', '724d86a8-8cfb-5415-a5fa-e7ef7ef6eaf6', 29, 29, 'እርሱ ግን የኢሎፍሊንና የሞዓብን፥ የምድያምንና የሶርያን፥ የግብፅንም ሕዝብ ያስነሣባቸው ነበር፤ ጠላቶቻቸውም ድል በነሷቸው ጊዜ፥ መከራ በአጸኑባቸውና በአስገበሯቸው ጊዜ፥ በገዟቸውም ጊዜ ይጮሁና ያለቅሱ ነበር፤ እግዚአብሔርም በወደደበት ጊዜ ያድኗቸው ዘንድ መሳፍንትን ያስነሣላቸው ነበር፤ መሳፍንቱም ያድኗቸው ነበር።'),
  ('9a382ff5-0332-5310-aabf-006da7a22492', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 1, 1, 'በኢያሱም እነርሱን ያዳነበት ጊዜ አለ።'),
  ('25f995f0-0946-5177-ab7e-dc6069a1cc79', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 2, 2, 'በጌዴዎን እነርሱን ያዳነበት ጊዜ አለ።'),
  ('955a2b1d-f59d-5df1-a547-eca6c6cada93', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 3, 3, 'በሶምሶን፥ በባርቅና በዲቦራ፥ በዮዲትም እነርሱን ያዳነበት ጊዜ አለ፤ በሴትም ቢሆን፥ በወንድም ቢሆን አድሮ ከሚያሠቃዩአቸው ጠላቶቻቸው እጅ ያድኗቸው ዘንድ መሳፍንትን ያስነሣላቸው ነበር።'),
  ('83c71e75-0384-57e9-accb-e6a2744e8a66', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 4, 4, 'እግዚአብሔርም እንደ ወደደ ከሚያሠቃዩአቸው ሰዎች እጅ ያድናቸው ነበር።'),
  ('b0346e86-6b59-52c0-a15f-2a6c031da492', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 5, 5, 'በአደረገላቸውም በጎ ነገር ሁሉ በምድራቸው ዘር፥ በምድረ በዳ ያለ መንጋቸውን ሁሉና ከብታቸውንም በማብዛት ደስ ይላቸው ነበር።'),
  ('ea432d5a-8145-5dc6-a550-3418688ddd34', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 6, 6, 'ከብታቸውንና ተክላቸውን ይባርክላቸው ነበር፤ በቤትና በምድረ በዳ የያዙትንም ሁሉ ይባርክላቸው ነበር፤ በዐይነ ምሕረት ይመለከታቸው ነበርና እንስሶቻቸውን አያሳንስባቸውም ነበር፤ የጻድቃን ልጆች ናቸውና ፈጽሞ ይወዳቸው ነበር።'),
  ('86d4311d-e194-53bd-a30b-481201dc3dd1', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 7, 7, 'እነርሱ ግን በሥራቸው ክፉ በሆኑ ጊዜ በጠላቶቻቸው እጅ አሳልፎ ይሰጣቸው ነበር።'),
  ('662640b0-715d-560e-ad3b-2faa32e1259a', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 8, 8, 'በሚያጠፋቸውም ጊዜ ወዲያውኑ ይሹት ነበር፤ ተመልሰውም ወደ ፈጣሪያቸው ወደ እግዚአብሔር ይገሠግሡ ነበር።'),
  ('63660073-02f6-5e18-a7e9-0ae9d20651df', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 9, 9, 'በፍጹም ልቡናቸውም በተመለሱ ጊዜ ኀጢአታቸውን ያስተሰርይላቸው ነበር፤ ሥጋና ደም እንደ ሆኑ ያውቃቸዋልና የሚያስት የዚህ ዓለም አሳብና፥ አጋንንትም አሉባቸውና የቀደመ ኀጢአታቸውን አያስብባቸውም ነበር።'),
  ('df080dfb-0934-56e4-afd0-aa87639334d3', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 10, 10, 'ያ መቃቢስ ግን እግዚአብሔር በቅዱሱ ተራራ የሠራውን ይህን ሥርዐት በሰማ ጊዜ በንስሓ ተጋደለ።'),
  ('b70826c6-9ad9-5ff2-ab75-6a5f695a9bc0', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 11, 11, 'ይኸን ነገር ከአየና ከሰማ በኋላም በጎ ሥራ መሥራትን አላቃለለም፤ እግዚአብሔር ይቅር ብሎአቸዋልና የእስራኤል ልጆች የሚሠሩትን ቸርነት ሁሉ መሥራት አላቃለለም፤ ትእዛዙንም ሲተላለፉ እግዚአብሔር በሚቀሥፋቸው ጊዜ ያለቅሱና ይጮሁ ነበር፤ ዳግመኛም ይቅር ይላቸው ነበር፤ ሕጉንም ይጠብቁት ነበር።'),
  ('e21a9027-9f13-56a6-a4de-b28f111c862e', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 12, 12, 'መቃቢስም እንደዚሁ መንገዱን ያቀና ነበር፤ ትእዛዙንም ይጠብቅ ነበር፤ በእስራኤል አምላክ በእግዚአብሔር ትእዛዝም ይሔድ ነበር።'),
  ('aeafea1a-9649-57ed-a0d0-232fce46d890', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 13, 13, 'ያንጊዜም የእስራኤል ልጆች የሚመኩበትን ሁሉ ከሰማ በኋላ የእግዚአብሔርን ትእዛዝ በመጠበቅ እንደ እነርሱ ይመካ ነበር።'),
  ('4ab83e38-b4e3-5860-ae9f-b1ad6f36bacf', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 14, 14, 'ቤቱንና ልጆቹንም በእግዚአብሔር ሕግና ትእዛዝ ሁሉ ይሄዱ ዘንድ ይሠራራ ነበር።'),
  ('788acda2-ffe8-5e06-a5f8-179db804e902', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 15, 15, 'አይሁድ የሚከለከሉትን ሥርዐት እርሱም ይከለከል ነበር፤ አይሁድም የሚጠብቁትን ትእዛዝ ሰምቶ ይጠብቅ ነበር፤ እርሱ ልዩ ሞዓባዊ ወገን ሲሆን አይሁድ የሚከለከሉትን ምግብም ይከለከል ነበር።'),
  ('476f81f8-2b8c-557f-a09d-456d83236cfc', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 16, 16, 'ዐሥራትም ያወጣ ነበር፤ ከበጎቹና ከላሞቹ፥ ከአህዮቹም መጀመሪያ የተወለደውንና የገዛውን ሁሉ ይሰጥ ነበር፤ እንዲሁም አይሁድ የሚሠዉትን መሥዋዕት ፊቱን ወደ ኢየሩሳሌም መልሶ ይሠዋ ነበር።'),
  ('68cfc964-70b9-5167-ac92-8ad3b7be1d9d', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 17, 17, 'የስእለቱንና የኀጢአቱን፥ የፈቃዱንና የሰላሙን መሥዋዕትና የዘወትሩን መሥዋዕት ይሠዋ ነበር።'),
  ('f653887a-941d-54d9-ad0b-c086a8a150a6', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 18, 18, 'የአዝመራውንም መጀመሪያ ይሰጥ ነበር፤ አይሁድም የሚያቀርቡትን የወይኑን ቍርባን ያቀርብና ለሾመው ለሌዋዊው ይሰጥ ነበር፤ አይሁድም የሚያደርጉትን ሁሉ እንዲሁ ያደርግ ነበር፤ ዕጣኑንም ያጣፍጥ ነበር።'),
  ('087f2fb4-b620-5a8e-af55-6b9477488abf', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 19, 19, 'መቅረዝንና ጋኖችን፥ ጠረጴዛዎችንና ድንኳኖችን፥ አራቱን ኅብርና ቀለበቶችን፥ ለቅድስተ ቅዱሳኑም መብራት የተጣራ ዘይትን፥ እግዚአብሔርን በሚያገለግሉበት ጊዜ እስራኤል በቅድስተ ቅዱሳኑ እንደሚያደርጉት መጋረጃን አሠራ።'),
  ('5e9075ad-0287-54f9-ae34-2a999e1fe9a9', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 20, 20, 'በሕጉና በሥርዐቱ በኖሩ ጊዜ፥ እግዚአብሔርም ቸል ብሎ በጠላቶቻቸው እጅ ባልጣላቸው ጊዜ፥ መቃቢስም እንደ እነርሱ በመንገዱ ሁሉ በጎ ሥራ ይሠራ ነበር።'),
  ('cdf1fd0b-c3fd-5ee8-aa31-02514377f782', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 21, 21, 'መሪ እንዲሆነው፥ ከመረጣቸውና ፈቃዱን ከአደረጉ ከእስራኤል ወገኖችም እንዳይለየው ሁልጊዜ ወደ እስራኤል ፈጣሪ ወደ እግዚአብሔር ይጸልይ ነበር።'),
  ('e023acc7-983f-5534-ad8d-0eb972f039e7', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 22, 22, 'በጽዮን ልጅን፥ በኢየሩሳሌምም ቤትን ይሰጠው ዘንድ፥ በነቢዩ አንደበት ከተናገረው ከጥፋትም ያድነው ዘንድ ንስሓ በገባበትና በእግዚአብሔር ፊት በአለቀሰው ልቅሶ ሁሉ ንስሓውን ይቀበለው ዘንድ፥'),
  ('696f99a7-951c-505a-a6b2-71f0afa4adf5', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 23, 23, 'ዘሩንም ከምድር እንዳያጠፋበት፥ በመግባቱና በመውጣቱም ይጠብቀው ዘንድ ዳግመኛ ይጸልይ ነበር።'),
  ('732fc272-de95-5f6e-a2bb-4dfdf760407f', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 24, 24, 'በመቃቢስ ሥልጣን በታች ከአሉ ከሞዓብ አሕዛብም ያምኑ ዘንድ ደስ አላቸው፤ አለቃቸው በቀናች መንገድ ይሄድ ነበርና፥ ፍርዱንም ይመለከቱ ነበር፤ ፈቃዱንም ያደርጉ ነበር፤ የአገራቸውን ፍርድና ያገራቸውን ቋንቋ ይንቁ ነበርና የመቃቢስም ሥራ እንደሚቀናና እንደሚሻል ያስተውሉ ነበር።'),
  ('c63546b5-c514-5313-a76d-52a01ab1dd09', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 25, 25, 'ወደ እርሱም መጥተው የመቃቢስን የቸርነቱንና የእውነቱን ፍርድ ይሰሙ ነበር።'),
  ('80df0c17-7d10-5c61-a901-82de469ddefb', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 26, 26, 'ብዙ ገንዘብም ነበረው፤ ወንዶች ባሮችና ሴቶች ባሮች፥ ግመሎችና አህዮችም ነበሩት፤ ጥሩር የሚለብሱ አምስት መቶ ፈረሶችም ነበሩት፤ ኢሎፍላውያንንና አማሌቃውያንን፥ ሶርያውያንንም ፈጽሞ ድል ይነሣቸው ነበር፤ ቀድሞ ጣዖት ሲያመልክ ግን ድል ሲነሡት ኖረ።'),
  ('e623009b-067d-5105-a6bb-9063a8e7839f', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 27, 27, 'እግዚአብሔርን ከአመነ ወዲህ ግን ወደ ሰልፍ ሲሄድ እርሱ ድል ይነሣ ነበር እንጂ እርሱን ድል የነሣው አልነበረም።'),
  ('574020cc-5495-5dfc-a115-b7763f73b33c', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 28, 28, 'እነርሱ ግን ይወጉት ዘንድ በጣዖቶቻቸው ኀይል ይመጡ ነበር፤ በጣዖቶቻቸውም ስም ጠርተው ይረግሙት ነበር፤ ነገር ግን እምነቱን በፈጣሪው በእግዚአብሔር ላይ አድርጓልና ድል የሚነሣው አልነበረም።'),
  ('9f9cc25a-4b81-5131-abb9-d4c8b1c92fb1', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 29, 29, 'እንዲህም እያደረገና ጠላቶቹንም ድል እየነሣ፥ አሕዛብንም በሥልጣኑ እየገዛ ኖረ።'),
  ('d5773579-6530-586b-ac30-cc08c383070c', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 30, 30, 'ስለ ተበደሉትም ይበቀል ነበር፤ የድሃአደጉንም ፍርድ ያጸድቅ ነበር፤'),
  ('3e50ab59-a075-5fd4-aa8b-5e2afbebce56', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 31, 31, 'ባልቴቶችንና ድሃአደጎችንም በችግራቸው ጊዜ ይቀበላቸው ነበር፤ የተራቡትንም ከምግብ ያጠግባቸው ነበር፤ የተራቈቱትንም ከልብሱ ያለብሳቸው ነበር።'),
  ('d263bfc6-cc1f-5ecb-a137-33b5f12af9de', '3ba5a194-6504-58d0-a8b0-f1045f6d6a7c', 'a82fa0ae-fbf9-576d-a1c3-1f583375a2d2', 32, 32, 'በጥበቡና በእጁም ሥራ ደስ ይለው ነበር፤ ከአለውም ሳይነፍግ ይሰጥ ነበር፤ ለቤተ መቅደስም ዐሥራትን ይሰጥ ነበር፤ መቃቢስም ይኽን እያደረገ ሳለ በመልካም ዐረፈ።'),
  ('b764ad3c-36f0-5fae-a219-b5d5b9d4765d', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 1, 1, 'እርሱም ታናናሽ ልጆቹን ትቶ ሞተ፤ አባታቸውም ሥርዐት እንደ ሠራላቸው አደጉ፤ የቤታቸውንም ሥርዐት ጠበቁ፤ ወገናቸውንም ሁሉ ይጠብቁ ነበር፤ ድሃውንና ባልቴቶችን፥ የሙት ልጆችንም አያስጮሁም ነበር።'),
  ('038394c3-2b77-5614-aa8e-a2517017b052', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 2, 2, 'እግዚአብሔርንም ይፈሩት ነበር፤ ገንዘባቸውንም ለድሆች ይመጸውቱ ነበር፤ አባታቸውም አደራ ያላቸውን ሁሉ ይጠብቁ ነበር፤ ባልቴትዋንና የሙት ልጆችንም በችጋራቸው ጊዜ ያረጋጓቸው ነበር፤ አባትና እናትም ይሆኗቸው ነበር፤ ከሚበድሏቸው ሰዎች እጅ ያስጥሏቸው፥ ካገኛቸው ሁከትና ኀዘንም ሁሉ ያረጋጓቸው ነበር።'),
  ('911df50f-401f-5e03-ac6f-e6cc42b9dfa6', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 3, 3, 'እንዲህም እያደረጉ አምስት ዓመት ኖሩ።'),
  ('b3ca013c-ad8b-540e-a634-dda5e9fc9c2a', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 4, 4, 'ከዚህም በኋላ የከለዳውያን ንጉሥ ጺሩጻይዳን መጣ፤ ሀገራቸውንም ሁሉ አጠፋ፤ የመቃቢስንም ልጆች ማረካቸው፤ መንደራቸውንም ሁሉ አጠፋ።'),
  ('a8ea2709-ebb4-5f81-af11-620461bd89da', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 5, 5, 'ገንዘባቸውንም ሁሉ ዘረፈ፤ እነርሱንም በእግዚአብሔር ትእዛዝና ፍርድ የማይሔዱ፥ ነገር ግን በክፋት ሁሉና በዝሙት፥ በርኵሰትና በስስት፥ በፅርፈትና አምላካቸውን ባለማሰብ የሚሔዱ ጣዖት አምላኪዎች ይዘው ወደ ሀገራቸው ወሰዷቸው።'),
  ('c7c6dd7b-0c5e-5933-a710-caeedb76f4ee', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 6, 6, 'የሞተውንና ደሙን፥ አውሬ የበላውንና የበከተውን፥ እግዚአብሔርም የማይወድደውን ሁሉ ይበላሉ፤ በኦሪት ከተጻፈው ከእውነተኛው ትእዛዝም ሁሉ ሕግ የላቸውም።'),
  ('a6e298a3-f653-5ac4-a1a3-cabbcca27ffa', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 7, 7, 'እግዚአብሔርንም ከእናታቸው ማኅፀን ያወጣቸውና በሚገባ የመገባቸው፥ ፈጣሪያቸውና መድኀኒታቸውም እንደ ሆነ አያውቁትም።'),
  ('8b0c37a6-fc02-5b49-afda-f7306c174cee', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 8, 8, 'በፍርድ ጊዜም ሕግ የላቸውም፤ የእንጀራ እናታቸውንና አክስታቸውን አግብተው ወደ ቅሚያና ወደ ክፉ ነገር፥ ወደ ኀጢአትና ወደ ዝሙትም ይሄዳሉ እንጂ። ክፉውንም ሁሉ ያደርጋሉ፤ እኅቶቻቸውንና ዘመዶቻቸውንም ያገባሉ፤ ሕግም የላቸውም።'),
  ('00f7f3f3-07ac-50a2-aabd-cc17b493452c', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 9, 9, 'መንገዳቸውም ሁሉ ድጥና ጨለማ፤ ርኵሰትና ዝሙት ነው።'),
  ('3265d2fb-f860-52d1-afc9-81373fb39814', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 10, 10, 'እነዚያ የመቃቢስ ልጆች ግን በሥርዐታቸው ሁሉ ይጠበቁ ነበር፤ ሞቶ ያደረውንና አባላ የተመታውን አይበሉም ነበር፤ የከለዳውያንንም ልጆች ርኵሰትና ኀጢአታቸውን ሁሉ አይሠሩም ነበር። በዚህ መጽሐፍ ያልተጻፈ የኃጥኣንና የወንጀለኞች፥ የመናፍቃንና የከዳተኞች፥ ፍጹም ርኩሰትንና ቅሚያን የተሞሉ የአረማውያን ልጆች የሚሠሩት ሥራቸው ክፉና ብዙ ነበርና።'),
  ('53eb8b3b-bb80-5aa1-acb7-8399a0f5861a', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 11, 11, 'ፈጣሪያቸው እግዚአብሔር የሚወድደው ሥራ ሁሉ በእነርሱ ዘንድ አልነበረም።'),
  ('d11f1421-8f5f-5a33-aace-bd6bb169de9c', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 12, 12, 'ዳግመኛም ስሙ ብኤል ፌጎር የሚባል ጣዖትን ያመልኩ ነበር፤ እንደ ፈጣሪያቸው እንደ እግዚአብሔርም ያመልኩትና ይታመኑት ነበር። እርሱ ግን ደንቆሮና ዲዳ ስለሆነ የሚያየውና የሚሰማው የለም፤ የሰው እጅ ሥራ ጣዖት ነውና፤ ብርና ወርቅን የሚሠራ አንጥረኛ የሠራው፥ ትንፋሽና ዕውቀት የሌለው የሰው እጅ ሥራ ነው፤'),
  ('108e18cf-58bd-58de-ab95-7250103091d6', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 13, 13, 'አይበላም፤ አይጠጣምም።'),
  ('8f663137-70d7-53c4-a79c-4d4a48b7f2a2', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 14, 14, 'አይገድልም፦ አያድንምም።'),
  ('a720d2c7-6a38-549d-aca9-22dc158499b8', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 15, 15, 'አይተክልም፦ አይነቅልምም።'),
  ('77e67cb0-453d-55cb-a4a9-96fc62e78f47', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 16, 16, 'መልካም አያደርግም፤ ክፉም አያደርግም።'),
  ('699a49cc-88dc-506b-a644-cbb2c8961d03', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 17, 17, 'አያደኸይም፦ አያከብርምም።'),
  ('54360d9e-945d-5e5c-a843-22cf5e376da1', '7af6e409-aa6b-5fdc-a86f-1b3b1c455839', '094e7c17-8b5e-55c7-ac49-936cec420874', 18, 18, 'አይቀሥፍም፤ ይቅርም አይልም። ነገር ግን ሰነፎች የከለዳውያንን ሕዝብ ለማሳት ዕንቅፋትን ይሆናል።'),
  ('5cea5535-7229-5078-a462-de1a2fc40b2f', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 1, 1, 'የእግዚአብሔር ጠላት ትዕቢተኛው ጺሩጻይዳን የሐሰት ካህናትንና የጣዖታቱን አገልጋዮች ሾመ።'),
  ('7284f15f-a45b-5524-aa7f-f23131b6fe1d', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 2, 2, 'መሥዋዕት ይሠዉላቸው ነበር፤ ወይኑንም ያፈስሱላቸው ነበር።'),
  ('229464a4-ed77-57ca-ac05-faedb347e22d', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 3, 3, 'እነርሱም የሚበሉና የሚጠጡ ይመስለው ነበር።'),
  ('cfd92b2e-aa40-5041-a03b-b7078c7728c9', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 4, 4, 'በየጧቱም ላሞችንና በጎችን፥ ፍየሎችንና ጊደሮችንም ይሰጣቸው ነበር፤ ማታና ጧትም መሥዋዕት ይሠዋ ነበር፤ ከዚያችም ከረከሰችው መሥዋዕት ይበላ ነበር።'),
  ('ac246b9a-2f35-5ea6-a398-c28a17bc03a8', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 5, 5, 'ዳግመኛም ለጣዖታቱ ይሠዉ ዘንድ ሌሎች ሰዎችን ያነሣሷቸውና ግድ ይሏቸው ነበር እንጂ እነርሱ ብቻ የሚያደርጉት አልነበረም።'),
  ('3e8aadfd-77b9-593a-ab5c-5e1d0c7f88f1', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 6, 6, 'የመቃቢስንም ልጆች ያማሩ እንደ ሆኑና ፈጣሪያቸው እግዚአብሔርን እንደሚያመልኩት ባዩአቸው ጊዜ እንዲሠዉና ከረከሰችውም መሥዋዕት እንዲበሉ የጣዖታቱ ካህናት ያስትዋቸው ዘንድ ወደዱ፤ እነዚህ የተባረኩ የመቃቢስ ልጆች ግን እንቢ አሏቸው።'),
  ('e0510787-6c26-59cb-abee-e4c6d777512a', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 7, 7, 'የአባታቸውን ትእዛዝ ይጠብቃሉና፥ በጎ ሥራንም በመሥራት ጸንተዋልና፥ እግዚአብሔርንም ፈጽመው ይፈሩታልና እነርሱን እሺ ማሰኘት ተሳናቸው።'),
  ('dae344a7-a3a9-5ee7-a1ec-36a26c308515', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 8, 8, 'ባሰሯቸውና በሰደቧቸው፥ በቀሟቸውም ጊዜ፥'),
  ('7d9beb11-0e8e-5169-aa14-d942942731a9', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 9, 9, 'ለጣዖቶችም መስገድንና መሠዋትን እንቢ እንዳሉ ለንጉሡ ለጺሩጻይዳን ነገሩት።'),
  ('99e78f71-2fa5-5ac2-a647-f6b565206528', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 10, 10, 'ስለዚህም ንጉሡ ተቈጣ፤ አዘነም፤ ያመጧቸውም ዘንድ አዘዘ፤ አምጥተውም በፊቱ አቆሙአቸው፤ እርሱም “ለጣዖቶች ስገዱ፤ መሥዋዕትንም ሠዉ” አላቸው።'),
  ('781f617e-d0a5-54ae-a15b-d2110e79fbcd', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 11, 11, 'እነርሱም መልሰው እንዲህ አሉት፥ “እኛስ በዚህ ነገር አንመልስልህም፤ ለረከሱ ለጣዖቶችህም መሥዋዕትን አንሠዋም።”'),
  ('c128a8a6-2981-50f7-a6bd-6436038a992e', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 12, 12, 'በብዙ ሥራም አስፈራራቸው፤ ነገር ግን በእግዚአብሔር አምነው ልባቸውን አስጨክነዋልና አልቻላቸውም።'),
  ('96c6fd53-1213-5902-a8c9-b204e0ab7ba5', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 13, 13, 'እሳትም አንድዶ ጨመራቸው፤ እነርሱም ነፍሳቸውን ለእግዚአብሔር ሰጡ።'),
  ('9364c3db-65d8-53bf-ae2f-043ef3158822', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 14, 14, 'ከሞቱ በኋላም ሕያዋን ሆነው፥ የተመዘዙ ሰይፎቻቸውን ይዘው በመንግሥቱ ዙፋን ተኝቶ ሳለ በሌሊት ታዩት፤ እርሱም ፈጽሞ ፈራ።'),
  ('f1224d97-a964-5a63-abcb-f1b73d983b59', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 15, 15, 'እርሱም እንዲህ አላቸው፥ “ጌቶች እሺ በሉኝ፤ ምን ላድርግላችሁ? ያዘዛችሁኝን ሁሉ አደርግ ዘንድ ነፍሴን አትውሰዷት፤” ፈጽመውም አስፈሩት።'),
  ('5e912a00-3a20-5b7b-aafa-578221c17134', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 16, 16, 'እነርሱም፥ “እግዚአብሔር ፈጣሪህ እንደ ሆነ አስብ” እያሉ የሚገባውን ሁሉ ነገሩት፤ “ከዚህም ትዕቢትህ የሚሽርህና ከአባትህ ከዲያብሎስ ጋራ ወደ ታች ወደ ገሃነም የሚያወርድህ አለ፤ በዚያም አንተን የበደልንህ በደል ሳይኖር፥ ፈጣሪያችን እግዚአብሔርንም እያመለክን ሳለን፥ እግዚአብሔርነቱንም በመፍራት እየሰገድንለት ሳለን በእሳት እንዳቃጠልኸን ፍዳህን ሁሉ ትጨርሳለህ።'),
  ('b76b05ef-365c-5020-af8d-dadc851985e9', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 17, 17, 'እርሱ ሁሉን የፈጠረ ነውና፥ ሰማይንና ምድርን፥ ባሕሩንና በውስጧ ያለውንም ሁሉ፥'),
  ('dcaa6a4e-d94b-5d46-a4f2-799a372f82e7', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 18, 18, 'ፀሐይንና ጨረቃንም፥ ከዋክብትንም፥ ፍጥረቱንም ሁሉ የፈጠረ እርሱ እግዚአብሔር ነውና።'),
  ('f5f0b170-6cb0-5c17-a96c-c70bbc90f309', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 19, 19, '“በላይ በሰማይ፥ በታችም በምድር ከእርሱ በቀር ሌላ አምላክ የለም፤ ሁሉን የሚችል እርሱ ነው፤ የሚሳነውም የለም። የሚገድልና የሚያድን፥ የሚገርፍና ይቅር የሚል እርሱ ነው።'),
  ('a3f3ff0e-7702-59af-aa74-8e1868b5f3ca', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 20, 20, 'ሰማይንና ምድርን የሚገዛ እርሱ ነውና ከእጁ የሚያመልጥ የለም።'),
  ('e0d0299a-01b9-56fb-aa34-eceb1b3d1868', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 21, 21, 'ከአንተ ከወንጀለኛውና አባትህ ሰይጣን ልቡናቸውን ካሳወራቸው እንደ አንተ ከአሉ ከወንጀለኞች በቀር እርሱ ከፈጠረው ፍጥረት ከትእዛዙ የሚወጣ የለም፤ አንተና እነዚያ ጣዖታቶችህም እስከ ዘለዓለም ድረስ መውጫ ወደሌለባት ወደ ገሃነም በአንድነት ትወርዳላችሁ።'),
  ('15407b27-5993-5f8a-ad8c-81489500cc88', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 22, 22, 'በእኛ ክፉ ነገርን ታደርግ ዘንድ ይኸን ክፉ ሥራ ያስተማረህ መምህርህ ሰይጣን ነው እንጂ ይኸን የምታደርግ አንተ ብቻ አይደለህምና።'),
  ('f7e1b7df-f7f9-59ce-abf4-18e157acc1f5', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 23, 23, 'የፈጠረህ እግዚአብሔርንም አላሰብኸውም፤ ራስህንም እንደ ፈጣሪህ እንደ እግዚአብሔር ታደርጋለህ።'),
  ('d40257f9-dd2c-591c-a6bd-dba00dc44d5c', '5c17fde2-f22f-563f-a864-604cbf765ae1', '905cfe09-153c-5b68-ae67-06a3b61363bf', 24, 24, 'እግዚአብሔር እስኪያዋርድህ ድረስ በእጅህ ሥራና በጣዖቶችህ ትታበያለህ፤ በምድር ላይም ስለ ሠራኸው ኀጢአትህና በደልህ ሁሉ ይበቀልሃል።”'),
  ('3b406fda-47e1-5b18-a73c-5f4ab4dcc382', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 1, 1, 'የፈጠራችሁ እግዚአብሔርን የማታውቁ፥ ትእዛዙንና ቃሉንም የማትጠብቁ አንተና እንደ አንተ ያሉት ወዮላችሁ! በሲኦል ጭንቅም ተይዛችሁ በተገረፋችሁ ጊዜ በማይረባ ጸጸት ትጸጸቱ ዘንድ አላችሁና።'),
  ('70096155-f7d9-52d3-a899-e4fd2d6e32a4', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 2, 2, 'ነፍስና ትንፋሽ ለሌላቸው፥ ክፉ ነገር ያደረገባቸውን ለማይበቀሉ፥ በጎ ነገር ላደረገላቸውም በጎ ነገርን ለማያደርጉ ለጣዖቶችህ እንደ ፈጣሪያችሁ እንደ እግዚአብሔር የምትሠዉላቸውና የምትሰግዱላቸው አንተና ካህናትህ እስከ ዘለዓለም ድረስ ከእርሷ መውጫ የላችሁም።'),
  ('c0f8bbd5-3e1d-5a68-a028-5b0429ece8a7', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 3, 3, 'እናንተንና የአማልክቶቻችሁን አገልጋዮች፥ እናንተንም የሚያዝዙ አጋንንትን ወደ ገሃነመ እሳት ያወርዳችሁ ዘንድ እንደ እናንተ ያሉ የሰነፎችን ልቡና ለማሳት ሰይጣን በውስጣቸው የሚናገርባቸው የሰው እጅ ሥራ ናቸውና።'),
  ('b0df27ef-d887-5870-a861-5168194e4190', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 4, 4, 'የሚረባችሁ እንደሌለ አታውቁምና ትበድላላችሁ፤ ትስታላችሁም።'),
  ('6003ac81-17a3-5809-a1b0-25683e3cf7c1', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 5, 5, 'ከእናንተስ ለምግባችሁ እግዚአብሔር የፈጠራቸው እንስሳት፥ አውሬዎችና ውሾችም ይሻላሉ። እነርሱ ከአንዲት ሞት በቀር ዳግመኛ ኵነኔ የለባቸውምና።'),
  ('d043eba1-b5c9-53dc-a087-76174cc32352', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 6, 6, 'እናንተ ግን ትሞታላችሁ፤ ዳግመኛም እስከ ዘለዓለም ድረስ መውጫ በሌለባት በገሃነም እንቅጥቅጥ ይፈርድባችኋል።'),
  ('f6ed3c90-35ad-5b6b-aa87-eb54115cc184', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 7, 7, 'ይኸንም ተናግረው ሄዱ፤ ከእርሱም ተሰወሩ።'),
  ('6a874ad0-8ebd-5311-a93f-7cabca850262', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 8, 8, 'ያ ጺሩጻይዳን ግን በጽኑ ፍርሀት ተይዞ ሲንቀጠቀጥ አደረ፤ እስኪነጋም ድረስ አልተወውም።'),
  ('98a24cc1-d828-51cd-a061-0304482a7f56', '3494095a-8f6c-5554-a7ce-bdc20df07156', 'e0ae4d78-edb0-544a-a77a-b23b2f2bb262', 9, 9, 'ከዚህም በኋላ የጻድቃንን ሬሳዎች ወደ ጣለበት ቦታ ሄደ፤ ነገር ግን አላገኛቸውም፤ ይቀብራቸው ዘንድ ወድዶአልና። ነገር ግን ሄዶ ሬሳቸውን እንዳይነካ እግዚአብሔር ሰውሯቸዋልና አጣቸው።'),
  ('4a924946-dbb4-5e8b-ae15-c43aa2b05234', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 1, 1, 'በትዕቢትና በልብ ተንኰል ሄደ።'),
  ('50be073b-937c-5518-ae8f-6e145594d30e', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 2, 2, 'በመንግሥቱም ዳንኤል እንዳየው ብረት ፅኑ ተብሏልና በዙሪያው ያሉ የአሕዛብ ሀገሮችን ዞረ።'),
  ('8a125122-4aa2-5386-a8fc-edeb41924947', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 3, 3, 'በስንፍናና በክፋት ሁሉ፥ በሁከትም ይኖራል።'),
  ('2de47eb7-a478-5b4a-a2dd-2b4771a19bd2', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 4, 4, 'ቀድሞም የተናገርነውን ይሰብራል፥ ያደቅቃል፤ ይበላልም።'),
  ('8c91f20d-3f11-5200-a772-15df52546e52', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 5, 5, 'አንገቱን እንደ አደነደነ እንደ አባቱ እንደ ዲያብሎስም መርዝ የሚተፋ ነውና የቀረውን በእግሩ ይረግጣል።'),
  ('7f7b5fcb-115b-591f-afc4-1adc1ba8ca97', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 6, 6, 'እግዚአብሔርንም ፈጣሪው እንደ ሆነ አያውቀውም፤ ነገር ግን ዘመኔ እንደ ሰማይ ዘመን ሆነ ይላል።'),
  ('4dbe5a24-8e1a-58c2-a66f-db23a0f7ccdb', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 7, 7, 'በልቡናውም ፀሐይ ከእርሱ እንደሚወጣ ያስባል።'),
  ('24cc71ad-fce6-572d-afa6-872a684449ef', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 8, 8, 'በኀይልም ይነሣል፤ በዛብሎን ዕጣ ይሰፍራል፤ በመቄዶንያም ሰልፍን ያስነሣል፤ ከሰማርያም ቀለቡን ይቀበላል፤ ከሶርያም እጅ መንሻን ይሰጡታል።'),
  ('5cf5548e-08a5-5013-a29b-025a7105748c', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 9, 9, 'በዘላኖች አውራጃ ይሰፍራል፤ እስከ ሲዶናም ይደርሳል፤ በአካይያም ግብርን ይጥላል፤ እስከ ፈሳሹ ባሕርም ድረስ አንገቱን ከፍ ከፍ ያደርጋል፤ ተመልሶም እስከ ሕንደኬ ባሕር ድረስ መልእክቱን ይልካል።'),
  ('958345cc-9387-57ba-a719-ad33d179ebe6', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 10, 10, 'እንዲሁም አንገቱን እስከ ሰማይ ድረስ ከፍ ከፍ ያደርጋል።'),
  ('49ee73bb-5ebe-516d-ada5-79c7397b358d', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 11, 11, 'በመታበይና በክፋት ጸንቶ ይኖራል እንጂ ራሱን ማዋረድ የለውም።'),
  ('8b62b56e-c532-5ad6-abc2-e3edb196c06f', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 12, 12, 'መንገዱም ሁሉ ወደ ጨለማና ወደ ድጥ፥ ወደ ወንጀልና ወደ መታበይም፥ ደም ወደ ማፍሰስና ወደ መከራም ነው።'),
  ('f7c8b68e-b3b7-58e7-a3b0-b8b06a7d2b69', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 13, 13, 'መንገዱ ሁሉ እግዚአብሔር የሚጠላው ነው፤ የቅሚያና የክፋት፥ የኀጢአትም መምህር ሰብላንዮስ እንደ አስተማረው ያደርጋል፤ ድሃአደጉንም ያስጮሃል፤ ለድሃም አይራራም።'),
  ('4127467f-a4e8-5286-aad7-739a821755ae', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 14, 14, 'የአሕዛብንም ነገሥታት በእጁ አግብቶ ገደላቸው።'),
  ('5e5a8950-7086-58f3-ac42-369f0b82fdc3', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 15, 15, 'የጠላቶች አለቆችንም ገዛ፤ ብዙ አሕዛብንም ገዛ፤ እንደ ወደደም አስገበራቸው።'),
  ('e6029bb6-9bad-55ff-a370-cce3e1b22084', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 16, 16, 'ምሕረትም አላደረገም፤ ከተርሴስ ባሕር ጀምሮ እስከ ኢያሪኮ ባሕር ድረስ ያልነጠቀው የለም።'),
  ('84d184b7-ca40-5866-ad52-f074e3796c62', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 17, 17, 'ለጣዖትም ይሰግድ ነበር፤ ሙቶ ያደረውንና ደሙን፥ አባላ የተመታውንና ለጣዖቶች የተሠዋውን ይበላ ነበር፤ በሥራውም ሁሉ ያለ ፍርድ ፍጹም ቍጣና ክርክር ነበር እንጂ ፍርድ አልነበረውም። ከሥልጣኑ በታች ላሉ አሕዛብም የሚያስደነግጥ ሆኗልና እንደ ወደደ ግብርን ያስገብራቸው ነበር።'),
  ('5b82410b-12a2-568f-a5f8-5dc5e329655c', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 18, 18, 'በፊቱ የወደደውን ሁሉ ያደርጋልና በፊቱ እግዚአብሔርን መፍራት አልነበረውም፤ በፈጣሪው በእግዚአብሔርም ፊት በተንኰል ይኖር ነበር።'),
  ('c73ff41d-68a0-55c3-a400-2be060e160b4', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 19, 19, 'እንደ ፈጣሪውም አያደርገውም ነበር። እግዚአብሔርም ተቈጥቶ በያዘው ጊዜ በባልንጀራው ላይ ክፉ ነገርን እንደ አደረገ ፍዳውን ይከፍለዋል።'),
  ('7b6266a9-c366-5fc6-a8eb-5b223857a200', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 20, 20, 'እግዚአብሔር ከዚህ ዓለም ስም አጠራራቸውን አጠፋ ዘንድ በትእዛዜ የማይኖሩ ትዕቢተኞችን እኔ ተበቅዬ አጠፋቸዋለሁ ብሏልና፥ ከእርሱ አስቀድሞ የነበሩ ኃጥኣንን እንዳጠፋቸው በጊዜው ይበቀለዋል።'),
  ('aeeb6c61-3626-5c63-a8e8-0454df391044', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 21, 21, 'ክፉዎችም ክፉ እንደ አደረጉ ፍዳቸውን ይቀበላሉ።'),
  ('72bb8896-2023-5591-ac24-c8bde62779f7', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 22, 22, 'በጎ አድራጊዎችን ግን በጎነት ከእግዚአብሔር ዘንድ ትከተላቸዋለች።'),
  ('5dab037c-7072-58ba-aec7-22ec212b7720', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 23, 23, 'ኢያሱ አምስቱን የከነዓን ነገሥታትን በአንዲት ቀን በአንዲት ዋሻ እንደ አጠፋቸው፥ ሠራዊቶቻቸውንም ያጠፋቸው ዘንድ በጸሎቱ ፀሐይን በገባዖን እንደ አቆመ፥ የኤዌዎንንና የከናኔዎንን፥ የፌርዜዎንንና የኬጤዎንን፥ የኢያቡሴዎንንም ሠራዊት እስኪያጠፋቸው ድረስ ፀሐይ በሰማይ መካከል ቆሟልና በአንድ ጊዜ ሃያ ሺህ ያህል ሰውም እንደ ገደለ፥ እነርሱንም እንደ ገደላቸው፥ እግር ከአንገትም አድርጎ እንደ አሰራቸው፥ በዋሻም በጦር እንደ ገደላቸው፥ ደንጊያም እንደ ገጠመባቸው፥'),
  ('a211a8dd-ae29-53b8-aa57-37c26db16151', '5e1c7d36-006b-518e-ad76-85002395ce31', 'c2250a34-914a-5f31-ad91-91c6fa524c60', 24, 24, 'በክፉ ሥራቸው እግዚአብሔርን የሚያሳዝኑትንም ሰዎች እንደዚህ ያለ መከራ ያገኛቸዋል።'),
  ('bde8ba76-c803-5ac0-a9a5-02918172ccbf', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 1, 1, 'እግዚአብሔር ያይደለህ አንተ ደካማ ሰው ሆይ! ለምን ትኰራለህ? ዛሬ ሰው ነህ፤ ነገም መሬትና ዐመድ ነህ፤ በመቃብርህም ትልና ብስባሽ ትሆናለህ።'),
  ('b7540a96-0f14-529b-a727-fd55479e0636', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 2, 2, 'ዳግመኛም አንተንና የአንተን ሥራ የሚሠሩትን ሲኦል ትከተላቸዋለች፤ የአንተ መምህር አባታችን አዳምን ስለ አሳተ የዐለምን ሁሉ ኀጢአት ወደ ራሱ የሚመልስ ሰብልያኖስ ነውና፤'),
  ('5840e43e-f85c-5dfe-a890-7f6420239b96', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 3, 3, 'ራሱንም በማኵራትና ልቡናውን በማደንደን ለፈጣሪው ሥራ መስገድን እንቢ ብሏልና።'),
  ('02afb4e3-cb6f-502f-ae78-87de6c24e145', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 4, 4, 'አንተም እንደ መምህርህ ለፈጣሪህ ለእግዚአብሔር መስገድን እንቢ ብለሃል።'),
  ('2b5fb82b-3dc2-56d8-a561-9aafe13fa3d4', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 5, 5, 'አንተም ፈጣሪያቸው እግዚአብሔርን የማያውቁት የቀደሙህ እንደ ሄዱት ትሄዳለህ፤'),
  ('35b3363a-3bef-52be-aceb-a68f81dd99af', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 6, 6, 'በምድር ስለ ሠሩት ስለ ክፉ ሥራቸው እንደ ተበቀላቸውና ወደ ሲኦል እንደ ወረዱ፥'),
  ('efa87294-29ca-59b4-aa70-d1d58b461ea5', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 7, 7, 'አንተም እንደ እነርሱ ወደ ገሃነም ትወርዳለህ።'),
  ('5ff7b957-44e6-5c89-a173-9b10b8d78028', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 8, 8, 'ቍጣውንም አነሣሥተሃልና፥ በአምስቱም መንግሥታት ላይ ሥልጣንን የሰጠህ እግዚአብሔርን ማምለክ ቸል ብለሃልና፥ ከእግዚአብሔር እጅ የምታመልጥ ይመስልሃልን?'),
  ('2baa5566-9cfc-50da-a933-77ad698e77e6', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 9, 9, 'ፈቃዱንም ታደርግ እንደ ሆነ፥ አታደርግም እንደ ሆነ መረመረህ፤ በምድርም መንገድህን ብታሣምር እግዚአብሔር መንገድህን ያከናውንልሃል፤ እጅህንም ያኖርህበትን ሁሉ ያከናውንልሃል፤ ይባርክልሃልም፤ ጥንተ ጠላቶችህንና የዕለት ጠላቶችህንም ያስገዛልሃል።'),
  ('13a74eeb-2c81-570a-aa17-6f9d0060399e', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 10, 10, 'በመውጣትህና በመግባትህ፥ በሆድህም ፍሬ፥ በመንጋዎችህና በድልቦችህም፥ በጣቶችህም በአመለከትህበት ሥራ ሁሉ፥ በልብህም ባሰብኸው ሁሉ ደስ ይልሃል፤ እንዲህ ታደርግ ዘንድ፥ ትሠራና ትተክል፥ ታፈርስም ዘንድ ከእግዚአብሔር ዘንድ ሥልጣን ተሰጥቶሃልና ሁሉ ይታዘዝልሃል።'),
  ('083d9b79-2343-549e-a7da-310b775677eb', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 11, 11, 'ነገር ግን የእግዚአብሔርን ቃልና ሕግ መስማትን እንቢ ብትል፥ በፍርዱም ባትኖር ፍርዱ ሁሉ እውነት ነውና ከአንተ አስቀድሞ እንደ ነበሩ፥ በሚገባም እግዚአብሔርን እንደማያመልኩት፥ በቀና ፍርዱም ጸንተው እንዳላመኑ ወንጀለኞች ከእግዚአብሔር እጅ የምታመልጥበት የለም።'),
  ('f4ad0735-6eed-50b7-aa3c-0c2280577d42', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 12, 12, 'ከፊቱም የሚሰወር የለም፤ ነገር ግን ሁሉ በፊቱ ፈጽሞ የተገለጠ ነው።'),
  ('4f9f94dc-d1df-5b9a-ac84-1de0fced76de', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 13, 13, 'የነገሥታቱን ሥልጣን የሚይዝና የኀይለኞችን ዙፋን የሚገለብጥ እርሱ ነው።'),
  ('26c62e70-d269-5185-a4cd-dc0936ce5a6e', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 14, 14, 'የተዋረዱትንም ከፍ ከፍ የሚያደርግ፥ የወደቁትንም የሚያነሣ እርሱ ነው።'),
  ('2688e09f-bdcf-56ba-aba7-6d92973658cf', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 15, 15, 'የታሰሩትን የሚፈታ እርሱ ነው፤ የሞቱትንም የሚያስነሣ እርሱ ነው፤ የይቅርታ ጠል ከእርሱ ዘንድ ነውና ሥጋቸው የፈረሰና የበሰበሰ፥ እንደ ትቢያም የሆነ ሰዎችን በወደደ ጊዜ ያስነሣቸዋል።'),
  ('def1d88d-f26e-5644-aa8c-0c10418cee5b', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 16, 16, 'አሳዝነውታልና ክፉ ሥራ የሠሩ ሰዎችንም የደይን ትንሣኤን ያስነሣቸዋል፤ ይበቀላቸዋልም።'),
  ('e2f8063e-b77e-59f0-ac28-ed5dc770097f', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 17, 17, 'በምድርም ዘራቸውን ያጠፋል፤ እነርሱ የእግዚአብሔርን ሕጉንና ሥርዐቱን ያፈረሱ ናቸውና፤'),
  ('668764d3-b9b4-5889-a9f1-a897a878dac9', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 18, 18, 'የጻድቃን መንገድ ከኃጥኣን መንገድ ይልቅ ጭንቅ ነውና ኃጥኣን በጻድቃን ምክር ይኖሩ ዘንድ አይወድዱም።'),
  ('a8c5f7d0-027d-5731-abad-6ee8d3a9f736', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 19, 19, 'ሰማይ ከምድር የራቀ እንደ ሆነ እንደዚሁ የጻድቃን መንገድ ከኀጥኣን መንገድ የራቀ ነው።'),
  ('74d56a89-547e-500f-a21d-f63996ee69a1', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 20, 20, 'የኃጥኣን መንገድ ግን የቅሚያና የክፋት፥ የዐመፅና የዝሙት፥ የስስትና የክዳት ነው፤ በዐመፅም መስከርና የሰውን ገንዘብ መቀማት ነው።'),
  ('3389ac0a-5688-522b-a9fd-9c595052036e', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 21, 21, 'የሰውን ደም ወደ ማፍሰስ ፈጥኖ መሔድ፥ በማይጠቅም ጥፋት ማድረግ፥ ድሃአደጉን ማስለቀስ፥ ደምንና ሞቶ ያደረውን መብላት፥ የግመልና የእሪያም ሥጋ መብላት፥ ወደ አራስና ሳትነጻ በደሟ ወዳለች ሴት መሔድ ነው።'),
  ('f5d316f6-07d3-5a14-adb6-3f6606c8c835', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 22, 22, 'ይህም ሁሉ የኃጥኣን ሥራ ወደ ዘለዓለም ጥፋትና ቅጣት የሚወስድ ሰፊ መንገድና የተዘረጋ የሰይጣን ወጥመድ ነው።'),
  ('36e17471-ebd8-5999-ab3b-3b724b39240d', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 23, 23, 'ጠባብና ቀጭን የምትሆን የጻድቃን ጎዳና ግን ወደ ሕይወት፥ ወደ የዋህነትና ወደ ትሕትናም፥ ወደ ፍቅርና ሰላም፥ ወደ ጾምና ጸሎት፥ ወደ ሥጋም ንጽሕና፥ ከማይጠቅም፥ አባላ የተመታውንና ሞቶ ያደረውን ከመብላት፥ ወደ ጐልማሳ ሚስት ከመሔድና ከዝሙትም ወደ መጠበቅ የምትወስድ ናት።'),
  ('b17230d1-f569-5056-a742-3e24a74452a7', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 24, 24, 'ኀጢአተኞች ሰዎች ይኸን ሁሉ ያደርጋሉና በሕግ ከአልታዘዘ ከተጠላ ሥራ ሁሉና ርኩስ መብልን ከመብላት፥ እግዚአብሔርም ከማይወደው ሥራ ሁሉ ይጠበቃሉ።'),
  ('408a12de-d100-516d-a4bd-60bc1ef58f30', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 25, 25, 'ጻድቃን እግዚአብሔር ከማይወደው መንገድ ሁሉ ይርቃሉ።'),
  ('0ac94b5d-cb8a-5db7-a379-afe050a51633', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 26, 26, 'እርሱም ይወድዳቸዋል፤ ከመከራቸውም ሁሉ እንደ አደራ ገንዘብ ይጠብቃቸዋል፤ ያድናቸዋልም።'),
  ('50a57786-a85d-5c3d-a68f-2b39e35f89e4', '7d129b55-6605-5fff-a299-3332aa9c09a0', 'b881114e-cbae-5045-ae7a-bc63510fb026', 27, 27, 'ኃጥኣንን ግን ሰይጣን ይገዛቸዋል። ሕጉንና ሥርዐቱን፥ የሚወደውንም ሁሉ ይጠብቃሉና።'),
  ('462bc906-b19c-5fdc-a545-c3872cfce227', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 1, 1, 'እናንተም ነገሥታቱና መኳንንቱ በሰይጣን ጎዳና አትሂዱ። ነገር ግን የፈጠራችሁን፥ እስከ ዛሬም ድረስ የጠበቃችሁን እግዚአብሔርን ፍሩት።'),
  ('f96762fa-c355-5f02-ae65-553b8d92709c', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 2, 2, 'ሁሉንም በሚገዛ በእግዚአብሔር ሕግና ትእዛዝ ጸንታችሁ ኑሩ።'),
  ('974e91b8-39dd-5115-a1ea-6c7a112b4e93', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 3, 3, 'የእስራኤል ልጆች የኬጤዎንንና የከናኔዎንን፥ የፌርዜዎንንም ሀገር ይወርሱ ዘንድ ወደ አማሌቅ በመጡ ጊዜ የሴፎር ልጅ ባላቅ፥'),
  ('22c6d0c5-5e7a-55b8-ad06-354e3e6d84d8', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 4, 4, 'በለዓምን፥ “አንተ የረገምኸው የተረገመ፥ የመረቅኸውም የተመረቀ ነውና ትረግምልኝ ዘንድ ና፤ እኔም የሚያከብርህን ብዙ ወርቅና ብር እሰጥሃለሁ” ብሎታልና።'),
  ('6386fadb-0cdf-5b42-a12c-e64c7c8f4f75', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 5, 5, 'በለዓምም የጥንቆላውን ዋጋ ተስፋ አድርጎ መጣ፤ የሴፎር ልጅ ባላቅም የእስራኤል ልጆች የሰፈሩበትን ቦታ አሳየው፤'),
  ('5536e7b0-9eb1-52d7-a06f-e5c6dac63523', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 6, 6, 'ሟርቱንም አደረገ፤ መሥዋዕቱንም ሠዋ፤ የሰቡትንም ላሞችንና በጎችን አረደ፤ የእስራኤልንም ልጆች ይረግማቸው ዘንድ ወደደ።'),
  ('96fd6694-4afa-53c8-a8ff-830c62d110b7', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 7, 7, 'እግዚአብሔር ግን ይረግማቸው ዘንድ አልወደደም፤ ርግማንን ወደ ምርቃት በቃሉ መለሳት እንጂ።'),
  ('3f55a139-85f6-53eb-ae9d-2ff7fe9e7b1a', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 8, 8, 'እንዲህም አለ፥ “አንተ እግዚአብሔር የመረጠው ሕዝብ ነህና፥ ከሰማይ የሚመጣ የፍቁር ማደሪያም ነህና የሚመርቁህ የተመረቁ ይሁኑ፤ የሚረግሙህም የተረገሙ ይሁኑ” አለ።'),
  ('0d47576d-e42d-5da5-a3fc-8122f1cd5364', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 9, 9, 'ከዚህም በኋላ በፊቱ በመረቃቸው ጊዜ የሴፎር ልጅ ባላቅ አዘነ፤ ፈጽሞም ተቈጣ፤ ይረግማቸውም ዘንድ አዘዘ።'),
  ('87036fbc-b052-5da8-ad1c-16c9e847f0a9', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 10, 10, 'በለዓምም፥ “እግዚአብሔር የመረቀው ወገን ወደዚህ ሀገር መጥትዋልና እግዚአብሔር የመረቃቸውን እኔ አልረግምም” አለው።'),
  ('5ff5cf0c-51bd-5f89-aff7-7ff0c4efe908', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 11, 11, 'የሴፎር ልጅ ባላቅም በለዓምን አለው፥ “እኔ ትረግምልኝ ዘንድ ወድጄ ነበር፤ አንተ ግን አልረገምኻቸውም፤ በፊቴም ፈጽመህ መረቅኻቸው፤ አንተም ብትረግምልኝና ስጠኝ ብትለኝ እኔ ቤት ሙሉ ወርቅና ብር በሰጠሁህ ነበር፤ አንተ ግን ፈጽመህ መረቅኻቸው፤ ለእኔም በጎ አላደረግህም፤ እኔም ለአንተ በጎ ነገር አላደርግም።”'),
  ('5f088579-e3b2-5708-af4f-a548a3557acf', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 12, 12, 'በለዓምም፥ “እግዚአብሔር በአንደበቴ ያደረገውን ቃል እርሱን እናገራለሁ እንጂ እኔስ የእግዚአብሔርን ቃል ቸል ማለትና መተላለፍ አልችልም።'),
  ('7c704c5c-6492-530b-a936-39438478355d', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 13, 13, 'እኔስ ከነፍሴ ገንዘብን አልወድድም፤ ገንዘብን ብወድ የተመረቀ ወገንን እንዳልረግም እግዚአብሔር ይቈጣኛልና” አለ።'),
  ('e592da17-f4e6-58ee-a560-2d27ee064149', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 14, 14, 'እግዚአብሔር አባታቸው ያዕቆብን፥ “የሚመርቁህ የተመረቁ ይሁኑ፤ የሚረግሙህም የተረገሙ ይሁኑ” ብሎታልና፤'),
  ('454242e6-a418-5b57-a10f-fa0e506fdd30', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 15, 15, 'የሚመርቅህም ሁሉ የተመረቀ ነው፤ ያለ ፍርድም የሚረግምህ የተረገመ ነው፤ እግዚአብሔር አንተን ይወድህ ዘንድ ጎዳናህንና ሥራህን አከናውን።'),
  ('05dda9e5-85f5-5769-ac3b-68da888992f6', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 16, 16, 'እግዚአብሔርንም በክፋታቸው እንዳሳዘኑት፥ እርሱም ቸል እንዳላቸው እንደ ቀደሙ ሰዎች አትሁን፤ በጥፋት ውኃም ያጠፋቸው አሉ።'),
  ('b142534f-50b7-552a-ac5c-d0580343ad7b', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 17, 17, 'በጠላቶቻቸውም እጅ ያጠፋቸው አሉ፤ መከራ ያጸኑባቸው ክፉዎች ጠላቶችን አምጥቶ ነገሥቶቻቸውን ከካህናቶቻቸውና ከነቢያቶቻቸው ጋራ ማረኳቸው።'),
  ('9a02931e-eba2-50b8-a20e-f4e2c8f07bb9', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 18, 18, 'ወደማያውቁት ወደ ባዕድ ሀገርም አደረሷቸው፤ ፈጽመውም ማረኳቸው፤ ገረፉአቸውም፤ ሀገራቸውንም አጠፉ።'),
  ('3afc0d5d-a29b-52ad-a034-50f46f0e6435', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 19, 19, 'የቅድስቲቱን ከተማ አጥሯንና ቅጥሯን አፍርሰዋልና ኢየሩሳሌምን እንደ እርሻ አደረጓት።'),
  ('bc969209-10fc-5030-a574-446f9c84714c', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 20, 20, 'ካህናቱም ተማረኩ፤ ሕጉም ፈረሰ፤ አርበኞችም በጦር ወደቁ።'),
  ('b5e26ca8-10dd-5a3a-a765-9f94f7b6619a', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 21, 21, 'ባልቴቶችም ተማረኩ፤ ለሞቱ ባሎቻቸውም አላለቀሱም፤ ተማርከዋልና ለራሳቸው አለቀሱ፤'),
  ('3d2ba7fb-41fd-5c09-a9cc-2804e333a66f', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 22, 22, 'ሕፃናትም አለቀሱ፤ ሽማግሎችም አፈሩ፤ የሽማግሌውንና የሽበታሙን ፊት አልራሩም።'),
  ('e3101eb8-04cc-5ba7-abf0-abb388570cb2', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 23, 23, 'ለቆንጆዎችና በሕግ ላሉም አልራሩም፤ በአገራቸው ያገኙትንም ሁሉ አጠፉ፤ ቤተ መቅደስን አስቀድሞ ያፈርስ ዘንድ በወደደ ጊዜ እግዚአብሔር ወገኖቹን ተቈጥትዋልና ወደማያውቁት ወደ ባዕድ ሀገር ማርከው ወሰዷቸው።'),
  ('74cff8bb-d1b0-5773-ab59-95e6532f372e', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 24, 24, 'ስለዚህም እግዚአብሔር የእስራኤልን ልጆች ቸል ባላቸው ጊዜ እግዚአብሔር ኢየሩሳሌምን እንደ እርሻ እንድትታረስ አደረጋት፤ ሁልጊዜ ፈጣሪያቸውን ያሳዝኑታልና።'),
  ('28d84c8b-a580-5483-aeb3-5a4052b38375', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 25, 25, 'እርሱ ግን በምንም አንድ ጊዜ አላጠፋቸውም፤ ስለ አባቶቻቸው ይራራላቸዋልና የሚራራላቸው ስለ ራሳቸው አይደለም። በእውነት የነገሡ፥ በፈጣሪያቸውም ፊት በቀና ሕግ ጸንተው የኖሩ አባቶቻቸውን አብርሃምንና ይስሐቅን ያዕቆብንም ይወዳቸዋልና ነው እንጂ።'),
  ('7fe73aa7-2d63-5061-a25a-271fc8f90905', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 26, 26, 'እርሱም እጥፍ በሆነ ክብር ላይ ሾማቸው፤ በሰማይና በምድር ያለ ሁለት መንግሥትንም አገኙ።'),
  ('9fdfeadd-8f5d-57de-a65e-151132292220', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 27, 27, 'እንዲሁም በሚያልፍ በዚህ ዓለም የምትኖሩ እናንተ ነገሥታቱና መኳንንቱ በሚገባ ሥራ ጸንተው የኖሩ ከእናንተ አስቀድሞ የነበሩ አባቶቻችሁ መንግሥተ ሰማያትን እንደ ወረሱ፥ ስማቸው ለልጅ ልጅ ያማረ እንደ ሆነ አስቧቸው።'),
  ('7005e1f9-dfea-5ae2-abd6-5787f796d676', '2997fc9e-340f-5f9d-aabc-87dfce57a176', '4e19412e-1f09-51a4-a3e4-848415939d54', 28, 28, 'አንተም መንግሥትህን ያቀናልህ ዘንድ መልካም አኑዋኑዋራቸው እግዚአብሔርን እንዳገለገሉት ከአንተ አስቀድሞ እንደ ነበሩ እንደ ደጋጎች ነገሥታት ስምህን መልካም ያደርግልህ ዘንድ ሥራህን አቅና።'),
  ('d36a765f-cd2d-52fd-af48-661a15089136', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 1, 1, 'የእግዚአብሔርን ሰው ሙሴን አስበው፤ በጸሎቱና በትሕትናው ይህን ያህል ሕዝቡን ሲጠብቅ አልተበሳጨም፥ አላጠፋምም፤ ነገር ግን ላሙትና እግዚአብሔርም በአንድ ጊዜ ያጠፋቸው ዘንድ ለወደደ ለወንድሙና ለእኅቱ በየዋህነቱ በእግዚአብሔር ዘንድ ኀጢአታቸውን እንዲህ ሲል አስተሰረየላቸው፥ “አቤቱ ወገኖችህ በፊትህ በድለዋልና ወገኖችህን ይቅር በል፤ ቸልም አትበል፥'),
  ('aa3f0f1b-9ee6-51e0-af4d-e38f2c8c543e', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 2, 2, 'በፊትህ በድያለሁና ኀጢአተኛ የምሆን እኔን ባርያህን ይቅር በለኝ፤ አንተ መሓሪ ነህና፥ ይቅር ባይም ነህና ለእነርሱም አስተስርይላቸው።”'),
  ('b30e0204-01b6-5bcf-a807-2866f6a96868', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 3, 3, 'እንደዚህም ሙሴ ለአሙት አስተሰረየላቸው።'),
  ('f2d51016-c22c-5347-a829-2504c4f2f560', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 4, 4, 'ስለዚህም የዋህ ተባለ።'),
  ('1cb73976-e97d-5ff4-a36f-505b0f32402d', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 5, 5, 'እግዚአብሔርም ከወንድሞቹ ከሌዋውያኑ ልጆች ሁሉ ይልቅ እጅግ ወደደው፤ ካህናቱንም ይሾማቸዋልና በእነርሱ ዘንድ እንደ እግዚአብሔር አስመሰለው።'),
  ('97a649b4-a7f8-5d99-a5be-e8c53902caf2', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 6, 6, 'የተደፋፈሩ የቆሬን ልጆች ግን በምድር በታች አሰጠማቸው፤ በሥጋና በነፍስ ሕያዋን ሳሉ ከከብቶቻቸውና ከድንኳኖቻቸው ጋራ ወደ ሲኦል አወረዳቸው፤ ፈጣሪው እግዚአብሔርን ወድዶታልና ከትእዛዙም አልወጣምና የተናገረው ቃል ሁሉ እንደ እግዚአብሔር ቃል ይደረግለት ነበር።'),
  ('ef1620f4-ea65-566c-a876-44745141e389', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 7, 7, 'አንተም እንዲሁ የእግዚአብሔርን ትእዛዝ ባትተላለፍ እግዚአብሔር ፈቃድህን ያደርግልሃል፤ ነገርህንም ይወድልሃል፤ መንግሥትህንም ይጠብቅልሃል።'),
  ('5abb2968-5787-54b0-a99d-9129f4739bb9', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 8, 8, 'ከሙሴ ትእዛዝ የወጡ የቆሬና የአሳፍ ልጆችም ለእግዚአብሔር ልቡናችሁን አቅኑ ስላላቸው በእርሱ አንጐራጐሩ።'),
  ('c88ee9d7-821b-531a-ac5e-11f035dd11fb', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 9, 9, '“እኛስ በምስክሩ ድንኳን የክህነት ሥራ የምንሠራ የሌዊ ልጆች አይደለንምን?” አሉት።'),
  ('e0c6cc2e-b138-555c-abee-68246b22f636', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 10, 10, 'ያጥኑም ዘንድ ጥናቸውን ያዙ፤ ሄደውም አጠኑ፤ እግዚአብሔር ግን ጸሎታቸውን አልተቀበለም፤ በጥናቸው እሳትም ተቃጠሉ፤ በእሳት እንደሚቀልጥ ሰምም ቀለጡ፤ ከእነርሱም አንድ ሰው ስንኳ አልቀረም፤ “በሰውነታቸው መቃጠል ጥናቸው ከብሯል” ብሏልና በእግዚአብሔር ትእዛዝ ወደ እግዚአብሔር ማደሪያ ከገቡት ከጥናቸው በቀር ልብሶቻቸውና አጥንቶቻቸው አልቀሩም።'),
  ('7fb0a14f-a5a1-5f84-aa3a-9841c72a5042', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 11, 11, 'ስለዚህም እግዚአብሔር ሙሴንና አሮንን እንዲህ አላቸው፥ “ጥናቸውን ወደ ድንኳን ሰብስቡ፤ ከውጭ ጀምሮ እስከ ውስጥ ድረስ ሁሉን ላዘጋጀሁለት ለቤቴ መሣሪያ ይሁን።”'),
  ('11d8ae11-2d5f-5d9c-a177-f2cea67e8ca7', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 12, 12, 'የተቀደሰች የድንኳንዋንም መሣሪያ አዘጋጀ፤ መክደኛውንና ቀለበቱን፥ የኪሩቤልን ሥዕልና ባሕሩን አዘጋጀ።'),
  ('797f9653-7e1b-5c87-a13d-ac00b49a6fe8', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 13, 13, 'ሰኑንና መጋረጃውን፥ ስክተቱንና የድንኳኑን ዙሪያ ዕድሞ፥ ጋኖችንና በምስክሩ ድንኳን የሚሠዉበት መሠዊያውን ሠራ።'),
  ('2639883d-3da8-534f-a424-ea5f97e94411', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 14, 14, 'የፈቃዱን መሥዋዕትና የሰላሙን መሥዋዕት፥ የስእለቱንና የኀጢአቱን መሥዋዕት፥ የማታውንና የጧቱንም መሥዋዕት ሠዉ።'),
  ('10a72fd4-1ad4-5829-a851-e807c6808243', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 15, 15, 'ሥራ ይሠሩባት ዘንድ በምስክሩ ድንኳን ለሙሴ ያዘዘውን ሁሉ አዘዛቸው።'),
  ('eb1c74a3-176e-5081-a4b8-edc6d1e3ceda', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 16, 16, 'ማርና ወተትን የምታስገኝ፥ ለአብርሃም የማለለትን፥ ያባቶቻቸውን ርስት ይሰጣቸው ዘንድ ተስፋ በሰጣቸው በፈጣሪያቸው በእግዚአብሔር በሕጉ ድንኳን ውስጥ ስሙ በእነርሱ ይመሰገን ዘንድ ለአምላካቸው መገዛትን አላቃለሉም።'),
  ('f20d88dc-4c2c-5e6e-ab85-702f307218b0', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 17, 17, 'ለይስሐቅ ማለለት፤ ለያዕቆብም አምልኮቱን አጸናለት።'),
  ('a891de9f-5635-5d93-ae51-8f0ddbc101e3', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 18, 18, 'በምስክሩ ድንኳንም ለሙሴና ለአሮን አጸናላቸው፥'),
  ('1ad63336-07b0-53be-a11c-749deb05bd1c', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 19, 19, 'በኢየሩሳሌም በድንኳኑና ሰሎሞን በሠራው ቤተ መቅደስ የእግዚአብሔር ማደሪያ፥ የልዑልም የስሙ ማረፊያ፥ የእስራኤልም ቅዱስ ማደሪያ እስኪሆን ድረስ ለሳሙኤልና ለኤልያስ አምልኮቱን አጸናላቸው።'),
  ('c128d1e3-2aef-54d5-ad30-d35bb0485b9c', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 20, 20, 'በየዋህነት ለሚኖሩ ለካህናቱ የሚገለጥባት መለመኛና የኀጢአት ማስተስረያ ናትና።'),
  ('68620f8d-346e-5738-a99a-10f67cb24ab3', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 21, 21, 'ፈቃዱንም ለሚያደርጉ ሰዎች ልመናቸውን የሚሰማባት ቦታ ናት።'),
  ('a48c552d-4cee-506d-af3f-5deb2ade93b6', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 22, 22, 'የእስራኤልም ቅዱስ የእግዚአብሔር ሕጉ የሚሠራባት ናትና።'),
  ('594242f2-df87-5ef2-aa64-f02d5d57a18f', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 23, 23, 'ለእስራኤል ቅዱስ ለእግዚአብሔር በጎ መዓዛ ሊሆን መሥዋዕት የሚሠዋባት፥ ዕጣንም የሚታጠንባት ናትና።'),
  ('f3fb2890-23a4-5da6-a4f1-fd486f0a3218', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 24, 24, 'በምስክሩ ድንኳን ውስጥም ይቅር በሚልበት በመክደኛው ላይ ሆኖ ይናገር ነበር፤ ለመረጣቸው ለያዕቆብ ልጆች፥ በእግዚአብሔር በሕጉና በትእዛዙ ጸንተው ለሚኖሩ ለቅዱሳኑም የእግዚአብሔር ብርሃኑ ይገለጥላቸው ነበር።'),
  ('62fb11f1-5727-5f74-a3f2-16dac3281100', '78863fa3-b112-5871-adc8-19cdeb3119b5', '7dfa4b86-71f5-522d-a4b3-2ff941f5288d', 25, 25, 'የሚገዳደሩ ግን ምድር እንዳሰጠመቻቸው እንደ ቆሬ ልጆች ይሆናሉ፤ እንዲሁም ኃጥኣን እስከ ዘለዓለም ድረስ መውጫ ወደሌላት ወደ ገሃነም እሳት ይገቡ ዘንድ አላቸው።'),
  ('35829e03-78bb-5eeb-a17f-3003000016b9', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 1, 1, 'በድንኳኑ ውስጥ ያዘዛችሁን ያልጠበቃችሁ፥ ከራሳችሁም ፈቃድ በቀር ፈቃዱን ያላደረጋችሁ የእስራኤል ኀያላን ወዮላችሁ! ይኸውም ትዕቢትና ትዝኅርት፥ ዝሙትና ስስት፥ ስካርና መጠጥ፥ በሐሰትም መማል ነው።'),
  ('6d67c0e1-f911-531b-a7ae-aebf108813a3', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 2, 2, 'ስለዚህም ቍጣዬ በእሳት ፊት እንደ አለ ገለባ በእናንተ ላይ ይነድዳል፤ ተራራውንም እንደሚያቃጥል እሳት፥ የደቀቀውንም ትቢያ ከምድር አፍሶ ከሥራው የተነሣ ፍለጋው ወደማይገኝበት ወደ ሰማይ እንደሚበትነው፥ እንደ ዐውሎ ነፋስ፥'),
  ('01330976-f376-557f-a52d-1d65e575cfe7', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 3, 3, 'እንዲሁ ክፋትን የሚሠሩአትን ሁሉ አጠፋቸዋለሁ ይላል የእስራኤል ቅዱስ እግዚአብሔር። ሁሉን የሚገዛ እግዚአብሔርንም አስቡት፤ የሚሳነውም የለም።'),
  ('57b85550-e231-55c3-aafb-b6dbf6851360', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 4, 4, 'የሚወድዱትንም ይወድዳቸዋል፤ በትእዛዙም የሚሄዱትን በደላቸውንና ኀጢአታቸውን ያስተሰርይላቸዋል፤ በአለማመንም ደንቆሮዎችና የልብ ፈዛዞች አትሁኑ።'),
  ('862b78cc-a6a5-50f6-a77c-f7edcf0b5a2a', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 5, 5, 'ልቡናችሁንም ለእግዚአብሔር የቀና አድርጉ፤ ነፍሳችሁን ታድኑ ዘንድ በእርሱ እመኑ፤ በመከራችሁም ቀን ከጠላታችሁ እጅ አድናችኋለሁ።'),
  ('2c84e20d-3ee4-5c0d-ad47-70bf889234f9', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 6, 6, 'በምትጠሩኝም ጊዜ እነሆ ከእናንተ ጋር አለሁ እላችኋለሁ፤ ከጠላቶቻችሁም እጅ አድናችኋለሁ፤ በእኔም አምናችኋልና፥ ትእዛዜንም አድርጋችኋልና፥ ከሕጌም አልወጣችሁምና፥ እኔ የምወደውን ወዳችኋልና በመከራችሁ ቀን ቸል አልላችሁም ይላል ሁሉን የሚገዛ እግዚአብሔር።'),
  ('8cdc3130-9d84-51e5-a0e1-8849e248080e', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 7, 7, 'የሚወድዱትንም ይወድዳቸዋል፤ ርኅሩህና ይቅር ባይ ነውና፥ ትእዛዙን የሚጠብቁትን ይጠብቃቸዋል።'),
  ('d8563f09-2b0b-514c-ad8b-d83423a125c7', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 8, 8, 'ቍጣውንም ብዙ ጊዜ ይመልስላቸዋል፤ ሥጋዊና ደማዊ እንደ ሆኑ የሚያውቃቸው ስለ ሆነ ይቅር ባይ ነውና፥ በመቅሠፍቱ ሁሉ አያጠፋም፤ ነፍሳቸውም ከሥጋቸው በተለየች ጊዜ ወደ መሬትነታቸው ይመለሳሉ።'),
  ('81ef95a9-13b5-5468-afd9-fe0a33df51fb', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 9, 9, 'ካለመኖር ፈጥሯቸዋልና፥ ካለመኖር ያመጣቸው ዘንድ እግዚአብሔር እስኪወድ ድረስ የሚኖሩበትን ቦታ አያውቁም፤ ዳግመኛም እርሱ ነፍሳቸውን ወሰደ፤ የመሬት ባሕርይንም ወደ መሬትነቱ መለሰ።'),
  ('8ada5e99-5ca6-546b-aa2c-4a3b3a59c2ff', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 10, 10, 'ዳግመኛም ፈቃዱ ካለመኖር ወደ መኖር ያመጣቸዋል።'),
  ('15aced62-1d0e-5315-a44c-84af84856082', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 11, 11, 'እግዚአብሔርን የካደ ጺሩጻይዳን ግን በእግዚአብሔር ፊት መታበይን አበዛ፤ እስከ ወደደባትም ቀን ድረስ በተወው ጊዜ ራሱን ከፍ ከፍ አደረገ።'),
  ('bd9fc55d-da7d-5066-ac05-04391b9eb511', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 12, 12, 'እንዲህም አለ፥ “ዘመኔ እንደ ሰማይ ዘመን ሆነ፤ ፀሐይንም የማወጣ እኔ ነኝ፤ እስከ ዘለዓለምም ድረስ አልሞትም።”'),
  ('d427d35b-e17e-55a7-a454-46e4abc26279', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 13, 13, 'ይህንም ነገር ተናግሮ ሳይጨርስ ስሙ ጥልምያኮስ የሚባል መልአከ ሞት ወርዶ ልቡን መታው፤ በዚያችም ሰዓት ሞተ፤ ፈጣሪውን አላመሰገነውምና ከትዕቢቱ ብዛት፥ ከሥራውም ክፋት የተነሣ ከአማረ ኑሮው ተለይቶ ጠፋ።'),
  ('5d79d952-d495-5b0e-a0be-f0cb736939f8', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 14, 14, 'የከለዳውያን ንጉሥ ሠራዊት ግን ሊወጉት ወድደው፥ ከከተማውና ከአገሩ አደባባይ ውጭ ሰፍረው ሳሉ በሞተ ጊዜ ወጥተው ሀገሩን አጠፉ፤ ከብቱንም ሁሉ ዘረፉ፤ ከቅጥር እስከሚጠጋ ወንድ ድረስ አላስቀሩም።'),
  ('9197b63a-568c-57c8-a3bf-26333f17dfc3', 'd20c4f0e-9938-5986-ab25-add21592095d', '3fa881ce-b0d1-5ba8-a123-8487ddc75f40', 15, 15, 'ገንዘቡን ሁሉ ዘረፉ፤ ቈሳቍሱንም ወሰዱ፤ ከተማውንም በእሳት አቃጥለው ወደ ሀገራቸው ተመለሱ።'),
  ('a352ba9f-8664-5a72-acab-96ed680dd33d', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 1, 1, 'የአመኑ እሊያ አምስቱ የመቃቢስ ልጆች ግን ለጣዖት የተሠዋውን መሥዋዕት መብላትን እንቢ ብለው ሰውነታቸውን ለሞት ሰጡ።'),
  ('fa83f3f8-39ed-5ab0-a51c-cd2fa5de2fee', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 2, 2, 'ይህ ዓለም እንደሚያረጅና እንደሚያልፍ፥ ተድላውም ለዘለዓለም እንደማይኖር ዐውቀው በሰማይ ከአለው እሳት ይድኑ ዘንድ ሰውነታቸውን ለእሳት ሰጡ።'),
  ('0f0d0ebc-9f15-5d80-af7d-7711e38493a4', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 3, 3, 'ሰውን ከመገዳደር እግዚአብሔርን መገዳደር እንደሚከፋ፥ ከንጉሥም ቍጣ የእግዚአብሔር ቍጣ እንደሚከፋ አውቀዋልና።'),
  ('343c915c-8a77-5df3-ab42-b3b44bb7108c', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 4, 4, '“አቤቱ፥ በምድር ላይ ብዙ ዘመን ከመኖር በገነት አንዲት ቀን ደስ መሰኘት ይሻላል፤ ከብዙ ዘመኖችም የአንዲት ሰዓት ይቅርታህ ይሻላል፤'),
  ('7d540bac-3888-5140-af23-236d2788e4e0', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 5, 5, 'የእኛ የሰዎች ዘመናችን ምንድን ነው? እንደ ጥላ የሚያልፍ፥ በእሳት ዳርም እንደ አለ ሰም አይደለምን?'),
  ('e0872dcf-f631-5812-a638-0d52df144736', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 6, 6, 'አቤቱ አንተ ግን ለዘለዓለም ትኖራለህ፤ ዘመንህም የማይፈጸም ነው፤ ስም አጠራርህም ለልጅ ልጅ ነው።”'),
  ('7bc66f47-8cc7-51f2-aa46-9579702648cd', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 7, 7, 'የመቃቢስ ልጆችም ይኸንና የሚመስለውን ሁሉ ዘመሩ፤ በእግዚአብሔር መታመንን መረጡ፤ ርኩስ መሥዋዕትን መብላትንም እንቢ አሉ፤'),
  ('f6b85e59-d75b-58ef-a4fc-1c2e027320b7', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 8, 8, 'ስለዚህም ሙታን እንደሚነሡ፥ ከትንሣኤም በኋላ ፍርድ እንደሚፈረድ ዐውቀው ስለ እግዚአብሔር ብለው ሰውነታቸውን ለሰማዕትነት ሰጡ።'),
  ('834ad383-2407-5836-af00-9291e37d1b71', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 9, 9, 'የሙታንን ትንሣኤ የማታውቁና የማታምኑ ሰዎች! ከዚች ከምታልፍ ከምድራዊት ሕይወታቸው ይልቅ ኋለኛዪቱ ሕይወታቸው እንደምትበልጥ ዐውቀው ሰውነታቸውን በአንድነት ለሞት ከሰጡና ወንድማማችነታቸው ከአማረ ከእነዚህ ከአምስቱ ሰዎች የተነሣ ዕወቁ፤'),
  ('b7aaf573-51a8-5dd4-a861-e5c94d2e5dec', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 10, 10, 'ሁሉ እንዲያልፍ ዐውቀው ስላመኑበት፥ ለጣዖትም ስላልሰገዱ፥ የሞተውንና የረከሰውንም መሥዋዕት ስላልበሉ፥ ከእግዚአብሔር ምስጋናን ያገኙ ዘንድ ሰውነታቸውን ለሞት ሰጡ።'),
  ('0beb5aaa-60fa-5191-a818-b45f2345240a', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 11, 11, 'ስለዚህም በኋለኛዪቱ ቀን በነፍስና በሥጋ ደስ እንደሚያሰኛቸው ዐውቀው ሚስትና ልጆች እያሏቸው የዚህን ዓለም ጣዕምና የሞትን ምሬት አላወቁም፤ በኋለኛዪቱም ቀን በነፍስና በሥጋ ትንሣኤ እንዲደረግ ዐውቀው ሰውነታቸውን ለሞት ሰጡ።'),
  ('be09ab09-0359-5b50-aac8-feec77ea22e7', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 12, 12, 'የእግዚአብሔርን ሥርዐት የጠበቁ ሕማምና ኀዘን፥ ሞትም በሌለበት በሚመጣው ዓለም ለልጅ ልጅና ለረጅም ዘመን፥'),
  ('8a978c26-6014-5818-accf-e81b951cf196', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 13, 13, 'የእግዚአብሔርን ቃል ከአመኑ ደጋግ ነገሥታትና መኳንንት ጋር እንደሚነግሡ ዐውቀው፥ ኋላም የሚደረገውን በልቡናቸው አይተው፥ በእሳት መካከል እንደ ሰም ሰውነታቸውን ለሞት ሰጡ።'),
  ('07d44ef8-fc1a-5602-a918-8eee09cc4820', '486d72c0-fdfa-5923-a5fb-e0680a952b8b', 'd93caacf-d9ce-5ef9-a79d-d0afc7c7e331', 14, 14, 'ፊታቸውም ከፀሐይ ሰባት እጅ እንደሚያበራ፥ ሁሉም በነፍስና በሥጋ በሚነሣ ጊዜ በፍቅሩ ደስ እንደሚላቸው ተስፋ አድርገው ሰውነታቸውን ለሞት ሰጡ።'),
  ('e002def2-8f9d-561c-a6f8-2e65e8fc0754', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 1, 1, 'የአይሁድና የሳምራውያን፥ የፈሪሳውያንና የሙታንን ትንሣኤ የማያምኑ የሰዱቃውያን ነገር እኔን እጅግ ያሳዝነኛል፤ ልቡናዬም ያውቀዋል። አይሁድ፦ እንብላ፤ እንጠጣም፤ ነገም እንሞታለን፤ በዚያም የምናየው የለም ይላሉ።'),
  ('09d5a39b-e609-5415-aff4-8bcdb73760b0', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 2, 2, 'ሳምራውያን ግን ሥጋችን ትቢያ ይሆናልና አይነሣም ይላሉ።'),
  ('7ff15c7b-b6d8-597a-a996-c343f5b11358', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 3, 3, 'ትንሣኤም በተደረገ ጊዜ የነፍሳችንን መነሣት እናምናለን። ነፍስ እንደ ነፋስ የማትታይና እንደ ነጐድጓድ ድምፅ ስለ ሆነች እነሆ እዚህ አለች የማይሏትና የማትታይ ስለ ሆነች ሥጋ ቢሞት አትሞትምና።'),
  ('a988ad05-dbf8-5c7b-a017-a8d856f88f62', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 4, 4, 'ሥጋችን ግን በሁሉ ትታያለች፤ ዐመድና ትቢያም ትሆናለች። አውሬዎች ይበሏታልና፥ ትሎችም በመቃብር ይበሏታልና።'),
  ('8f5cac47-caf7-5698-a3a3-580759a31f6d', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 5, 5, 'እነዚያም የበሏት እንደ ሣር ይሆናሉና፥ እንዳልተፈጠሩም ትቢያ ይሆናሉና ዐመድ ይሆናሉ፤ ፍለጋቸውም አይገኝም። የፈረሱ ሥጋዎች የት ይገኛሉ?'),
  ('fea4b87b-afb6-5eda-a5b4-ba6ae739cfd1', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 6, 6, 'ፈሪሳውያንም እንዲህ ይላሉ፥ “የሙታንን መነሣት እናምናለን፤ ነገር ግን ነፍሳትን በምድር ያይደለ በሰማያት ሌላ ሥጋ ያለብሳቸዋል።”'),
  ('a6f38700-844c-5ed4-ade9-74db2da6a66d', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 7, 7, 'ሰዱቃውያንም እንዲህ ይላሉ፥ “ነፍሳችን ከሥጋችን ከወጣች በኋላ ከሞት አንነሣም፤ ለነፍስና ለሥጋም ትንሣኤ የላቸውም፤ ከሞትንም በኋላ አንነሣም።”'),
  ('e3afe7a1-6b2d-5089-aa47-6d85d6bb6080', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 8, 8, 'ስለዚህም እጅግ ፈጽመው ይስታሉ፤ በእግዚአብሔርና በጌትነቱም ላይ ጽርፈትን ይናገራሉና የእነርሱ ነገር ያሳዝነኛል።'),
  ('c5c35af6-e994-550c-a4ff-39fc4152b9d9', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 9, 9, 'የሚያጸድቃቸው እግዚአብሔርንም አላመኑትምና ለመዳን ተስፋ የላቸውም፤ ለመዳንና ከሙታን ለመነሣትም ተስፋ የላቸውም።'),
  ('3f3f30e9-184e-56d3-a006-f589bcf06a54', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 10, 10, 'አንተ ዕውር አይሁዳዊ ካለመኖር የፈጠረህን፥ እንደ ምራቅም ስትሆን ሰው ያደረገህን እግዚአብሔርን አላዋቂ ታደርገዋለህን? በምሳሌውና በመልኩ የፈጠረህ ነፍስህንና ሥጋህን አዋሕዶ ማስነሣት ይሳነዋልን?'),
  ('0db21dd9-fa4f-55fe-aef5-26d05a9eb241', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 11, 11, 'ከእግዚአብሔር እጅ አታመልጥምና እንደዚህ አታስብ፤ ሳትወድ ትነሣለህ፤ በሞትህም ጊዜ የተያዝህባት የሲኦል ገመድ በአንገትህ አለችና ሳትወድ ይፈረድብሃል።'),
  ('9910a770-ecdb-54c6-a370-5631ca81f98d', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 12, 12, 'በአንገትህ የታሠረች ያች ገመድም በእናትህ ማኅፀን ከሲኦል ግንድ ለአንተ ትበቅላለችና። አንተም ባደግህ ጊዜ እርሷም ታድጋለችና።'),
  ('81ec4e7a-3605-5a4d-a522-ab213c704618', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 13, 13, 'አንተም በሞትህ ጊዜ በአንገትህ ያኖሯታል፤ ግንዷንም በሳቧት ጊዜ እርስዋ ታመጣቸዋለች፤ ቅርንጫፎችዋንም ትስባለች።'),
  ('4c126b94-6a6b-58fd-a61e-b359b9ef62ee', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 14, 14, 'ኃጥኣን ሁሉ በአንገታቸው ገመድ እንዳለ በውስጧ ተይዘው አሉና።'),
  ('3e460eef-c656-58df-a714-84f15f9db319', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 15, 15, 'የኃጥኣንም ነፍሳት ሁሉ ከአሉበት ከሰማይ ዳርቻ ይመጣሉ፤ እንደዚሁም ገመድህ ነፍስህን ካለህበት ስባ አምጥታ ወደ ሲኦል ታገባሃለች።'),
  ('b928b1f4-fe44-5352-ae24-40d8305c1b43', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 16, 16, 'ሥጋህም ከነፍስህ ከተለየ በኋላ እንደ አባታችን እንደ አዳም ሥጋ ፍጹም ሆኖ በእግዚአብሔር በቸርነቱ ጠል ይነሣል። በዚያም በደልንና ኀጢአትን እንደ ሠራህ እንደ አለማመንህ ፍዳህን ትቀበላለህ።'),
  ('beede3f7-e3f2-55b7-af93-db23525e8698', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 17, 17, 'ሌላውን ብቻ የምታስት አይምሰልህ፤ ራስህም ትስታለህ፥ በስሕተትህም በመቃብር ትኖራለህ፤ ከእግዚአብሔርም ትእዛዝ ወጥተው ይስቱ ዘንድ የሙታን ትንሣኤ የለም ትላለህ።'),
  ('1f5bb276-60b0-57b9-adc4-3147c6566d4e', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 18, 18, 'እንደ ሠራኸው ሥራህ ፍዳህን ይሰጥህ ዘንድ ያስነሣሃል እንጂ በትቢያና በዐመድ ውስጥ ማን ይተውሃል?'),
  ('3ad42de5-9d7d-56b4-a47a-bd119daf3e6e', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 19, 19, 'ያንጊዜ ግን በነፋስ ውስጥ ያለ ነፋስ ባሕርይህም ቢሆን፥ በውኃ ውስጥ ያለ ውኃ ባሕርይህም ቢሆን፤ በመሬት ያለ መሬት ባሕርይህም ቢሆን፥ በእሳትም ውስጥ ያለ እሳት ባሕርይህም ቢሆን ይመጣል።'),
  ('13493db0-63d1-5b3d-ae63-677619176348', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 20, 20, 'በአንተ ያደረች፥ በጨለማ ቦታ የምትኖር ነፍስም ብትሆን ትመጣለች።'),
  ('cb90dc80-af0e-54cc-a5ff-7683e8ab7ff4', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 21, 21, 'በገነት በደስታ የሚኖሩ የጻድቃን ነፍሳትም ይመጣሉ።'),
  ('799f8625-53b9-54ef-a1e4-1e07b84436ce', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 22, 22, 'አንተም አይሁዳዊ፥ አንተም ሳምራዊ፥ አንተም ፈሪሳዊ፥ አንተም ሰዱቃዊ እስኪፈረድብህ ድረስ በጨለማ ትኖራለህ።'),
  ('c8b01a80-9429-543a-aa7a-26d948e2be8d', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 23, 23, 'ያንጊዜም ሰውን ስለ አሳትህ እንደ ሥራህ እግዚአብሔር እንደሚከፍልህ ታያለህ።'),
  ('e27411a1-a2e2-5007-ac33-2eef5b2f6f10', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 24, 24, 'እንዲህም ትላቸዋለህ፦ የሞቱ ሰዎች አይነሡም፤ ነገ እንሞታለንና እንብላ፤ እንጠጣም፤ በሙሴም ወንበር ተቀምጠህ በቃልህ የሙታን ትንሣኤ የለም ትላለህ።'),
  ('a947a53f-c084-5264-a47f-967ff284cb90', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 25, 25, 'ስለዚህም የኦሪትን መጽሐፍ እያወቅህ፥ የመጻሕፍትንም ቃል እያስተማርህ ሳትህ፤ ሰውን ከምታስት ሳትማር በቀረህ ይሻል ነበር።'),
  ('64dbe087-bdea-58f5-a386-ddd3d6b0dfba', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 26, 26, 'በክፉ ትምህርትህና በማይጠቅም ቃልህ የእግዚአብሔርን ሕዝብ ከምታስክድ የመጻሕፍትን ቃል በአላወቅህ ይሻልህ ነበር።'),
  ('5d1036e9-5741-565b-a2e1-5577b2febcfd', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 27, 27, 'አንተ ግን እንደ ሥራህና እንደ ከንፈርህ ፍሬ ይሰጥሃል፤ እግዚአብሔር ፊት አይቶ አያዳላምና፥ በጎ ሥራንም ለሚያስተምሩ ለወዳጆቹ ከአዘጋጀው ጸጋ ይሰጣቸዋልና።'),
  ('c76233e4-c38e-5720-a402-dece32ea88d4', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 28, 28, 'አንተም ከሚፈረድብህ ከእግዚአብሔር እጅ የምታመልጥበት የለም፤ እንደ ሥራህም ይከፍልህ ዘንድ አለው፤ አንተና ያስተማርሃቸውም በአንድነት ይፈረድባችኋል።'),
  ('24192da4-50e5-5f18-a9b1-d2fb16d80ce6', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 29, 29, 'ሙታን እንደሚነሡም ዕወቅ፤ ሕጉን የጠበቁ ቢሆኑም ይነሣሉ፤ በመቃብር መቈየት አይችሉም፤ ዝናም በዘነመ ጊዜ ምድር ሣርን እንደምታወጣ ትእዛዙ ያወጣቸዋልና።'),
  ('265179c0-c6b1-5a55-a522-fca1af8f81fb', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 30, 30, 'ዝናም ምድርን ባጠገባት ጊዜ ርጥብ እንጨት ቅጠልን እንደምታወጣ፥ ስንዴም ፍሬን እንደምታፈራ፥ እህልም ዝርዝርን እንደምታስገኝ፥ እግዚአብሔርም ከወደደ ፍሬዋን ትከለክል ዘንድ እንደማትችል፥'),
  ('b0d27828-98fc-5f87-a841-7c434a9db18a', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 31, 31, 'የፀነሰችም ሴት ምጥ በያዛት ጊዜ ማኅፀኗን መዝጋት፥ ሳትወልድም ማምለጥ እንደማትችል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e96d4b82-99f5-5db9-accb-4cf0d786bb2b', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 32, 32, 'ምድርም እንደዚሁ በእርስዋ የተሰበሰቡትን ታወጣለች፤ የእግዚአብሔርንም ቃል ከሰማች በኋላ ማኅፀንዋን መዝጋት አትችልም፥ ነገር ግን ከእግዚአብሔር የታዘዘ ጠል ወደ እርስዋ ይወርዳልና በአንድ ጊዜ ትወልዳቸዋለች።'),
  ('725cbb55-6d8a-5970-a9f9-815ccef31c2c', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 33, 33, 'ሥጋዎችም ሬሳዎቻቸው በወደቁባቸው ቦታዎች ይሰበሰባሉ፤ የነፍሳት መዛግብት ቤቶችም ይከፈታሉ፤ ነፍሳትም ቀድሞ ወደ ተለዩበት ወደ ሥጋ ይመለሳሉ።'),
  ('6f70dfe8-fe7d-584c-aeb2-afd6d8147610', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 34, 34, 'መለከትም በተነፋ ጊዜ ሙታን እንደ ዐይን ጥቅሻ ይነሣሉ፤ በእግዚአብሔርም ፊት ይቆማሉ፥ እንደ እጃቸውም ሥራ ይሰጣቸዋል።'),
  ('6292ef49-d431-5c40-a4a1-d3c7c123812d', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 35, 35, 'ያንጊዜም ከሙታን ጋራ እንደምትነሣ ታያለህ፤ በምድር ላይ የሠራኸውንም ሥራ ሁሉ ታደንቃለህ፤ በዐይኖችህም ፊት ተጽፈው ባየሃቸው ጊዜ ያንጊዜ የማይረባ ጸጸትን ትጸጸታለህ።'),
  ('5c7f8ba6-bb08-5399-abdf-d65c3e2d8f78', '3ba002d9-b7cf-52fa-ad49-73466a7485f1', 'c0a4f0eb-f4a6-52d8-abef-f1560f29f910', 36, 36, 'ከሙታን ጋራም እንደምትነሣ፥ እንደ ሠራኸውም ሥራ እንደምትቀበል ታውቃለህ።'),
  ('1a000a15-7a17-5643-aaa8-504c2bed02d1', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 1, 1, 'በጎ ሥራቸውን ያገኙ ያንጊዜ ደስ ይላቸዋል፤ ሙታን አይነሡም እያሉ ቸል ያሉ ግን ሙታን ከማይጠቅም ክፉ ሥራቸው ጋራ እንደ ተነሡ በአዩ ጊዜ ያንጊዜ ያዝናሉ።'),
  ('b86ebd91-914a-517e-a06f-0a65ecb3f5be', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 2, 2, 'ያም የሠሩት ሥራቸው ይፈርድባቸዋል፤ የሚከራከራቸውም ሳይኖር እንደሚፈረድባቸው እነርሱ ራሳቸው ያውቃሉ።'),
  ('b522b868-99c4-567d-a261-3aafbffa2b39', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 3, 3, 'በልቅሶና በፍርድ ቀን በቍርጥ ፍርድ ቀንና በእግዚአብሔር ቀን ዝንጉዎች በሚቆሙበት ቦታ ይቆማሉ።'),
  ('fcc5eec5-b4f0-5cb3-a85b-c9f16734d959', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 4, 4, 'በፍጹም ጨለማ ቀን፥ በጉም ቀን፥ በብልጭልጭታ ቀን፥ በመብረቅ ቀን፥'),
  ('ebe958f1-d954-5134-a9b0-d3cbc8f4cfc2', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 5, 5, 'በፍርሀትና በመንቀጥቀጥ ቀን፥ በብርድና በሙቀት ቀን፥ በውርጭም ቀን፥'),
  ('2bfd6f3a-2665-5127-a4b9-750d481a3f6e', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 6, 6, 'ክፉ ሰው ክፋትን እንደ ሠራ ፍዳን በሚቀበልባት ቀን፥ ንጹሕ ሰውም ንጹሕ ሥራን እንደ ሠራ ዋጋውን በሚቀበልባት ቀን፥ ኀጢአተኛም ኀጢአትን እንደ ሠራ ፍዳውን እንደሚቀበል፥'),
  ('508ed23f-9b64-5023-a179-9e5ffb785adb', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 7, 7, 'ጌታም ከባርያው በማይከብርባት ቀን፥ እመቤትም ከባርያዋ በማትከብርበት ጊዜ፥'),
  ('dba91646-a7e4-54f8-a44b-641b07b8425d', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 8, 8, 'ንጉሡም ከድሃው በማይከብርበት ጊዜ፥ ሽማግሌውም ከሕፃኑ በማይከብርበት ጊዜ፥ አባት ከልጁ በማይከብርበት ጊዜ፥ እናትም ከልጅዋ በማትከብርበት ጊዜ፥'),
  ('0350f3dc-894b-566d-a809-780b3bb7a7cd', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 9, 9, 'ባለጸጋው ከድሃው በማይከብርበት ጊዜ፥ ትዕቢተኛም ከተዋረደው ሰው በማይከብርበት ጊዜ፥ ታላቁም ከታናሹ በማይከብርበት ጊዜ፥ የፍርድ ቀን ናትና፥ የፍዳና የቅጣት ቀን ናትና፥ ሁሉም እንደ ሠራው የሚቀበልባት ቀን ናትና።'),
  ('d88ca107-9d56-5e08-ae7e-720b27c4607c', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 10, 10, 'በጎ ሥራ የሠሩም ዋጋቸውን የሚቀበሉባት ቀን ናትና፥ ክፉ የሠሩም ክፉውን የሚቀበሉባት ቀን ናትና።'),
  ('0632cdb6-9d2f-5bbd-a04f-17127a9265a7', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 11, 11, 'ዋጋቸውን ያገኙም ደስ የሚሰኙባት ቀን ናትና፥ ክፉውንም የተቀበሉ የሚያዝኑባት ቀን ናትና። ሙታን አይነሡም እያሉ መጻሕፍትን የሚያሳብሉትም ያያሉ።'),
  ('41234ef8-debe-58a9-a3c2-6f86b8d089b3', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 12, 12, 'ያንጊዜም የምድር ኃጥኣን ስለ ሠሩት ኀጢአታቸውና በምድር ሳሉ መልካም ባለማድረጋቸው ስለሚያገኛቸው መረጋጋት ስለሌለው ኀዘናቸው ያለቅሳሉ።'),
  ('d0d8a8d6-625e-5cbe-a996-2799425a2f65', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 13, 13, 'እንደዚሁም በምድር ላይ ሳሉ በጎ ሥራን ሠርተዋልና በጎ ሥራን የሠሩ የደጋጎች ደስታ እስከ ዘለዓለም ድረስ አይፈጸምም።'),
  ('724ef25b-4001-5a1b-a3fc-ac84da37c92f', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 14, 14, 'ከሞትም እንደሚነሡ አውቀዋልና ከፈጣሪያቸው ሕግ አልወጡም።'),
  ('0e00021a-d893-506a-a379-45709ea836ea', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 15, 15, 'ከትእዛዙም ስላልወጡ ሁለት ሕይወትን ይወርሳሉ፤ በምድርም ላይ ዘራቸውን አበዛ፤ ልጆቻቸውንም ባረካቸው።'),
  ('07b86b22-1124-57d4-af19-3fbc5e87f593', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 16, 16, 'በሰማያትም በትንሣኤ ቀን ባለጸጎች በሚደኸዩበት ጊዜ ለአባቶቻቸው የማለላቸውን መንግሥተ ሰማያትን ያወርሳቸዋል።'),
  ('14cf9c63-e986-5f44-a80a-8e339907e5f9', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 17, 17, 'ክፉ የሚሠሩና የሙታንን መነሣት የማያምኑ፥ የእግዚአብሔርን ሕግና የትንሣኤንም ቀን የማያስቡ ያለቅሳሉ።'),
  ('7de7a138-22e3-553f-a4a1-d2d23cc4a7b3', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 18, 18, 'ያንጊዜም መጨረሻ የሌላት፥ ድኅነትና መረጋጋት የሌለባት የምታገኛቸውን መከራ ያያሉ፤ በልቡናቸውም መረጋጋትና ዕረፍት የሌለው ኀዘን ይሆናል።'),
  ('b6d479ab-1222-59b5-a5d4-b6b00eca2419', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 19, 19, 'የማያንቀላፋ ትል፥ የማይጠፋም እሳት ያገኛቸዋል።'),
  ('8ffa7257-7ece-5699-a70c-a5d57b47f536', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 20, 20, 'ሥጋቸውም ባለበት ቦታ እሳትና ድኝ፥ ጥቅል ነፋስ፥ ውርጭና በረድ፥ ቀቅም በላያቸው ይዘንማል።'),
  ('69593bd2-6d3b-537e-ac40-9607c812387a', '4ff07f78-17a6-5b43-af3d-3c48e0ec9662', '85c57c4c-3491-5e38-a60f-70cbb2df18be', 21, 21, 'የሙታንንም መነሣት በማያምኑ ሰዎች ላይ ገሃነመ እሳት አለባቸው።'),
  ('085911c5-2c83-5bf6-a3f2-1475b739282e', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 1, 1, 'በሥጋህ፥ በእጅህና በእግርህ ጥፍር፥ በራስህም ጠጕር ያለውን እስኪ አንተ ራስህ አስበው፤ በቈረጥሃቸው ጊዜ ፈጥነው ይወጣሉና፥ ለማመን ልብና አእምሮ ከአለህ በዚህ ዕወቅ።'),
  ('979c0a36-7b56-523e-a9c8-e310d5cc9814', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 2, 2, 'እነዚህ የእጅህና የእግርህ ጥፍር፥ የራስም ጠጕር ከወዴት ይወጣሉ ትላለህ? ከሞት እንደምትነሣ ታውቅ ዘንድ በሌላ ሥጋ ያይደለ በአንተ ሥጋ የሚደረግ ትንሣኤን እንድታውቅ ይበቅሉ ዘንድ እግዚአብሔር ያዘጋጀው አይደለምን?'),
  ('849c5c27-77f5-553b-abff-db5e6f30de6e', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 3, 3, 'አንተም የሙታን ትንሣኤ የለም እያልህ ሕዝቡን ስለአሳትህ ኀጢአትንና በደልን እንደ ሠራህ በሙታን ትንሣኤ ጊዜ ፍዳህን ትቀበላለህ።'),
  ('1948a58a-be78-526b-ac2a-7f634b6e1a07', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 4, 4, 'አሁንም የፍዳህ ቀን በደረሰችብህ ጊዜ ታያታለህ፤ ስንዴም ቢሆን፥ ገብስም ቢሆን አንተ ስንኳ የዘራኸው ይበቅል ዘንድ እንቢ አይልምና።'),
  ('c9877016-a8b7-585d-a2f0-ee99ff4d1f00', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 5, 5, 'ዳግመኛም አንተ የተከልኸው ተክል አልበቅልም አይልም፤ የወይን ተክልም ቢሆን፥ የበለስ ተክልም ቢሆን ቅጠሉና ፍሬው አይለወጥም።'),
  ('bf08278d-c071-5889-a7ff-b35f334d507f', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 6, 6, 'ወይን ብትተክልም በለስ ይሆን ዘንድ አይለወጥም፤ በለስም ብትተክል ወይን ይሆን ዘንድ አይለወጥም፤ ስንዴም ብትዘራ ገብስ ይሆን ዘንድ አይለወጥም፤'),
  ('cbbae75e-26c6-5262-a4e2-fbf5faf373b0', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 7, 7, 'ገብስም ብትዘራ ስንዴ ይሆን ዘንድ አይለወጥም። ነገር ግን ሁሉ በየዘሩና በየወገኑ፥ በየፍሬውና በየእንጨቱ፥ በየቅጠሉና በየሥሩ፥ ከእግዚአብሔር በሚገኝ የምሕረት ጠል በረከትን ተቀብሎ ፍሬን ያወጣል።'),
  ('6b5dd935-d936-5cee-ab7b-28ab69d4e93c', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 8, 8, 'እንደዚሁም ምድር እግዚአብሔር እንደ ዘራባት ነፍስንና ሥጋን ታስገኛለች፤ እግዚአብሔር የዘራቸው ሥጋና ነፍስ ተዋሕደው ይነሣሉ እንጂ በጎ ሥራ የሠሩ ሰዎች ክፉ ሥራ በሠሩ ሰዎች አይለወጡም፤ ክፉ ሥራም የሠሩ ሰዎች በጎ ሥራን በሠሩ ሰዎች አይለወጡም።'),
  ('c8ec599b-773d-5cc8-a910-070411e923c8', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 9, 9, 'መለከት የሚነፋበትም ሰዓት በደረሰ ጊዜ ሙታን ከእግዚአብሔር በሚገኝ የጠል ምሕረት ይነሣሉ፤ በጎ ሥራ የሠሩ ሰዎች የሕይወት ትንሣኤን ይነሣሉ፤ ዋጋቸውም እግዚአብሔር ለደጋጎች ያዘጋጀው፥ መከራና ደዌ የሌለበት፥ ከዚህም በኋላ ዳግመኛ የማይሞቱበት የንጹሓን ማደሪያ የደስታ ገነት ነው።'),
  ('692d11c0-4ba1-51a8-aeed-e36c2375511b', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 10, 10, 'ክፉ ሥራ የሠሩ ግን የደይን ትንሣኤ ተነሥተው ከአሳታቸው ከዲያብሎስ ጋራ፥'),
  ('1fbc3737-6f5e-53de-a0af-cebe13fd5d81', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 11, 11, 'ከሰው ልጆች ሁሉ አንድ ሰው ስንኳ ይድን ዘንድ ከማይወዱ ከሠራዊቶቹ ከአጋንንትም ጋራ ወደ ዘለዓለም ቅጣት ይሄዳሉ፤'),
  ('b8c492b9-e95e-5afe-a514-e012a2a2ac20', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 12, 12, 'የጨለማ ዳርቻ ወደ ሆነ፥ ጥርስ ማፋጨትና ልቅሶ ወዳለበት፥ ይቅርታና ምሕረት ወደሌለበት፥ እስከ ዘለዓለም ድረስ መውጫ ወደሌለበት ወደ ገሃነም ይወርዳሉ። በሥጋቸው ሳሉ በምድር ላይ በሕይወታቸው በጎ ሥራ አልሠሩምና።'),
  ('cca29586-81a9-5276-ae81-8aa8408d6adb', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 13, 13, 'ስለዚህም ነፍስና ሥጋ በትንሣኤ ጊዜ ይፈረድባቸዋል።'),
  ('aff74591-57e1-55ba-af6d-a60839628931', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 14, 14, 'እግዚአብሔር የተአምራቱን ብዛት የሚያሳይባት የነፍስና የሥጋን በአንድነት መነሣት ለማያምኑ ሰዎች ወዮላቸው!'),
  ('614ce9f3-a4d3-5b40-a1a9-759d048bdd30', 'd3ae58e7-f242-5e84-a6d5-4a1813e8dad4', '185b5816-c02f-537f-ada4-6fa31e371df3', 15, 15, 'ሁሉም እያንዳንዱ እንደ ሥራውና እንደ እጁ ድካም ዋጋውን ይቀበላል።'),
  ('0bea4086-c3fd-5dd3-ad6d-4299890631f7', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 1, 1, 'የስንዴ ቅንጣት ካልፈረሰች አትበቅልም፤ ፍሬም አታፈራም። የስንዴ ቅንጣት ብትፈርስ ግን ወደ ምድር ሥር ትሰዳለች፤ ቅጠልም ታወጣለች፤ ዝርዝርም ይሆናል፤ ፍሬም ያፈራል።'),
  ('2dec295a-21e8-5710-a6d6-f158391ed870', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 2, 2, 'አንዲቱ የስንዴ ቅንጣት ብዙ ቅንጣት እንደምትሆን እናንተ ታውቃላችሁ።'),
  ('91021be4-c85c-5632-a467-23455a85993b', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 3, 3, 'እንደዚሁ ይህች ቅንጣት ከነፋስና ከውኃ፥ ከመሬትም የተነሣ ትበቅላለች፥ ፀሐይ ግን በእሳት ፋንታ ነው። ስንዴ ያለ ፀሐይ ፍሬ ማፍራት አይችልምና።'),
  ('c9298438-4d57-58b7-a977-b0010bfdcd24', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 4, 4, 'ነፋስም ስለ ነፍስ ፋንታ ነው፥ ያለ ነፋስም ስንዴ ማፍራት አይችልም፤ ውኃውም ምድርን ያጠጣታል፤ ያረካታልም።'),
  ('607422ad-14a0-5ad0-a374-20e3c802e089', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 5, 5, 'መሬትም ውኃን ከጠጣች በኋላ ሥርን ታስገኛለች፤ ጫፏም ወደ ላይ ከፍ ከፍ ትላለች፤ እግዚአብሔርም የባረካትን ያህል ታፈራለች።'),
  ('8d3d3f96-fc09-5a46-ad1d-9a74b9b82dd7', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 6, 6, 'የስንዴ ቅንጣት ግን እግዚአብሔር የፈጠራት ነባቢት ነፍስ ያደረችበት የአዳም አምሳል ነው፤ የወይን ግንድም እንደዚሁ ውኃ ይጠጣል፤ ሥርም ይሰድዳል፤ ቀጫጭኑ የሥሩ ገመድም ውኃን ይስባል።'),
  ('4634dba3-e400-5d39-ada3-3ecf9eeba2f5', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 7, 7, 'ውኃዋንም ወደ ቅጠሎች ጫፍ ያወጣታል፤ ከእግዚአብሔር የተገኘ ጠል ረጃጅም የሐረጎችን ጫፎች ያጠጣቸዋልና። በፀሐይም ሙቀት ይዘረዝራል፤ በእግዚአብሔርም ፈቃድ ፍሬን ያፈራል።'),
  ('a00265c8-3f0c-5bbf-afc7-1824bacb5028', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 8, 8, 'ልብን ደስ የሚያሰኝ በጎ መዓዛንም ያደርጋል፤ በበሉትም ጊዜ እንደማያስርብ እህልና እንደማያስጠማ ውኃ ያጠግባል፤ በጠመቁትም ጊዜ የወይን ጠጅ ይሆናል።'),
  ('6c784b00-0198-504c-a290-9dcabce9903c', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 9, 9, 'በጠጡትም ጊዜ “ወይን የሰውን ልብ ደስ ያሰኛል” ተብሎ በመዝሙር እንደ ተነገረ የሰውን ልብ ደስ ያሰኛል፤ ፈታ ፈታ ያለ ሰውም አፉን ከፍቶ በጠጣ ጊዜ ይሰክራል፤ በሳምባውም ይመላል፤ ደሙም ወደ ልቡ ይፈስሳል።'),
  ('b1b7ea09-9823-5946-a708-63c62985ea53', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 10, 10, 'የወይን ስካር እጅግ ያስታልና አእምሮውን ያሳጣዋል፤ ጐጻጕጹንና ገደሉንም እንደ ሰፊ ሜዳ ያደርገዋል፤ በእጁና በእግሩ ያለውንም እንቅፋትና እሾህ አያውቅም።'),
  ('5002130f-033c-564b-a701-4e48668f0306', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 11, 11, 'እግዚአብሔርም ፈቃዱን በሚያደርጉና የሙታንን ትንሣኤ በሚያምኑ ስሙ ይመሰገን ዘንድ በወይን ግንድና በፍሬዋ እንዲሁ አደረገ።'),
  ('f3a762f9-37d3-5d84-ad3d-77f5990a3515', '3794c371-8d61-5989-a965-cfc95cfa7a36', '4ec6bcf3-6e98-53c9-a0ed-e91b1d0e97db', 12, 12, 'የሙታንን መነሣት የሚያምኑትንም በሕይወት ማደሪያ ደስ ያሰኛቸዋል።'),
  ('b18f4eec-e42f-5e52-abe5-32ad8d2236d4', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 1, 1, 'የሙታንን መነሣት የማታምኑ ሰዎች፥ ምን ያህል ስሕተትን ትስታላችሁ? ወደማታውቁትም ቦታ በወሰዷችሁ ጊዜ፥ በነፍስና በሥጋ በአንድነት የሙታንን መነሣት ስለ አላመናችሁ ወደ ገሃነም በጣሏችሁ ጊዜ ያንጊዜ የማይረባ ጸጸትን ትጸጸታላችሁ።'),
  ('d2691f9d-34d5-58fd-a0a0-9296765663f3', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 2, 2, 'ትቢያና ዐመድ የሆኑ ሙታን እንደማይነሡ እኛ እናውቃለን እያላችሁ የባልንጀሮቻችሁን ልቡና ታስታላችሁና በጎውንም ቢሆን፥ ክፉውንም ቢሆን እንደ ሠራችሁ ዋጋችሁን ትቀበላላችሁ።'),
  ('e2bd7751-3a06-561a-a8db-313114ef5fb6', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 3, 3, 'ስለዚህም ባልንጀሮቻቸውን ያስታሉ፤ ለሞታቸው ዕረፍት የለውምና፥ ለመቅሠፍታቸውም ኀይል የለውምና፥ በድካማቸውም የጸኑ አልሆኑምና፥ በእግዚአብሔር አደባባይም ይቆሙ ዘንድ አላቸውና።'),
  ('93f290ba-10e5-5503-ad97-a46e7b7068cb', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 4, 4, 'በመዓቱም በሚገሥጻቸው ጊዜ፥ ክፉም ስለ አደረጉ በሚቈጣቸው ጊዜ እጅግ ያፍራሉ፤ የእግዚአብሔርን መንገድ ሳያውቁ ይናገራሉና። ከየት እንደ መጡም አያውቁምና።'),
  ('89b0308c-b07c-586d-aa75-06b345e304c0', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 5, 5, 'የሚሄዱበትንም ገሃነም አያውቁም፤ ቍጡዎች፥ በሥራቸውም ጠማሞችና ክፉዎች ስለ ሆኑ እንደ ልቡናቸው ጥመት ለባልንጀሮቻቸው ያስተምራሉና፤ ትንሣኤ ሙታንም የለም እያሉ ጠማማ ነገርን የሚያስተምሩ ናቸውና።'),
  ('7dccd5bc-ce61-5f14-aa42-d3cd1c10a66a', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 6, 6, 'ያንጊዜም ሙታን እንደሚነሡ ያውቃሉ፤ ለሰው ልጆች ወገን ሁሉ የሚሆነውን የሙታን ትንሣኤ ስለ አላመኑ እንደሚፈረድባቸው ያውቃሉ።'),
  ('b8844143-40e7-5341-a875-6a3abb03fdf7', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 7, 7, 'ሁላችን የአዳም ልጆች ስለ ሆንን በአዳምም ምክንያት ሞተናልና፥ ሁላችንም በአባታችን በአዳም ስሕተት ከእግዚአብሔር ዘንድ የሞት ፍርድ አግኝቶናልና።'),
  ('4e176617-3414-577f-ac5a-f5ddc82ae5ee', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 8, 8, 'ዳግመኛም በሠራነው ሥራችን ፍዳችንን እንቀበል ዘንድ ከዚያ ከአባታችን ከአዳም ጋራ እንነሣለን፤ በአባታችን በአዳም አለማወቅ ዓለም ለሞት ተገዝትዋልና።'),
  ('1b82b28b-dd85-513f-aaef-18f653f0dd82', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 9, 9, 'ስለዚህም በአዳም መተላለፍ ፍዳን እንቀበላለን፤ ሥጋችንም በመቃብር ውስጥ ቀለጠች፤ አጥንቶቻችንም ደቀቁ።'),
  ('eb3e9c0b-dd84-58c8-a8d0-835b9a531fd0', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 10, 10, 'ምድርም ቅልጥማችንን ጠጣች፤ ጠፋንም፤ ደም ግባታችንም በትቢያ ጠፋ፤ ሥጋችንም በመቃብር ተቀበረ፤ የአማረ ቃላችንም በመሬት ተቀበረ።'),
  ('fc79105c-53a8-5283-acca-9f25afc3cff8', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 11, 11, 'ከሚያበሩ ዐይኖቻችንም ትሉ ወጣ፤ መልካችንም በመቃብር ጠፋ፤ ትቢያም ሆንን።'),
  ('8a6844ed-6b4d-588c-ab8e-e1d673b532b1', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 12, 12, 'መልከ መልካም የነበሩ፥ ቁመታቸውም ያማረ፥ የቃላቸውም ንግግር የተቀላጠፈ የጐልማሶች የመልካቸው ደም ግባት ወዴት አለ? የአርበኞችስ ገናናነታቸው ወዴት አለ?'),
  ('9f6fb808-c2d5-526f-a5a0-73578fdd3a09', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 13, 13, 'የነገሥታቱ ኀይላቸው፥ የመኳንንቱስ ክብራቸው ወዴት አለ? በፈረስ መጠረር፥ በወርቅና በብርም ማጌጥ፥ በሚያንጸባርቅ የጦር መሣሪያም መጠረር ወዴት አለ?'),
  ('e21fbfc4-2988-53bd-a4f3-688e8854140e', '3517ae73-ef51-5f0d-a2c2-66af6316ae98', '590b1d0e-fdee-5e23-a0fb-f0b5588ed2fe', 14, 14, 'የመባልዕት ጣዕምና ጣፋጩ የወይን መጠጥ የት አለ?'),
  ('f9aecb09-0d03-5f06-ab68-59e396bc6d67', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 1, 1, 'ነገሥታትንና መኳንንትን፥ ታላላቆችንና ክቡራንንም፥ የተዋቡ ሴቶችንና መልካማ ቆነጃጅትንም የሰበሰብሻቸው ምድር ሆይ፥ ከአንቺ የተነሣ ወዮ!'),
  ('673417fb-83f2-5ab2-afe8-6bf677b7e1c6', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 2, 2, 'ደም ግባት ያላቸውን፥ ባተ መልካሞች የሆኑትን፥ ዕውቀትና ልቡናም ያላቸውን፥ ቃላቸውም እንደምታንጐራጕር በገና፥ እንደ ክራርና እንደ መሰንቆም አመታት ያማረ ቃል ያላቸውን፥'),
  ('e3e83b04-147f-5202-a7f7-c36690898600', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 3, 3, 'እንደ ጣፋጭ የወይን መጠጥም ደስ የሚያሰኝ ዜማ ያላቸውን፥ ዐይኖቻቸውም እንደ አጥቢያ ኮከብ የሚያበሩትን፥'),
  ('73355f29-215d-581b-ac64-2a58de162ab5', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 4, 4, 'ቀኝ እጃቸውም እንደሚሰጥና እንደሚነሣ ጽኑዕ የሆነላቸውን፥ የሚነድፉ፥ እግሮቻቸውም ለማየት ያማሩና እንደተስተካከሉ መንኰራኩሮች የሚሮጡ ኀያላን ሰዎችን የሰበሰብሻቸው ምድር ሆይ፥ ከአንቺ የተነሣ ወዮ!'),
  ('1b14a548-0a0b-53ec-a8a8-6356209b66ef', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 5, 5, 'በእግዚአብሔር ፈቃድ ተልከሃልና የመልከ መልካም ሰዎችን ነፍሳት ከሥጋቸው የለየህ ሞት ሆይ! ከአንተ የተነሣ ወዮ!'),
  ('c5e3531a-ed79-58a3-a324-9bb2cc2e304c', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 6, 6, 'አንችም ምድር! እግዚአብሔር ከአንቺ ያስገኛቸውንና ወደ አንቺ የመለሳቸውን ብዙዎች ሥጋዎችን ሰብስበሻልና ከአንቺ የተነሣ ወዮ! በፈቃደ እግዚአብሔር ከአንቺ ወጣን፤ ወደ አንቺም እንመለሳለን፤ በእግዚአብሔርም ፈቃድ በአንቺ ላይ ደስ አለን።'),
  ('03a07033-f946-58d8-afc9-75b294406839', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 7, 7, 'ለሬሳዎቻችን ምንጣፍ ሆንሽ፤ በላይሽ ተመላለስን፤ በውስጥሽም ተኛን፤ ፍሬሽን በላን፤ አንቺም ሥጋችንን በላሽ።'),
  ('a67499c5-e72b-5ddd-a93b-e89083a1cca6', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 8, 8, 'ከምንጭሽም ውኃ ጠጣን፤ አንቺም ከደማችን ምንጭ ጠጣሽ፤ ከመሬትሽ ስባት በላን፤ አንቺም የአጥንቶቻችንን ስባት በላሽ።'),
  ('7df9d612-e7d2-568f-a5af-30d0e8d3e6c3', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 9, 9, 'ምግባችን ልትሆኝ እግዚአብሔር እንዳዘዘሽ ያማረ ጠል ከአለው ከመሬትሽ እህልን በላን፤ አንቺም የሥጋችንን ደም ግባት ተቀበልሽ፤ እግዚአብሔርም እንዳዘዘሽ ለምግብሽ ትቢያን አደረግሽው።'),
  ('e1981c0e-bbf7-5a13-a969-8fe4b7e589cb', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 10, 10, 'ብዙዎች ኀያላን ነገሥታትንና መኳንንትን የሰበሰብህ፥ የፈጠራቸው እግዚአብሔርም እንዳዘዘህ ከገናናነታቸውና ከግርማቸው የተነሣ ያልፈራህ፥ ጦም አዳሪውንም ያልናቅህ ሞት ሆይ! ከአንተ የተነሣ ወዮ!'),
  ('19a8bc7e-9369-5863-a780-8b4ab7d4d987', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 11, 11, 'መልካቸውም ለአማረ ሰዎች አልራራህም፤ ኀይለኞችንና አርበኞችንም አልተውህም፤ ባለጸጎችንና ድሆችን፥ መልከ ክፉዎችንና መልከ መልካሞችን፥ ሽማግሌዎችንና ልጆችን፥ ሴቶችንና ወንዶችንም አልተውህም።'),
  ('75394707-897f-5f24-aea7-6296ac4a8dee', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 12, 12, 'በጎ የሚያስቡትንና ከትእዛዙ ያልተላለፉትንም አልተውህም፤ በሥራቸውም እንደ እንስሳ የሆኑ ክፉ ነገር የሚያስቡትንም አልተውህም። በመልካቸው ደም ግባት፥ በቃላቸውና በነገራቸው ጣዕም ፍጹማን የሆኑትን አልተውህም።'),
  ('d7f7a9dc-149b-50d9-a6d8-2b2aff16e650', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 13, 13, 'ቃላቸው ቁጡ የሆነና አፋቸውም ርግማንን የተመላ ሰዎችን አልተውህም፤ ነፍሶቻቸውንም በብርሃንና በጨለማ መዛግብትህ ሰበሰብህ።'),
  ('20b59f22-c16d-5a14-a5e1-244ff7020b62', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 14, 14, 'ምድርም መለከት እስከሚነፋበትና ሙታን እስከሚነሡበት ጊዜ ድረስ በዋሻም ቢሆን፥ በመሬትም ቢሆን ሥጋቸውን ሰበሰበች።'),
  ('f01bcedc-1274-59b2-a8a4-6b08eed0fe0d', '9ca6218f-c30d-5333-a472-8919834d24f5', 'b8f62f13-b098-56a6-a4e5-253374a1fe22', 15, 15, 'ክፉ አድራጊዎች እንደ ሠሩት ሥራቸው ዋጋቸውን ይቀበላሉ፤ በመለከት ድምፅና በእግዚአብሔር ትእዛዝ ሙታን እንደ ዐይን ጥቅሻ ይነሣሉና፥ በጎ ሥራ የሠሩም ደስ ይላቸዋል።'),
  ('912ddb44-aca3-5e87-a49e-f521aab539c1', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 1, 1, 'በፍርሀትና በመንቀጥቀጥ በፊቱ በቆምን ጊዜ በምድር የሠራነው ሥራችን ሁሉ እንደማይቀርና እንደማይሰወር እመኑኝ።'),
  ('484e7e92-a87a-5a87-a855-f34c3319dc8d', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 2, 2, 'ለመንገዳችንም ስንቅ ባልያዝን ጊዜ፥ ለሰውነታችንም ልብስ በሌለን ጊዜ፥'),
  ('4db35cd8-81cf-554e-a29a-ad25d2c81b72', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 3, 3, 'ለእጃችንም ምርጕዝ፥ ለእግራችንም ጫማ በሌለን ጊዜ፥'),
  ('27b64093-19b6-58ac-af9e-2da39dbc28a1', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 4, 4, 'ድጥም ቢሆን፥ ጐጣጕጥም ቢሆን፥ ጨለማም ቢሆን፥ እሾህም፥ አሜኬላም ቢሆን፥ የባሕር ጥልቅም ቢሆን፥ የጕድጓድም ጥልቅ ቢሆን እኛን የሚወስዱበትን ጎዳናውን በማናውቅበት ጊዜ።'),
  ('8e7733a3-cd07-537a-a5e7-24de07de8461', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 5, 5, 'የሚወስዱንንም አናውቃቸውም፤ ነገራቸውንም አንሰማም።'),
  ('a51f6e0e-c54a-5b27-a939-eea7b2bd5c00', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 6, 6, 'እነርሱ ጥቋቍሮች ናቸውና፥ ወደ ጨለማም ይመሩናልና፥ ፊታቸውን አናይም።'),
  ('64db4759-8bbb-5c81-ae06-d0cef01477b7', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 7, 7, 'ነቢዩ ዳዊት እንደ ተናገረ፥ “ነፍሴ በላዬ በአለቀች ጊዜ አቤቱ ጌታዬ ጎዳናዬን አንተ ታውቃለህ፥ በዚች በሔድሁባትም ጎዳና ወጥመድ ሰወሩብኝ፤ ወደ ቀኜም ተመልሼ አየሁ፤ የሚያውቀኝም አጣሁ፤ የማመልጥበትም የለኝም።”'),
  ('7a8efc28-467d-5361-a19c-52d3c583a9bb', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 8, 8, 'ይህንም በተናገረ ጊዜ፦ አጋንንት እንደሚዘባበቱበትና ወደማያውቀው ጎዳና እንደሚመሩት ስለሚያውቅ ነው። ወደ ቀኝና ወደ ግራም ቢመለስ የሚያውቀው ሰው አላገኘም።'),
  ('ba570a36-8944-55af-ab7a-6b4642b2a3d5', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 9, 9, 'እርሱንም የሚያውቀው አልነበረም፤ ነገር ግን በጨለማ መላእክት መካከል ነበረ።'),
  ('182a4d7b-6030-5755-aa46-e7731106eb25', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 10, 10, 'የጻድቃንን ነፍሳት ይቀበሉ ዘንድ፥ ወደ ሕይወት ብርሃን ቦታም ይወስዱ ዘንድ ወደ ደጋጉ የሚላኩ ረቂቃን መላእክተ ብርሃን ናቸው።'),
  ('41e1927e-778c-5f33-a8d7-de9b24a5e01b', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 11, 11, 'ይቀበሏቸው ዘንድ፥ በሠሩት ኀጢአታቸውም ፍዳቸውን ሊቀበሉ ወደ ተዘጋጀላቸው ዘለዓለማዊ ቅጣት ይወስዷቸው ዘንድ ወደ ኃጥኣን ነፍሳት የሚላኩ ግን መላእክተ ጽልመትና አጋንንት ናቸው።'),
  ('f8d82fee-92e7-5ac1-a6cd-74e20b785db1', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 12, 12, 'ወደ ጥፋት ለሚወስዷቸው ዕረፍትና ድኅነት ካገኛቸውም መከራ እስከ ዘለዓለም ድረስ ማምለጥና መውጣት ለሌላቸው ለኃጥአን ነፍሳት ወዮላቸው።'),
  ('f77a18fa-4c92-5470-a4b3-599d063a80b1', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 13, 13, 'በቃየን መንገድ ሄደዋልና፥ በበለዓምም በደል ዋጋ ጠፍተዋልና፥ የሚያደርጉትንም አጥተዋልና። ገንዘባቸው ያልሆነውን የባዕድ ገንዘብ በግፍ ይወስዱ ዘንድ መማለጃንና አራጣን ለመቀበል ያመካኛሉና።'),
  ('aa4aea7d-9c25-5999-a657-2ef447d02b22', '976454bc-eac9-5737-abba-9da6756f49c0', 'd1b97f25-188d-5995-ab33-7a9213e6ebd3', 14, 14, 'እነርሱም እንደ ሠሩት ሥራቸው በገሃነም እሳት ፍዳቸውን ይቀበላሉ።'),
  ('5a2a1aa9-e9ab-510d-a1bf-d6f1c09aec8e', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 1, 1, 'የራሳቸው ገንዘብና የእጃቸው ሥራ ያልሆነውን የሌላውን ገንዘብ በዐመፅ የሚሰበስቡ ሰዎች ወዴት አሉ?'),
  ('bb645287-d61e-57d5-aa1f-d886fc1bceee', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 2, 2, 'ያለ ዋጋ የሌላውን ገንዘብ ይወስዳሉና፥ የምትደርስባቸው ዕለተ ሞታቸውንም ሳያውቁ ይሰበስባሉና፥ ገንዘባቸውንም ለባዕድ ይተዋሉና።'),
  ('60850f36-7acb-5235-a7fe-4b46d589192f', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 3, 3, 'ልጆቻቸውም በአባቶቻቸው ገንዘብ ደስ አይላቸውም፤ እንደ አባቶቻቸው እንደ እነርሱ ያሉ ኃጥኣንን በስርቆትም ቢሆን በቅሚያም ቢሆን፥ አስጨንቀው የሚይዙ የኃጥኣን ወገኖች ናቸውና።'),
  ('da38a645-432b-5a99-a64e-75ee820a5f7d', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 4, 4, 'የአባቶቻቸውም ገንዘብ አይጠቅማቸውም፤ በንጥቂያና በግፍ ሰብስበውላቸዋልና፤ እንደ ጉም ሽንትና ነፋስ እንደሚበትነው ጢስም፥ እንደሚረግፍ ሣርም፥ በእሳትም ፊት እንደሚቀልጥ ሰም እንዲሁ የኃጥኣን ክብራቸው ይጠፋል።'),
  ('f73dbfbb-faae-5a5b-a918-535ad44e0be4', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 5, 5, 'ዳዊትም እንደ ተናገረ፥ “ኀጢአተኛን እንደ ሊባኖስ ዛፍ ለምልሞና ከፍ ከፍ ብሎ አየሁት፤ በተመለስሁ ጊዜ ግን አጣሁት፤ ፈለግሁ፤ ቦታውንም አላገኘሁም።”'),
  ('00bde6be-44d8-5a52-a66b-6e25220f5e85', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 6, 6, 'የማይሞቱ መስሏቸው የሌላውን ገንዘብ በግፍ ስለሚሰበስቡ ዛሬ ባልንጀሮቻቸውን የሚበድሉ ሰዎች እንዳይመኩ የኃጥኣን ጥፋታቸው እንደዚህ በአንድ ጊዜ ነው።'),
  ('849cce58-f4f1-5f92-a931-9df54d8e8178', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 7, 7, 'እናንተ ሰነፎች፥ እንደምታልፉ፥ ገንዘባችሁም ከእናንተ ጋር እንደሚያልፍ አስቡ፤ ወርቃችሁና ብራችሁ ቢበዛ የዛገ ይሆናል።'),
  ('a82cd379-d192-5ef2-a7a0-1dcaef39804a', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 8, 8, 'ልጆችን ብታበዙም የመቃብር ብዛት ይሆናል፤ ቤቶችንም ብታበዙ የፈረሰ ይሆናል።'),
  ('4a60d689-8306-530c-a257-e7fa2fb7759d', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 9, 9, 'የአምላካችሁ የእግዚአብሔርን ፈቃድ አልፈጸማችሁምና ከብት ብታበዙም ለጠላቶቻችሁ ምርኮ ይሆናል፤ ያልተባረከ ሆኗልና፥ እጃችሁን ያኖራችሁበት ገንዘብ ሁሉ አይገኝም።'),
  ('7a162d8e-c861-5237-a116-af041d1af40b', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 10, 10, 'በቤትም ያለ ቢሆን፥ በዱርም ያለ ቢሆን፥ በመሰማሪያና በእርሻም ያለ ቢሆን፥ በእህል አውድማና በወይን መጭመቂያም ያለ ቢሆን አይገኝም።'),
  ('557a5f3b-e522-5e6c-a7a5-7357e224f50c', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 11, 11, 'በሆዳችሁም ፍሬ ቢሆን ደስ አይላችሁም፤ ነገር ግን ከጠላቶቻችሁ የተነሣ ኀዘን ይሆንባችኋል። የእግዚአብሔርን ትእዛዝ ስላልጠበቃችሁ፥ እግዚአብሔር ከቤተ ሰባችሁ ሁሉ ጋር አያድናችሁምና።'),
  ('1ab18a67-34a9-5ebe-a5a5-122844fea13d', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 12, 12, 'ሕጉንና ሥርዐቱን፥ ትእዛዙንም የጠበቁ ሰዎችን ግን ከበረከቱ አያሳጣቸውም፤ የለመኑትንም ሁሉ ይሰጣቸዋል፤ የምድራቸውን ፍሬና የሆዳቸውን ፍሬም ይባርክላቸዋል።'),
  ('76c9f3e4-a499-5f89-adb5-8f42fadab0eb', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 13, 13, 'እንዲገዙ እንጂ እንዳይገዙ፥ በዙሪያቸው ከአሉ አሕዛብም ሁሉ በላይ ያደርጋቸዋል፤ በመሰምሪያቸውም ቦታ በረከቱን ሁሉ ይሰጣቸዋል።'),
  ('bb4c3e34-ce3c-55ab-a089-ca24801e149f', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 14, 14, 'እጃቸውን ያኖሩበትን ሁሉ፥ የእርሻቸውን ፍሬ ሁሉና የከብቶቻቸውን ቦታ ሁሉ ይባርክላቸዋል፤ በሆዳቸውም ፍሬ ደስ ያሰኛቸዋል።'),
  ('f81568ec-f324-53ee-a5f7-f305c64d4290', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 15, 15, 'ከብቶቻቸውንም አያሳንስባቸውም፤ ከመከራቸውም ሁሉ ከበሽታና ከድካምም፥ ከጥፋትም፥ ከሚያውቁትና ከማያውቁትም ያድናቸዋል።'),
  ('2621ec49-343a-5025-a0a9-c79bacfeeeff', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 16, 16, 'በፍርድም ጊዜ ይከራከርላቸዋል፤ ከክፉ ነገርና ከመከራም፥ ከሚቃወማቸውም ሁሉ ያድናቸዋል፤ በመጀመሪያ የድንኳኑን ሥራ በአደራ የተቀበለ ሌዋዊ የድንኳኑን ሥራ ቢጠብቅ፥ በእግዚአብሔርም ፈቃድ ቢሄድ፥ በመጀመሪያው ሕግ እንደ ሕጉ ሁሉ ዐሥራቱንና ከሰው ጀምሮ እስከ ከብት ድረስ በኵራቱን ይሰጡት ነበር።'),
  ('10875f99-f156-5beb-a7d7-2d8af662459e', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 17, 17, 'ሙሴም የነዌ ልጅ ኢያሱን እንዳዘዘው በሚፈርዱበትና ለሚፈርዱለት ፍርድን እስኪሰጡ ድረስ ባለማወቅ ወይም በማወቅ ነፍስ የገደለ ሰው ቢኖር በዚያ ይድን ዘንድ በከተሞቻቸው ሁሉ መማጸኛ ከተማ ነበር።'),
  ('8bc61ba1-e5f4-59fe-a6e9-733df78d8253', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 18, 18, '“ቀድሞ ከእርሱ ጋር ጠብ እንዳለው በልቡናችሁ መርምሩ አላቸው፤'),
  ('d200ad96-0761-5064-ab51-b5d92288ef9b', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 19, 19, 'ምሳርም ቢሆን፥ ድንጋይም ቢሆን፥ እንጨትም ቢሆን፥ ባለማወቅ ከእጄ ስለ ወደቀ ያ የወደቀበት ሰው ሞተብኝ ቢል፥ መርምራችሁ አድኑት፤ ባለማወቅ አድርጎታልና ይድናል።'),
  ('2c4a3574-4dba-567f-a0b1-ce2f53f37b27', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 20, 20, 'በማወቅ ቢያደርገው ግን እንደ በደሉ ፍዳውን ይቀበላል፤ የሚምረውም የለም፤ ባለማወቅ ቢያደርግና ቢገድለው ግን ባለማወቅ አድርጎታልና እንዳይሞት መርምራችሁ አድኑት።”'),
  ('59be1654-48f0-5316-a87c-507294c127f4', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 21, 21, 'ሙሴም የእግዚአብሔርን ትእዛዝ እንዳይተላለፉ ለእስራኤል ልጆች እንደዚህ ሥርዐት ሠርቶላቸው ነበር፤ ከክፋትም ሁሉ እንዲርቁ ሥርዐት ሠርቶላቸው ነበር።'),
  ('b67f7d96-0436-5dac-a493-c732b708bf39', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 22, 22, 'በፍርዱና በሕጉ ይኖሩ ዘንድ፥ ጣዖት ከማማለክ፥ ሙቶ ያደረውንና አባላ የተመታውን ከመብላትም፥ በእግዚአብሔር ትእዛዝ ለሚኖሩና እንደ ሠራላቸው ከክፉ ሥራ ሁሉ ለሚርቁ ለሰው ልጆች ከማይገባው ሁሉ ፈጽመው ይርቁ ዘንድ አዘዛቸው።'),
  ('05134f92-102e-51f1-a8f1-7860c3c7a2f0', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 23, 23, 'ነፍሳቸውንም ያድኑ ዘንድ፥ በጎ ከሠሩ ከአባቶቻቸው ጋራ ማደሪያቸውን ያገኙ ዘንድ በሰማይ ባለች ድንኳን አምሳል ከሠራላቸው ትእዛዝ እንዳይወጡ አዘዛቸው።'),
  ('7a618e99-876f-5888-a221-ac5678d57057', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 24, 24, 'በእግዚአብሔር ቃል ያመኑና በትእዛዙ የሄዱም እነርሱ የጻድቃን ልጆች ይባላሉ። የእግዚአብሔርን ፈቃድ ከአደረጉ ከአዳምና ከሴት ናቸውና።'),
  ('60abe8c4-b44e-5ba4-add2-994b4e7c466f', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 25, 25, 'የአዳም ልጆች ነንና፥ በጎ ሥራንና እግዚአብሔርን ደስ የሚያሰኘውንም ሁሉ እንሠራ ዘንድ በመልኩና በምሳሌው ፈጥሮናልና አይንቀንም።'),
  ('d45dccb6-ccac-588a-a5fc-3fde090781ed', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 26, 26, 'በጎ ሥራን ብንሠራም በጎ ሥራን ከሠሩ ጋራ መንግሥተ ሰማያትን እንወርሳታለን፤ የሚወዱትን አይለያይምና።'),
  ('3b1641aa-37ed-52a9-aaa8-54373e5c3151', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 27, 27, 'በንጹሕ የሚለምኑትን ሰዎች እጅግ ይወዳቸዋል፤ ጸሎታቸውንም ይሰማቸዋል፤ ቈርጠው ንስሓ የሚገቡትንም ንስሓቸውን ይቀበላቸዋል፤ ሕጉንና ሥርዐቱን፥ ትእዛዙንም ለሚጠብቁ ሰዎች ኀይልንና ጽናትን ይሰጣቸዋል።'),
  ('53a76875-c438-53b2-a736-4daeffd054fe', '44e9e76c-cc22-577d-a07c-5faab9ee2ec5', '939e17eb-5d5b-5958-a4e7-b462c009cf32', 28, 28, 'ፈቃዱንም ያደረጉ ሰዎች ለዘለዓለሙ በመንግሥቱ ከእርሱ ጋር ደስ ይላቸዋል፥ ፊተኞችም ቢሆኑ፥ ኋለኞችም ቢሆኑ ምስጋናን ያቀርቡለታል። ከዛሬ ጀምሮ እስከ ዘለዓለም አሜን።'),
  ('ace5bd41-61d1-5ba6-a55f-81b0857bd2cb', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 1, 1, 'ግፈኛና አሳች፥ የፈጣሪውንም መንገድ የሚፃረር ዲያብሎስን ስለሚበቀለው በኋላ ዘመን ስለሚመጣው ቸርና የዋህ የግብጽ ደሴቶች ደስ ይላቸዋል።'),
  ('ac49efff-e955-5dd5-acdf-a0ed8676f959', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 2, 2, 'እርሱም ይበቀለዋል፤ በልቡናውም ታብዮአልና ክብሩን ወደ መሬትና ወደ መዋረድ ይመልሳል።'),
  ('a0f0f4ca-c75c-5f93-af60-4d4b3066e878', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 3, 3, 'እርሱም እንዲህ አለ፥ “ከእኔ በላይ ማን ነው? ወደ ባሕሩ ጥልቅ እገባለሁና፥ ወደ ሰማይም እወጣለሁና፥ ጥልቆችንም አያለሁና፥ የአዳምንም ልጆች እንደ ወፍ ጫጩት ጨብጬ እይዛቸዋለሁና።'),
  ('6f263d37-f960-569f-ac77-507b783b89d8', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 4, 4, 'ከቀናች ሕገ እግዚአብሔር አርቃቸው ዘንድ በእነርሱ ላይ ምክንያት ስለምፈጥር የእግዚአብሔርን ፈቃድ ባላደረጉ፥ በምድር ላይ በሚኖሩ ሰዎች እኔ እበረታታባቸዋለሁና ከእጄ የሚያስጥለኝ የለም።'),
  ('95e84a0b-09af-570b-a23a-5f9d681df84f', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 5, 5, 'ከእኔ ጋራም ወደ ጥፋት እንዲሄዱ ጐጣጕጥ ወደ ሆነ ጎዳና እመልሳቸዋለሁ።'),
  ('9c4d9c44-1fc6-5791-adcc-998cc207fcb7', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 6, 6, '“ስለዚህም እርሱን የወደዱት፥ ሕጉንም የጠበቁ ሰዎች እኔን ይጠላሉ፤ ከጌታቸው ተለይተው የሳቱ ሰዎች ግን ወደ እኔ ይመጣሉ፤ እኔንም ይወድዳሉ፤ ቃል ኪዳኔንም ይጠብቃሉ፤ ወደ ፈጣሪያቸው ወደ እግዚአብሔርም እንዳይመለሱ ልባቸውን አከፋለሁና፥ አሳባቸውንም አጠማለሁና እኔ እንዳዘዝኋቸው ትእዛዜን ያደርጋሉ።'),
  ('b93b4e7a-2302-526f-a732-1e47350849bc', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 7, 7, 'የዚህን ዓለም ገንዘብ ባሳየኋቸውም ጊዜ ከቀናች መንገድ ልቡናቸውን አስታለሁ፤ መልከ መልካም ሴቶችንና ቆነጃጅትንም ባሳየኋቸው ጊዜ በእነዚህ ከቀናች መንገድ አርቃቸዋለሁ።'),
  ('82cc2196-d86d-5c88-a1ff-713d6e1baad1', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 8, 8, 'የሚያንፀባርቁ የሕንደኬ ዕንቆችን፥ ወርቅንና ብርን ባሳየኋቸው ጊዜ ወደ እኔ ሥራ ይመለሱ ዘንድ በዚህም ከቀናችው መንገድ አርቃቸዋለሁ።'),
  ('efe252f4-fe3d-56d9-a1dd-8d1c814f521e', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 9, 9, 'ቀጭን ልብስን፥ ነጭ ሐርንና ቀይ ሐርን፥ ግምጃንና የተልባ እግርን ባሳየኋቸው ጊዜ በዚህም ከቀናች መንገድ አርቃቸዋለሁ፤ ወደ እኔም አሳብ እመልሳቸዋለሁ፤ ገንዘብን፥ ከብቶችንም እንደ አሸዋ አብዝች ባሳየሁአቸው ጊዜ በዚህም ወደኔ ሥራ እመልሳቸዋለሁ።'),
  ('756a09b8-e74f-532d-a21e-349dde9f7924', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 10, 10, 'ስለ ሴቶች፥ ስለ ቍጣና ስለ ጠብ፥ የትዕቢት ቅናትን ባሳየኋቸው ጊዜ በዚህ ሁሉ ወደ እኔ መንገድ እመልሳቸዋለሁ።'),
  ('7d6eda73-1192-5482-a851-caa3ba7aa29f', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 11, 11, 'ምልክቶችንም ባሳየኋቸው ጊዜ በባልንጀሮቻቸው ልቡና አድራለሁ፤ በልቡናቸውም እየራሱ የሆነ የምልክት ነገርን አሳድራለሁ፤ የቃላቸውንም ምልክት አሳይች አስታቸዋለሁ።'),
  ('096285b7-8fa6-51a6-a531-e88b299cbc23', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 12, 12, 'ማደሪያዬም ላደረግኋቸው ሰዎች ምልክትን አሳያቸዋለሁ፤ በከዋክብት አካሄድም ቢሆን፥ ወይም በደመና መውጣት፥ ወይም በእሳት ማናፋት፥ ወይም በአውሬዎችና በወፎች ጩኸት እነርሱ ማደሪያዎች ናቸውና በዚህ ሁሉ በልቡናቸው ምልክቶችን አሳድርባቸዋለሁ።'),
  ('e883f76d-c1c1-5f92-aee1-6937768cabea', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 13, 13, 'እነርሱ ተናግረው ለባልንጀሮቻቸው ምልክት ይሰጧቸዋል፤ እኔም ቀድሜ እነዚያ ሟርተኞቻቸው እንደ ነገሯቸው ምልክት እሆናቸዋለሁ።'),
  ('c00fa7d4-0ede-5a01-aa5d-412136514e6d', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 14, 14, '“የመረመሯቸው ሰዎች ይስቱ ዘንድ፥ ዋጋንም ይሰጧቸው ዘንድ፥ እንደ ተናገሩት የሚደረግላቸው ትንቢትንም የሚያውቁ፥ ክፉና በጎንም የሚለዩ፥ ሁሉም እንደ ተናገሩ የሚሆንላቸው፥ እንደ ቃላቸውም የሚደረግላቸው እንደ እገሊትና እንደ እገሌ ዐዋቆች የሉም ብለው ለባልንጀሮቻቸው ይነግሯቸው ዘንድ የቃላቸውን ምልክት አደርግላቸዋለሁ።'),
  ('23d87d30-1912-5ef3-a398-2835f5031817', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 15, 15, 'የሚጠፉ፥ በእኔም የሚስቱ ሰዎች ፈጽመው ይበዙ ዘንድ፥ የአዳምም ልጆች ከእኔ ጋር ይጠፉ ዘንድ ይህን በተናገሩ ጊዜ እኔ ደስ ይለኛል፤ ለበታች አልሰግድም በማለቴ እግዚአብሔር ስለ አባታቸው ስለ አዳም ከክብሬ አዋርዶኛልና።'),
  ('7f4cf880-733f-5664-a96f-55dd997e16ef', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 16, 16, '“እኔም በትእዛዜ የሚሄዱ ልጆቹን ሁሉ ወደ ጥፋት እወስዳቸዋለሁ” ያሳትኋቸው ሰዎች ከእኔ ጋራ በእሳት ውስጥ ይጨመሩ ዘንድ ከፈጠረኝ ከእግዚአብሔር ቃል ኪዳን አለኝ።'),
  ('ace6220f-8040-5393-abf0-8cc93019ee0c', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 17, 17, 'እኔም ቍጣውን በእኔ ላይ ባበዛ ጊዜ፥ አስረውም ወደ ገሃነምና ወደ ሲኦል ጥልቅ ይጥሉኝ ዘንድ ባዘዘ ጊዜ፥ ጌታዬን ማለድሁ፤ ፈጣሪዬም እንዲህ በአዘዘ ጊዜ ተቈጥተኸኛልና በመቅሠፍትህም ገሥጸኸኛልና፥ በመዓትህም ቀሥፈኸኛልና አቤቱ ጌታዬ በፊትህ አንዲት ነገር እናገር ዘንድ ፍቀድልኝ ብዬ በፊቱ ማለድሁ።'),
  ('09e008cd-d8fb-56ba-af2f-10273df9ec2d', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 18, 18, 'ጌታዬም፦ ተናገር እሰማሃለሁ ብሎ መለሰለኝ፥ ያንጊዜም ወደ እርሱ እንዲህ እያልሁ እለምን ጀመርሁ። ከክብሬ ከተዋረድሁ በኋላ ያሳትኋቸው ሰዎች እኔ መከራ በምቀበልበት ከእኔ ጋር ይሁኑ።'),
  ('a347113b-e63a-55ea-af8b-469812eb60e4', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 19, 19, 'ነገር ግን እንቢ ያሉኝ፥ በእኔም ያልሳቱ፥ ትእዛዝህን ያደርጉ ዘንድ፥ ፈቃድህንም ይፈጽሙ ዘንድ፥ ቃልህንም ይጠብቁ ዘንድ፥ ትእዛዜን ያልጠበቁ፥ እኔም እንዳስተማርኋቸው እንቢ ባሉ ጊዜ፥ እኔም እንዳሳትኋቸው በእኔ ባልሳቱ ጊዜ እነርሱ ለመንግሥትህ ይሁኑ፤ ትወድደኝም በነበረ ጊዜ ለእኔ የሰጠኸኝን ዘውድ ይውሰዱ።'),
  ('4894bc98-b614-507d-ab73-dfcc3edb0ff4', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 20, 20, 'ከእኔ ጋር ላልተሰደዱና ሰይጣናት ላልተባሉ ሥልጣናትም የእኔን ዘውድ ስጣቸው፤ ከእኔና ከሠራዊቶችም ባዶ በሆነች መንበሬ በቀኝህ አስቀምጣቸው።'),
  ('c6b17ba2-765a-51da-a938-fad1b7a4a35d', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 21, 21, 'እንደ ወደድህም ያመስግኑህ፤ እንደ እኔና እንደ ሠራዊቶች ይሁኑ፤ እኔን ጠልተህ ከአመድና ከመሬት የተፈጠሩትን ስለ ወደድሃቸው፥ የእኔ ሥልጣን ተሽሮአልና፥ የእነርሱም ሥልጣን ከፍ ከፍ ብሏልና እንደ ወደድህ ያመስግኑህ።”'),
  ('668fd180-c4a5-55c2-abb4-744bf0042331', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 22, 22, 'ጌታዬም መልሶ እንዲህ አለኝ፥ “እያዩና እየሰሙ ሥራዬን ሳይወዱ አንተ አስተሃቸዋልና እንደ ፈቃድህና እንደ ቃልህ ይሁኑህ።'),
  ('df1e56c5-f4ec-5680-a737-f73190687759', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 23, 23, 'ትእዛዜንና የመጻፎችን ቃል ትተው ወደ አንተ ከመጡ ጥፋታቸው አያሳዝነኝም፤ አንተም ከአሳትሃቸው ከአንተ ጋር በገሃነም ይቀጡ።'),
  ('e259d65b-032b-550c-aec7-90d8665b9099', 'adfe38f1-61d8-51d9-a41e-8f6d19f2eaa0', 'bfedfa4a-83f0-528f-a9b5-ce699b0490da', 24, 24, 'እስከ ዘለዓለሙ ድረስ ለአንተና በአንተ ለሳቱ ከገሃነም ቅጣት መውጫ የላችሁም። ነገር ግን ለዘለዓለም በእሳት ውስጥ ትሠቃያላችሁ።'),
  ('d4819cf3-23da-58d7-a08c-8f2bf698b4d4', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 1, 1, '“አንተ ግን እንደ ባርያዬ እንደ ኢዮብ ማሳት የተሳነህን እኔ በክብር የአንተን ዙፋን አወርሳቸዋለሁ፤ አንተ ማሳት ለተሳነህ ሰዎች መንግሥተ ሰማያትን እሰጣቸዋለሁ ይላል ሁሉን የሚችል እግዚአብሔር።”'),
  ('e7446ed0-50e7-567d-ad6e-0039415378af', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 2, 2, 'እኔም የአዳምን ልጆች በሁሉ እተነኰልባቸዋለሁ፤ እነርሱን ማሳት ከተቻለኝ በበጎ ሥራ ይጸኑ ዘንድ አልተዋቸውም፤ የአዳምን ልጆች ሁሉ እተነኰልባቸዋለሁና፥ የዓለምን ምኞትም አጣፍጥላቸዋለሁና።'),
  ('2905480f-3427-516a-a221-598295024c8c', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 3, 3, 'መብልን በመውደድ፥ መጠጥንም በመውደድ፥ ልብስን በመውደድም ቢሆን፥ ነገርንም በመውደድ፥ በመስጠትም በመንሣትም ቢሆን፥'),
  ('1fb06258-1962-519b-a761-b8b262df9628', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 4, 4, 'መስማትንና ማየትንም በመውደድ ቢሆን፥ መዳሰስንና መሄድንም በመውደድ ቢሆን፥ ትዕቢትንና ነገርንም በማብዛት ቢሆን፥ እንቅልፍንና ሕልምንም በመውደድ ቢሆን፥'),
  ('c9296418-cd12-5694-a533-8857b8d3c3ec', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 5, 5, 'መጠጥንና ስካርን በማብዛት ቢሆን፥ ስድብንና ቍጣንም በማብዛት ቢሆን፥ ቡዋልትንና ቀልድን በመናገርም ቢሆን፥'),
  ('0991183f-c9cf-5bd4-a400-2e9e7deb67cb', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 6, 6, 'ባልንጀራቸውንም በማማት በጠብ ቢሆን፥ መልከ መልካሞች የሆኑ የዚህን ዓለም ሴቶችን በማየትም ቢሆን፥ የሚያስትዋቸውን የሽቱዎችን መዓዛ በማሽተትም ቢሆን፥'),
  ('6072a95e-e0e6-55a4-a3da-0372dfe12ba0', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 7, 7, 'መዳንን እንዳይችሉ በዚህ ሁሉ እኔ እጣላቸዋለሁ፤ በእነርሱም ምክንያት ከመንበሬ ወደ ተዋረድሁበት ጥፋት ከእኔ ጋራ ይገቡ ዘንድ ከእግዚአብሔር መንገድ አርቃቸዋለሁ።'),
  ('cbc26274-2349-57eb-a295-8a9d46570ddd', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 8, 8, 'ነቢዩም እንዲህ አለ፥ “አንተ ጥፉና አጥፊ! በትዕቢትህና በልብህ ደንዳናነት፥ ፈጣሪህን በማሳዘንና ፈጣሪህንም ባላማመስገን አንተ ከእግዚአብሔር ትእዛዝ ወጥተህ በካድህ ጊዜ በእግዚአብሔር ፍጥረት ላይ እንዲህ ትታበያለህን?'),
  ('f7d744dd-9929-55ac-a8ee-1429fbeba918', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 9, 9, 'ፈጣሪህ በተቈጣህ ጊዜ ስለ ክፉ ሥራህ ጣለህ፤ ፈጣሪው ከመሬትና ከትቢያ የፈጠረውን፥ እንደ ወደደም የሠራውንና ለምስጋናው ያኖረውን ምስኪን ለምን ትወስደዋለህ?'),
  ('d6ea2f11-fa6f-55bf-a627-fa9f9ec8e795', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 10, 10, '“ረቂቅ የምትሆን አንተ ከእሳት ነበልባልና ከነፋስ የፈጠረህን ፈጣሪ ነኝ በማለት በታበይህ ጊዜ፥'),
  ('7c01c221-7f09-5aee-a7be-48970e084fae', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 11, 11, 'አንተም በተመካህ ጊዜ እግዚአብሔር ክፉ ሥራህን ተመለከተ፤ ሳያጓድል ስሙን ያመሰግን ዘንድ፥ በአንተ ፋንታ የሚያመሰግን አዳምን ፈጠረው፤ አንተ ከሠራዊቶችህ ጋራ እግዚአብሔርን ክደሃልና።'),
  ('d0dcc5c0-c75e-5930-a564-8f881bf3e349', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 12, 12, 'አዳምና ልጆቹም እግዚአብሔር ስለ ትዕቢትህ በናቃችሁ በአንተና በሠራዊትህ ምስጋና ፋንታ የእግዚአብሔርን ስም ያመሰግኑ ዘንድ ተፈጠሩ፤ ከሊቃነ መላእክት ሁሉ ይልቅ ራስህን አኵርተሃልና።'),
  ('d9d4973e-88f5-583f-ad28-8602457985e5', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 13, 13, 'ስለዚህም እግዚአብሔር እንደ አንተ ከአሉ ከመላእክት አለቆች ሁሉ ለይቶ አዋረደህ፤ በአንድ ምክር የተፈጠራችሁ አንተና ሠራዊትህም ስለማይጠቅም ስለ ልቡናችሁ መደንደንና ስለ ሕሊናችሁ ትዕቢት ከእግዚአብሔር ምስጋና ወጥታችሁ ሳታችሁ፤ በሌላም ሳይሆን በፈጣሪያችሁ ላይ ታበያችሁ።'),
  ('d869b106-86d3-528c-a731-371ed5c3b51c', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 14, 14, 'ስለዚህም በትሑታን ይመሰገን ዘንድ አዳምን ከምድር አፈር ፈጠረው፤ ከበለስም ፍሬ እንዳይበላ ትእዛዝንና ሕግን ሰጠው።'),
  ('be940979-556c-556a-a119-79597fc523d3', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 15, 15, 'በፈጠረውም ሁሉ ላይ ሾመው፤ እንዲህም ብሎ አስታወቀው፤ “በገነት ውስጥ ከአለው ዛፍ ሁሉ ብላ፤ በራስህም ላይ ሞትን እንዳታመጣ የሞት እሾህ ከሆነችው ከአንዲት ዛፍ አትብላ፤”'),
  ('4f000830-124d-5ebd-a935-72a386b1f60e', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 16, 16, 'ይህቺንም ቃል በሰማሃት ጊዜ ከአዳም የጎን አጥንት በተገኘች በሔዋን ላይ የአፍህን መርዝ ተፋህ።'),
  ('991f5609-2a6b-5911-ad5e-0c8d886feb21', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 17, 17, 'እንደ አንተም ሕግ አፍራሽ ታደርገው ዘንድ በክፉ ሽንገላ ንጹሑን በግ ነጠቅኸው።'),
  ('527abcc5-e912-581c-a5c8-1a973d85b97d', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 18, 18, 'እንደ የዋህ ርግብ ሆና የተፈጠረች ተንኰልህን የማታውቅ ሔዋንንም ባሳትሃት ጊዜ በተከናወነ ነገርህና በጠማማ ቃልህ አስካድሃት፤ ያችንም መጀመሪያዪቱን ፍጥረት ካሳትሃት በኋላ፥ እርሷ ሄዳ ከመሬት የተፈጠረ መጀመሪያውን የእግዚአብሔር ፍጥረት አዳምን አሳተችው።'),
  ('0fbd2a04-4a4f-5609-af76-ef5b9590c7ab', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 19, 19, 'በትዕቢትህም ወደማይገባ ሁከት ጨመርኸው፤ የፈጣሪውንም ቃል እንዲክድ አደረግኸው፤ በትዕቢትህም ድሃውን አጠፋኸው።'),
  ('46cd0467-e7b1-529d-a2c1-3d985d783412', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 20, 20, 'በተንኰልህም ከፈጣሪው ፍቅር አራቅኸው፤ በምክንያትህም ከደስታ ገነት አወጣኸው፤ በመሰናክልህም የገነትን መብል አስተውኸው።'),
  ('b603d60d-de07-56e7-af0f-0ef1006f86a2', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 21, 21, 'በሐሰትህም ከገነት መጠጥ አስጠማኸው፤ አንተ ፍዳ ወደምትቀበልባት ወደ ሲኦል ታወርደው ዘንድ ካለመኖር ወደ እውነተኛ መኖር ካመጣው አምላኩም ፍቅር ታወጣው ዘንድ የዋህ አዳምን ከጥንት ጀምሮ አንተ ተጣልተኸዋልና።'),
  ('b3bb14bd-5e14-5b81-a01b-6845f3d9d480', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 22, 22, 'መሬታዊም ሲሆን በነፍሱና በሥጋው፥ በልቡናውም ፈጣሪውን የሚያከብርና የሚያመሰግን መንፈሳዊና ተናጋሪ አደረገው።'),
  ('953c9905-fde0-569b-af69-34c86085d301', '6f618cf9-dc53-533d-abe1-66ca717633dc', '12f21ab6-9f15-557d-ab54-f5eef64764d7', 23, 23, 'እንደ በገና በተለያዩ ብዙ ስልቶች የሚያመሰግኑ ዐሥር ሕሊናትን ፈጠረለት።'),
  ('f9c6991b-7034-53ae-ac81-de7da7958c7d', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 1, 1, 'ለአንተስ ፈጣሪህ ወደላከህ እየተላክህ ፈጽመህ ታመሰግን ዘንድ አንድ አሳብን ፈጠረልህ።'),
  ('775164f7-d9e1-5970-a7e2-3917c315a0c3', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 2, 2, 'ለአዳም ግን ክፉ የሆኑ አምስት አሳቦችና በጎ የሆኑ አምስት አሳቦች ዐሥር አሳቦች ተሰጡት።'),
  ('8eeef7b6-7848-55ad-aad7-9f205f8e4268', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 3, 3, 'ዳግመኛም እንደ ባሕር ሞገድ፥ ከምድርም አንሥቶ ትቢያን እንደሚበትን ጥቅል ነፋስ፥ ነፋስም እንደሚያናውጠው እንደ ባሕር ሞገድ የሚታወኩ ብዙ አሳቦች አሉት፤ እንደማይቈጠር እንደ ዝናብም ጠብታ በልቡ ከአለ ከማይቈጠር ከአሳቡ ብዛት የተነሣ የአዳም አሳብ እንደዚሁ ነው።'),
  ('b928f7c5-272b-556e-aa7b-84794f408e51', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 4, 4, 'የአንተ ግን አሳብህ አንዲት ናት፤ ሥጋዊ አይደለህምና ሌላ አሳብ የለህም።'),
  ('3ceaf319-f8e2-5249-a6fe-2af5fad28ad1', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 5, 5, 'አንተ ግን በእባብ ልቡና አድረህ አንድ አካል የሆነ አዳምን በክፉ ሽንገላ አጠፋኸው፤ ሔዋንም የእባብን ነገር ሰማች፤ ሰምታም እንዳዘዘቻት አደረገች።'),
  ('b3811631-04fc-5e48-aca4-f600afb04f49', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 6, 6, 'መጥታም የእግዚአብሔር መጀመሪያ ፍጥረቱ አዳምን የበለስን ፍሬ በማብላት አሳተችው፤ የፈጣሪዋንም ትእዛዝ ስለ ተላለፈች በእርስዋና በልጆችዋ ሞትን አመጣች።'),
  ('5fe7b0b8-7765-5517-a768-45a9783be670', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 7, 7, 'በእግዚአብሔርም እውነተኛ ፍርድ ከገነት ወጡ፤ ተጣልቶም ከገነት አላራቃቸውም። ነገር ግን በተሰደዱበት ምድር በሆዳቸው ፍሬ በልጆቻቸውና በምድራቸው ፍሬ አረጋጋቸው።'),
  ('f1bf0101-e0e5-52e3-a475-9f78f65511b7', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 8, 8, 'በቅንአትህም ከገነት ባስወጣሃቸው ጊዜ እግዚአብሔር ከገነት የለመለሙ ዕፀዋትን ሰጣቸው፤ ይተክሉ ዘንድ እግዚአብሔር በሰጣቸው በገነት ፍሬና በምድር ፍሬ ይረጋጉ ዘንድ፤'),
  ('9a3984ff-a18b-5c27-a526-282ca13f7c9f', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 9, 9, 'ልጆችን በማየት፥ ገነትንና ምድር ከአፈር ያበቀለችውን የምድር ፍሬ በማየት ልቡናቸውን እጅግ ደስ ያሰኙ ዘንድ፤ እርሱንም በበሉ ጊዜ ከገነት እነርሱን ካስወጣህበት ኀዘን ፈጽመው ይረጋጋሉ።'),
  ('4e68e720-4d25-53df-adba-54c811bfd024', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 10, 10, 'እግዚአብሔርም ፍጥረቱን ማረጋጋት ያውቃልና በልጆቻቸውና በምድር ፍሬ ልቡናቸው ይረጋጋል።'),
  ('3c40a991-b994-5d04-aa5a-f61ac7513b6d', '5119cd55-8a4e-56ea-aee8-377934723a97', 'c7f6c796-96fa-5d5e-acc8-962236561676', 11, 11, 'ወደዚች የእሾህና የአሜከላ ምድርም ተሰደዋልና ልቡናቸውን በእህልና በውኃ ያጸናሉ።'),
  ('cc12c37b-875c-5709-a1ce-b30433d73ed8', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 1, 1, 'ጌታውም አዳምን ይቤዠው ዘንድ አለው፤ አንተንም ያሳፍርሃል፤ በጉንም ከተኵላ አፍ ያድነዋል።'),
  ('715ed794-dac6-52ad-a086-cf8720b65c9b', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 2, 2, 'ነገር ግን አንተ የገዛሃቸውን ሰዎች ከአንተ ጋር ይዘህ ወደ ጥፋት ትሄዳለህ።'),
  ('f1ef91e2-3e3d-5ae2-a8d1-34e89cc7e1d9', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 3, 3, 'የፈጣሪያቸው የእግዚአብሔርን ሕግ የጠበቁ ግን የእርሱ እድል ፋንታ ያደርጋቸው ዘንድ፥ የፈጣሪያቸው የእግዚአብሔርንም ሕግ እንዳንተ ካልተላለፉ ከቅዱሳን መላእክቱ ጋር ያመሰግኑት ዘንድ ከክፉ ሥራህ ከሰወራቸው ከፈጣሪያቸው ከእግዚአብሔር ጋር ደስ ይላቸዋል።'),
  ('f0069290-caec-5ae4-ae7b-ce8e5ccb5a2a', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 4, 4, 'አንተ ግን ከመላእክቱ ጋራ ታመሰግነው ዘንድ እንደ አንተ ካሉት ሁሉ ይልቅ መርጦ የሰጠህ እግዚአብሔር በትዕቢትህ ከፍ ያለ ዙፋንን ነሳህ።'),
  ('7042d032-16a1-571b-a1f3-e64c0e79e324', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 5, 5, 'አንተም ታበይህ፤ ዲያብሎስም ተባልህ፤ ሠራዊቶችህም አጋንንት ተባሉ።'),
  ('f0f16a51-54aa-50a2-aa01-de052ffff95d', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 6, 6, 'እግዚአብሔርን የሚወዱ ግን እንደ ቅዱሳን መላእክት ለእርሱ ወገኖቹ ይሆናሉ፤ የሚያመሰግኑት ሱራፌልና ኪሩቤልም ክንፎቻቸውን ዘርግተው ያለማቋረጥ ያመሰግናሉ።'),
  ('fddfa47c-f665-508f-a986-978e5d36b2af', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 7, 7, 'አንተ ግን በመልክህ ከተፈጠሩ ከነገድህና ከሠራዊትህ ጋር ሁልጊዜ ታመሰግነው ዘንድ ምስጋናህን በትዕቢትህና በስንፍናህ አጠፋህ።'),
  ('5daa2feb-5064-5e97-abcd-e06a6e5bb6f6', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 8, 8, 'እንደ አንተ ያለ መፍጠር የማይቻለው መስሎህ አንተ የፈጠረህ የእግዚአብሔርን ምስጋና በዘነጋህ ጊዜ፥ ዐሥረኛ ነገድ አድርጎ የፈጠረህ የእግዚአብሔር ምስጋናው እንዳይጐድል አንተም ከወንድሞችህ አንድነት በተለየህ ጊዜ የፈጠረህ የእግዚአብሔር ምስጋናው እንዳይጐድል፥'),
  ('d63ecc5a-c767-51ff-a524-e0f9c71bc522', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 9, 9, 'አንተም በልቡናህ ትዕቢት የፈጠረህ የእግዚአብሔርን ምስጋና ቸል ባልህ ጊዜ፥ እርሱም በተቈጣህና፤ በተዘባበተብህ ጊዜ፤ ከሠራዊቶችህም ጋራ በገሃነም እንቅጥቅጥ በአጋዘህ ጊዜ'),
  ('13fca489-571f-507e-a023-8a8a81267c88', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 10, 10, 'በቅዱሳት እጆቹ ከምድር መሬትን ወሰደ፤ ውኃንና እሳትን፥ ነፋስንም ጨመረ፤ አዳምንም በመልኩና በምሳሌው ፈጠረው።'),
  ('4c12f480-bb42-5bb7-a35d-c094b0ec9485', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 11, 11, 'ምስጋናው በአንተ ጉድለት ይመላ ዘንድ በእጁ በፈጠረው ፍጥረት ሁሉ ላይ ሾመው። የመሬታዊውም ምስጋና ከሰማያውያኑ ምስጋና ጋር ተጨመረ፤ ምስጋናቸውም እኩል ሆነ።'),
  ('33ce4256-0fe9-5e6b-a404-b8e21782ae27', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 12, 12, 'አንተ ግን በትዕቢትህና በአንገትህ መደንደን ተሰደድህ፤ ከፈጠረህ ከእግዚአብሔርም ጌትነት ወጥተህ ራስህን አጠፋህ።'),
  ('f0fe371d-69be-5c0a-a6a1-b9afce0a0c56', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 13, 13, 'የእግዚአብሔርነቱ ምስጋና እንዳይጐድል እግዚአብሔር በፈቃዱ ምክር የሚያመሰግነውን ፈጥሯልና ምስጋናው እንዳይጐድል ዕወቅ።'),
  ('6b48b333-fa76-5290-ab0b-0d67351bceb7', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 14, 14, 'እርሱ ሳይደረግ ሁሉን ያውቃልና፥ ትእዛዙንም እንደምታፈርስ ሳይፈጥርህ ዐወቀህ፤ ዓለም ሳይፈጠር በእርሱ ዘንድ የተሰወረ ምክር ነበረና በካድኸው ጊዜ ባርያው አዳምን በመልኩና በምሳሌው ፈጠረው።'),
  ('223f08e1-8cd8-52b6-aa2d-8f4e41806811', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 15, 15, 'ሰሎሞን፥ “ከኮረብቶች በፊት ወለደኝ፤ ዓለምም ሳይከናወን የምድርም መሠረት ሳይመሠረት፥'),
  ('48d4ac37-84f2-5786-a921-39581233f8d4', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 16, 16, 'የተራራዎችና የኮረብቶች መቋምያ ሳይተከል፥ የዓለምም ጐዳና ሳይጸና፥ የፀሐይና የጨረቃ ብርሃን ሳይበራ፥ የከዋክብትና የዘመኖች ምግብና ሳይታወቅ፥'),
  ('85a05d20-117b-55dd-a1f8-e8e1c10fc349', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 17, 17, 'ሌሊትና መዓልት ሳይፈራረቁ፥ ባሕርም ባሸዋ ሳትወሰን፥ የተፈጠረው ፍጥረት ሁሉ ሳይፈጠር፥'),
  ('4be2b34b-e1f4-5ca5-a996-9ef09f5a2c2a', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 18, 18, 'ዛሬም የሚታየው ሁሉ ሳይታይ፥ ዛሬ የሚጠራው ስም ሁሉ ሳይጠራ ፈጠረኝ” ብሎ እንደ ተናገረ፥ አንተና እንዳንተ ያሉ መላእክት፥ ባርያው አዳምም በእግዚአብሔር ኅሊና ውስጥ ነበራችሁ።'),
  ('43c3fab8-86c5-560b-ae34-97889a3c9db4', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 19, 19, 'አንተ በካድህ ጊዜ ቅዱስ ስሙ ይመሰገን ዘንድ፥ አንተም በታበይህ ጊዜ ከመሬት በፈጠረው በተዋረደ በባርያው በአዳም ይመሰገን ዘንድ አዳምን ፈጠረው።'),
  ('02b3e133-f2e9-5410-a561-e5e6beaac094', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 20, 20, 'እግዚአብሔር የድሆችን ጸሎት ከሩቅ ይሰማልና፥ የተዋረዱ ሰዎችንም ምስጋና እግዚአብሔር ይወዳልና።'),
  ('ec947a61-0488-571e-a5d6-cd702e842a68', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 21, 21, 'እግዚአብሔር የትዕቢተኞችን ነገር ቸል ይላል፥ የፈረስን ኀይል አይወድምና፥ በሰው ጕልበትም ደስ አይለውምና።'),
  ('a711625e-6b13-5822-a016-37bb77fc6136', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 22, 22, 'ነገር ግን እግዚአብሔር በሚፈሩትና ስለ ኀጢአታቸው ጩኸው በሚያለቅሱ ደስ ይለዋል።'),
  ('0951ca45-66b8-523c-a3b5-d60b23728233', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 23, 23, 'አንተ በንስሓ መናዘዝ ተሳነህ።'),
  ('36bf210b-0752-5acb-a941-5105b3ba9bd9', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 24, 24, 'ያ መሬት ግን ስለ ኀጢአቱ በእግዚአብሔር ፊት ፈጽሞ እያለቀሰ በንስሓ ተመለሰ።'),
  ('ba131f08-78c9-5663-a35b-2e9c39a4e7b6', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 25, 25, 'አንተስ በልብህ ትዕቢትና በአንገትህ መደንደን የሰላም መንገድን አላወቅሃትም፥ ንስሓንም አላወቅሃትም፥ በንስሓ፥ በልቅሶና በእንባ በፈጣሪህ በእግዚአብሔር ፊት መናዘዝ ተሳነህ።'),
  ('ef63a89b-03af-5e01-a172-8c61b461f455', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 26, 26, 'ያ አመድና መሬት የሆነ ድሃ ግን በልቅሶና በእንባ ወደ ንስሓ፥ ወደ ሰላምና ወደ ትሕትና መንገድ ተመለሰ።'),
  ('d838fd25-fce3-5e78-a042-006f248577b3', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 27, 27, 'አንተስ ለፈጠረህ ለእግዚአብሔር ራስህንና የልብህን ቀፈት አላዋረድህም።'),
  ('03389946-6708-567c-a607-fa454ef7f910', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 28, 28, 'እርሱ ግን በበደለው በደል ራሱን አዋርዶ ተናዘዘ፤ አልታበየምም።'),
  ('c133a37d-52c7-5e77-a9ab-64e91971cd16', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 29, 29, 'ያንም ስሕተት የፈጠረው እርሱ አይደለም። ከአንተ የተገኘ ነው እንጂ፥ ወንጀልን ፈጥረህ አውጥተኸዋልና። በትዕቢትህም ከአንተ ጋራ ወደ አንተ ጥፋት ወሰድኸው።'),
  ('a41c5bb8-e348-5f0a-af4b-4b1baa36d812', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 30, 30, 'ሁለታችሁን ሁሉ ሳይፈጥራችሁ ዐውቋችኋልና፥ አካሄዳችሁንም ዐውቋልና ይህ የተደረገ በልብህ ትዕቢት እንደ ሆነ እርሱ ያውቃል።'),
  ('466b5be9-17c9-58fc-ae34-be0fcfd306f5', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 31, 31, 'ያን የትዕቢት ተንኰል የሌለውን ግን በንስሓ፥ በልቅሶና በእንባ መለሰው።'),
  ('21ce9ac4-76c2-51f2-a3c1-56f4bcd71f5c', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 32, 32, 'አንተ ግን በልብህ ትዕቢት በንስሓ መናዘዝ ተሳነህ። በድሎ በንስሓ የማይናዘዝ ሰው ከቀድሞ በደሉ ይልቅ በደሉን ያከፋልና።'),
  ('bbe08add-c040-5b5a-a45e-6a2a264e7023', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 33, 33, 'ነገር ግን በድሎ በፈጣሪው በእግዚአብሔር ፊት የሚናዘዝና የሚያለቅስ፥ እርሱ በእውነት ንስሓ ገባ፤ የጌታውንም ልብ ያራራ ዘንድ የመዳኑን መንገድ አገኘ፤ በጌታውም ፊት ተናዘዘ፤ ጌታውም በባሪያው ላይ ይቈጣ ዘንድ ቀድሞ ከመከረበት ያቃልልለታል፤ በብዙ ንስሓና ስግደት ተናዝዞአልና። የቀደመ ኀጢአቱንም ይቅር ይለዋል።'),
  ('c7342207-4c9d-5ccd-aa04-6d118ed09757', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 34, 34, 'ወደ ቀደመ በደሉም ካልተመለሰ፥ ይህንም ካደረገ ይህ ፍጹም ንስሓ ነው። አዳምስ ፈጣሪውን ማሰብንና ለፈጣሪው መናዘዝን አልዘነጋም።'),
  ('570994c3-6d25-569e-a060-0078d3b5c08c', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 35, 35, 'አንተም ለፈጣሪህ በንስሓ ተናዘዝ፤ በእርሱ ላይና በእጁ ሥራ ላይም በደልን አታብዛ፤ እነርሱ ሥጋውያንና ደማውያን ስለ ሆኑ የፈጠራቸው እግዚአብሔር ድካማቸውን ያውቃልና።'),
  ('1e578294-718f-55c5-af8f-6233392946a6', 'a8dc0738-7284-5147-ae72-2c21aff7a818', 'ca2be3c4-64c3-53ce-a533-995157c3447a', 36, 36, 'ነፍሳቸውም ከተለየች በኋላ ሥጋቸው እግዚአብሔር እስከፈቀዳት ቀን ድረስ ትቢያ ይሆናል።'),
  ('37c093bd-fde2-52ed-ae96-2ed21a4e89cc', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 1, 1, 'የፈጠረህን ዕወቀው፤ ያጸናህና ያዳነህ የእስራኤልን ቅዱስም አትርሳው፤ አንተ መሬት ስትሆን በመልኩና በምሳሌው ፈጥሮሃልና ደስ ይልህ ዘንድ፥ ምድርንም ትቈፍራት ዘንድ በገነት አኖረህ።'),
  ('fffef2df-12bd-5324-af10-2a8a86d3bf91', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 2, 2, 'ትእዛዙንም ባፈረስህ ጊዜ ከዚያ ከገነት አሜከላና እሾህ ወደምታበቅል፥ በአንተም ምክንያት ወደ ረገማት ወደዚች ምድር አወጣህ።'),
  ('711ca00c-05d2-5f72-a25c-b1c71bf22b15', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 3, 3, 'አንተ ምድር ነህና፥ እርስዋም ምድር ናትና፥ አንተ ትቢያ ነህና፥ እርስዋም ትቢያ ናትና፥ አንተ መሬት ነህና እርስዋም መሬት ናትና ከእርስዋም ትመገባለህ፤ ወደ እርስዋም ትመለሳለህ፤ ያስነሣህ ዘንድ እስኪወድድ ድረስ ትቢያ ትሆናለህና የሠራኸውን በደልና ኀጢአት ሁሉ ይመረምርሃልና።'),
  ('4d06e784-4f4f-5e76-a322-aa54fb1534d5', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 4, 4, 'ያንጊዜ የምትመልሰውን ዕወቅ፤ በዚህም ዓለም የሠራኸውን ክፉውንና በጎውን አስብ፤ ክፉው ይበዛ እንደ ሆነ፥ ወይም በጎው ይበዛ እንደ ሆነ መዝን፤ ምከርም።'),
  ('a33513bd-3bbf-5355-a9be-dd339dc4d94e', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 5, 5, 'በጎ ነገርንም ብታበዛ፥ ሙታን በሚነሡበት ቀን ደስ ይልህና ሐሤት ታደርግ ዘንድ ለአንተ መልካም ይሆንልሃል።'),
  ('fd0ec180-ff1b-55b2-a1a0-08f433e7531c', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 6, 6, 'ክፉ ሥራን ብታበዛ ግን ወዮልህ፤ እንደ እጅህ ሥራና እንደ ልቡናህ ክፋት ፍዳህን ትቀበላለህና በባልንጀራህ ክፉ እንደ ሠራህበት፥ እግዚአብሔርንም እንዳልፈራኸው እንደ ሥራህ ፍዳህን ትቀበላለህና።'),
  ('e0ef6e6b-8352-5647-a6a0-eb95c2a9fc73', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 7, 7, 'ባልንጀራህንም ብትከዳው፥ በእግዚአብሔርም ስም በሐሰት ብትምል፥ እንደ ሥራህ ፍዳህን ትቀበላለህና።'),
  ('65e17fb8-5c9d-506f-a4d2-b2c5f8fc8c2e', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 8, 8, 'ለባልንጀራህ በማስመሰል ቃልህን በሐሰት እውነተኛ እንዲሆን ታደርጋለህና፤ አንተ ግን ሐሰት እንደ ተናገርህ ታውቀዋለህ።'),
  ('dd471cf4-d9fc-5efd-a9ee-3b63d1b76321', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 9, 9, 'ከአንተ ጋራ ያሉትንም እያሳመንህ ቃልህ እውነት እንደ ሆነ ታጸናለህ፤ እውነት ያልሆነ ነገርንም ታበዛለህ፤ እንደ ሥራህም ፍዳህን ትቀበላለህ፤ የማትሰጠውን ለባልንጀራህ እሰጥሃለሁ እያልህ ባልንጀራህን ትከዳዋለህ።'),
  ('6120d53f-4668-51cd-a089-37895f3f46a9', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 10, 10, 'በንጹሕ ልቡናህም እሰጣለሁ ባልህ ጊዜ አጋንንት እንደ ውሾች ደጅ ይጠኑሃል፤ ሁሉንም ያስረሱሃል፤ ብትነሣም፥ ትሰጥ ዘንድ ብትወድም የማይጠቅምህንና የማትበላውን ገንዘብ ታደልብ ዘንድ የዚህ ዓለም ገንዘብ ያስጎመጅሃል፤ “ይሰበስባሉ፤ የሚሰበስቡለትንም አያውቁም” ብሏልና።'),
  ('6560c7e9-0239-534f-aa87-b57043df8572', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 11, 11, 'ዳግመኛም “ሐሰተኞች የአዳም ልጆች ሚዛንን ሐሰተኛ ያደርጋሉ፤ እነርሱስ መቼም መች ከከንቱ ወደ ከንቱ ይሄዳሉ” ብሏልና።'),
  ('a9a4d12b-ad9e-5e0f-abc3-19bd73bb3de9', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 12, 12, 'ሰዎች ሆይ ሚዛንንና ላዳንን በማሳበል፥ የሌላውንም ገንዘብ በመስረቅና በዐመፅ ወደ ገንዘባችሁ በመጨመር፥ የባልንጀራችሁንም ገንዘብ፥ የባልንጀራችሁንም እርሻ በመድፈር፥ ለባልንጀራችሁ ያይደለ ለራሳችሁ ትርፍ በምታደርጉት ሁሉ ዐመፅን ተስፋ አታድርጓት።'),
  ('0ba31ecb-b341-5801-ae24-8e3b39d62c4e', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 13, 13, 'ይህንም ብታደርጉ እንደ ሥራችሁ ትቀበላላችሁ።'),
  ('71100d1e-67e2-5133-a2d1-8c99b7a51d0e', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 14, 14, 'ሰዎች ሆይ በሚገባ በእጃችሁ ሥራ ተመገቡ እንጂ ቅሚያን አትታመኗት፤ በማይገባ ያለ ፍርድ በመቀማትና በመንጠቅ የሰውን ገንዘብ ትበሉ ዘንድ አትውደዱ።'),
  ('16ed7af6-5644-5a80-a54e-3ba0a1cf78dd', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 15, 15, 'ብትበሉትም አያጠግባችሁም፤ ብታደልቡትም በምትሞቱበት ጊዜ ለሌላ ትተዉታላችሁ እንጂ አይጠቅማችሁም።'),
  ('8e56c74f-e388-5954-a1da-6b7c665a1c3b', 'e2dd5eb9-ca9f-5128-a587-82d8b4a21072', '48e0b9cd-6167-5664-a8e6-7c471af61792', 16, 16, 'ገንዘባችሁም ቢበዛ ልቡናችሁን አታኵሩ፤ የኀጢአተኞች ሰዎች ገንዘብ ከምድጃ እንደሚወጣ፥ ነፋስም እንደሚወስደው እንደ ጢስ ነውና፥ ከብዙ የኀጢአተኞች ገንዘብ በእውነት ያለ ጥቂት ገንዘብ ይሻላል።'),
  ('10ca1c09-5bfe-599d-a162-e3af3ee6388e', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 1, 1, 'የምትሞቱበትን ቀን አስቡ፤ ነፍሳችሁ ከሥጋችሁ በምትለይበት ጊዜ፥ ገንዘባችሁንም ለሌላ በምትተዉበት ጊዜ፥ ወደማታውቁትም መንገድ በምትሄዱበት ጊዜ የምትመጣባችሁን አስቧት።'),
  ('d4088771-ecd9-5534-af34-2b9eeccfe02a', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 2, 2, 'የሚቀበሏችሁም ክፉዎች ናቸው፤ በመልካቸውም ጥፉዎች ናቸው፤ በግርማቸውም የሚያስፈሩ ናቸው፤ ቃላችሁን አይሰሙም፤ ቃላቸውንም አትሰሙም።'),
  ('684cdbd7-e0d9-5b15-a947-8687c281e3a8', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 3, 3, 'የአምላካችሁን የእግዚአብሔርንም ፈቃድ ስለ አላደረጋችሁ በለመናችኋቸው ጊዜ አይመልሱላችሁም፤ ስለዚህም እጅግ ያስፈሯችኋል።'),
  ('53d12c84-e62f-5f33-afe4-201bb70b1799', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 4, 4, 'አጋንንት ይፈሯቸዋልና የእግዚአብሔርን ፈቃድ በሚፈጽሙ ሰዎች ግን ፍርሀት የለባቸውም። በኃጥኣን ነፍሳትም አጋንንት ይዘባበቱባቸዋል።'),
  ('9b19bd64-3dfb-5fca-aadb-3107ad2b373b', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 5, 5, 'ይህን ዓለም ስለ ናቁት እጅግ ደስ ያሰኛቸዋልና የጻድቃን ሰዎች ነፍሳት በመላእክት ይባቤ ደስ ይላቸዋል፤ የኃጥኣን ነፍሳትን ግን ክፉዎች መላእክት ይቀበሏቸዋል።'),
  ('4cb33c9b-dfd4-5460-a4df-4ec6226a44cb', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 6, 6, 'የጻድቃንን ነፍሳት ያረጋጓቸው ዘንድ ከእግዚአብሔር ይላካሉና፥ የጻድቃንንና የደጋጎች ነፍሳትን የምሕረት መላእክት ይቀበሉአቸዋል። የኃጥኣንን ነፍሳት ግን ክፉዎች አጋንንት ይቀበሏቸዋል፤ በኃጥኣን ነፍሳት ይዘባበቱባቸው ዘንድ ከዲያብሎስ ይላካሉና።'),
  ('794ebbd2-3541-5869-a463-b60f1bf0796c', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 7, 7, 'ኃጥኣን ወዮላችሁ፤ የምትሞቱባት ቀን ሳትደርስባችሁ ለራሳችሁ አልቅሱ፤ ከሞታችሁ በኋላ ያለፈው ዘመናችሁ አይመለስም።'),
  ('96861a93-48a5-57d9-a646-dd59ef38f62b', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 8, 8, 'ነገር ግን ወደ እግዚአብሔር ፊት በደረሳችሁ ጊዜ ያለ መከራና ያለ ደዌ በደስታ ትኖሩ ዘንድ ዘመናችሁ ሳያልፍ በአላችሁበት ንስሓ ግቡ።'),
  ('78b7a560-00c5-5efe-ae06-8b7cac9a0f0c', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 9, 9, 'ከእግዚአብሔር ወደሚያርቅ ከንቱ ፈቃድ እንዳይስባችሁ፥ በእናንተ ጽኑ ነቀፋና መቀማጠል፥ መብልንና ደስታንም መውደድ አይገኝባችሁ፤ ያለ ልክ የጠገበች ሰውነት የእግዚአብሔርን ስም አታስብምና የዲያብሎስ መንፈስ ያድርባታል እንጂ በእርስዋ የሕይወት መንፈስ አያድርባትም።'),
  ('14605cb3-3efb-52ef-ab70-04620729a68d', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 10, 10, 'ሙሴ፥ “ያዕቆብ በልቶ ጠገበ ወፈረም፥ ሰባ፥ ሰፋም፥ የፈጠረው እግዚአብሔርንም ተወው፤'),
  ('bff2cfd4-009e-5da3-a857-8d72d0897bd6', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 11, 11, 'ሕይወቱም ከእግዚአብሔር ራቀ” ብሎ እንደ ተናገረ፥ ያለ ልክ የሆድ ጥጋብ እንዳለሌ ፈረስ መሆን ነውና፥ ያለ ልክ መብላትና መጠጣት፥ ማመንዘርም እንደ ምድረ በዳ እሪያ መሆን ነውና።'),
  ('7dd7ec7d-7360-527e-a17a-ede5a901ab1c', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 12, 12, 'በልክ የሚበላ ግን በእግዚአብሔር መሠረት የጸና ይሆናል፤ እንደ አድማስም ድንጋይ፥ አጥርም እንዳለው ግንብ ይጸናል። “ኀጢአተኛ የሚያባርረው ሳይኖር ይሸሻል” ተብሎአልና።'),
  ('61c5c68e-ba76-50ee-a33a-8a79896a0239', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 13, 13, 'ጻድቅ ግን እንደ አንበሳ ተዘልሎ ይኖራል።'),
  ('6c043265-e4e4-588e-a6a0-9234552f35a6', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 14, 14, 'እግዚአብሔርን የማይወዱ ሰዎች ግን ቃሉን አይጠብቁም፤ ልቡናቸውም የቀና አይደለም።'),
  ('e8591498-ce60-5cb3-a17b-ac0e7fe7a932', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 15, 15, 'እግዚአብሔርም በምድር ሳሉ እንዳያርፉ በመንቀጥቀጥና በፍርሀት፥ ገንዘባቸውንም በመንጠቅ፥ ቍጥርም በሌለው ብዙ መከራ ተይዘው ከጌቶቻቸው እጅ እጃቸውን በሰንሰለት ታስረው፥'),
  ('76d24c19-397f-5446-a274-c5c45fd16dda', 'b848bb19-d466-5f4e-a148-2babdf179202', '860ccccd-fa31-5900-ad56-68516676586d', 16, 16, 'ከመከራውም ያረፉ እንዳይሆኑ፥ አኗኗራቸውም በሰላም እንዳይሆን በተለያዩ የሚያስደነግጡ መከራዎች ሳሉ ኀዘንንና ድንጋጤን ያመጣባቸዋል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('eea10fdd-e7cc-5c45-afbb-dabf0f924386', 'cd78ccaf-a112-56fe-a86a-7f6676caf3e9', '02d281aa-edfe-5ce7-a09d-47b677dce845', 1, 1, 'ዳዊት፥ “በእግዚአብሔር አመንሁ፤ አልፈራም፤ ሰው ምን ያደርገኛል” ብሎ እንደ ተናገረ በእግዚአብሔር በሚያምኑ ሰዎች ግን ፍርሀትና ድንጋጤ የለባቸውም።'),
  ('724eb0a4-18a0-5280-a80e-a66cb085f3de', 'cd78ccaf-a112-56fe-a86a-7f6676caf3e9', '02d281aa-edfe-5ce7-a09d-47b677dce845', 2, 2, 'ዳግመኛም አለ፥ “አርበኞች ቢከቡኝ፥ እኔ በእርሱ አመንሁ፤ እግዚአብሔርን አንዲት ነገር ለመንሁት፤ እርስዋንም እፈልጋለሁ፥ በእርሱም ያመነ ለዘለዓለሙ በሕይወት ይኖራል፥ ከክፉ ነገርም የተነሣ አይፈራም።”'),
  ('6a50ba67-32fa-53ac-a9e5-c7ba8689497d', 'cd78ccaf-a112-56fe-a86a-7f6676caf3e9', '02d281aa-edfe-5ce7-a09d-47b677dce845', 3, 3, 'በእግዚአብሔር አምኖ ያፈረ ሰው ማን ነው? ጠርቶትስ ቸል ያለው ማን ነው?'),
  ('0b1534d1-7ac9-5eec-a7db-2f719accbb62', 'cd78ccaf-a112-56fe-a86a-7f6676caf3e9', '02d281aa-edfe-5ce7-a09d-47b677dce845', 4, 4, '“የወደደኝን እወደዋለሁ፤ ያከበረኝንም አከብረዋለሁ፤ ወደ እኔ የተመለሰውንም እጠብቀዋለሁ” ብሏልና እርሱን ተስፋ አድርጎ ያፈረ ሰው ማን ነው?'),
  ('76c8dbec-e9dc-5162-a314-b4033810e37b', 'cd78ccaf-a112-56fe-a86a-7f6676caf3e9', '02d281aa-edfe-5ce7-a09d-47b677dce845', 5, 5, 'የባልቴቲቱን ሰውነት አድኑ፤ በክፉ ነገር ከሚቃወማችሁ ሁሉ እግዚአብሔር ያድናችሁ ዘንድ አድኗቸው፤ ጠብቋቸውም፤ ከእናንተም በኋላ ልጆቻችሁን ያድናቸዋል፤ የጻድቃን ልጆች ይባረካሉና፤ አትርፈውም ይሰጣሉ እንጂ እህልን አይቸገሩም።'),
  ('0279b71d-9660-5846-ae4a-eb3a64c8127e', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 1, 1, 'ኢዮብ በእግዚአብሔር አመነ፤ ፈጣሪው እግዚአብሔርን ማመስገንን ቸል አላለምና የአዳም ልጆች ጠላት ዲያብሎስ ካመጣበት መከራውም ሁሉ አዳነው፤ በደረሰበትም መከራ ልቡን አላሳዘነም፤ ነገር ግን “እግዚአብሔር ሰጠ፤ እግዚአብሔርም ነሳ፤ እግዚአብሔርም እንደ ወደደ ሆነ፤ በሁሉም በሰማይና በምድር የእግዚአብሔር ስሙ የተመሰገነ ይሁን” አለ።'),
  ('4b066f8d-217c-54b3-a5df-3f39dd9258c4', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 2, 2, 'እግዚአብሔርም የኢዮብ ልቡ ንጽሕት እንደ ሆነች ባየው ጊዜ፥ እግዚአብሔር በብዙ ክብር ተቀበለው።'),
  ('194b38fb-f589-50ba-a06c-233673b7a892', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 3, 3, 'ከቀደመ ገንዘቡ ይልቅ የሚበዛ ገንዘብንም ሰጠው፤ እጅግ ትዕግሥተኛ ሆኗልና፥ የደረሰበትን መከራ ሁሉ ስለ መታገሡ ከቍስሉ ፈወሰው።'),
  ('1a60d265-bdf2-5b67-a681-303f1dd46002', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 4, 4, 'እንዲሁም እናንተ ወደ እናንተ ከሚላኩ ጠላቶች ብትታገሡ ብፁዓን ትሆናላችሁ።'),
  ('2eb713eb-99b9-50ba-a990-3f7f4410a47e', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 5, 5, 'ታገሡ፤ እግዚአብሔር ከሚጠሏችሁ ሰዎች ለእናንተና ከእናንተም በኋላ ለልጆቻችሁና ለልጅ ልጆቻችሁ መጠጊያ ይሆናችሁ ዘንድ ከመጣባችሁ መከራ የተነሣ ልቡናችሁን አታሳዝኑ፤'),
  ('6e0fd9ce-edae-5748-a402-df947d6b6aed', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 6, 6, 'እመኑት፥ እርሱም መጠጊያ ይሆናችኋል፤ ጥሩት፥ ይሰማችኋልም፤ ተስፋ አድርጉት፥ እርሱም ይቅር ይላችኋል፤ ለምኑት፥ እርሱም አባት ይሆናችኋል።'),
  ('a835df29-ba6d-5477-ac85-7f9f46d486a9', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 7, 7, 'አስቴርንና መርዶክዮስን፥ ዮዲትንና ጌዴዎንንም፥ ባርቅንና ዲቦራንም፥ ሶምሶምንና ዮፍታሔንም፥'),
  ('066f06b2-d267-5fff-a9c0-c74fb293ce53', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 8, 8, 'በእግዚአብሔር ለማመን የጨከኑ ጠላቶቻቸውም ድል ያልነሷቸው እንደነርሱ ያሉ ሌሎችንም አስቡ።'),
  ('f60a1a10-fc29-5253-a86f-caa0283c3478', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 9, 9, 'እግዚአብሔር እውነተኛ ነውና፥ ፊት አይቶም አያዳላምና በእነርሱ ላይ ክፉ ያደርጉ ዘንድ የወደዱ ክፉውን ተቀበሉ፤ የሚፈሩትንና ጽድቅን የሚያደርጉትን ሁሉ ግን ነፍሶቻቸውን ይጠብቃል፤ ክብርንና ባለሟልነትንም ይሰጣቸዋል።'),
  ('d75196cc-6c47-5250-ac1c-34c010bf7343', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 10, 10, 'በመግባታቸውና በመውጣታቸው፥ በሞታቸውና በሕይወታቸው፤ በመቀመጣቸውና በመነሣታቸውም ደስ ያሰኛቸዋል፤ እርሱ ያድናልና፥ ይገድላልምና።'),
  ('e509e772-29a9-5df5-a81d-a241eb5b76a6', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 11, 11, 'እርሱ ይገርፋል፤ ይቅርም ይላል።'),
  ('c3e82d87-9f59-5264-ada1-dea4ac1a606d', 'bbb7e060-ed44-5ba9-a377-de1ef132464e', '5c02a8b7-53cb-59ff-ad3a-874df4898773', 12, 12, 'እርሱ ያደኸያል፤ ባለ ጸጋም ያደርጋል፤ እርሱ ያዋርዳል፥ ያከብራልም።'),
  ('a0da634b-c520-5977-a05f-f6010224ed02', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 1, 1, 'በሰማይም ያለ ቢሆን፥ በምድርም ያለ ቢሆን፥ ረቂቅም ቢሆን፥ ግዙፍም ቢሆን ሁሉም የእርሱ ነው፤ ሁሉም በሥርዐቱ ጸንቶ ይኖራል።'),
  ('6e03d990-e468-589e-ab6e-cedcc4a2f28d', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 2, 2, 'ከዓለሙ ሁሉ ፈጣሪ ሕግና ትእዛዝ የሚተላለፍ የለም፤ በሰማይ የሚበር የንስር ፍለጋ ቢሆን፥ ወደ ወደደበት መሄጃውን እርሱ ያዝዛል።'),
  ('e78023b2-fff4-52f1-aed7-a221b0cd54d2', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 3, 3, 'የእባብንም ጎዳና በዓለት ውስጥ እርሱ ወደ ወደደበት ያዝዛል፤ የመርከብንም ጎዳና በባሕር ውስጥ ከእግዚአብሔር ብቻ በቀር ጎዳናውን የሚያውቀው የለም።'),
  ('27dd531e-6a63-5330-a471-e28e1c20461c', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 4, 4, 'የጻድቅም ነፍስ፥ የኃጥእም ነፍስ ብትሆን፥ ከሥጋዋ ከተለየች በኋላ ከእግዚአብሔር ብቻ በቀር ነፍስ የምትሄድበትን ጎዳና የሚያውቅ የለም።'),
  ('25f40708-2d5b-518c-a771-20f92dd7ee9c', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 5, 5, 'በምድረ በዳ ወይም በተራራም ትዞር እንደ ሆነ የምትዞርበትን ማን ያውቃል? እንደ ወፍም ትበር እንደ ሆነ፥ በተራራውም ንቃቃት ላይ እንደሚወርድ እንደ አርሞንኤም ጠል ትሆን እንደ ሆነ፥'),
  ('c229d75a-6dea-5e28-aa36-883e8fb28a14', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 6, 6, 'እንደ ጥቅል ነፋስም ትሆን እንደ ሆነ፥ ጎዳናውን እንደሚያቀና መብረቅም ትሆን እንደ ሆነ፥'),
  ('7be8d70c-8343-54f0-a803-3413aeffc873', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 7, 7, 'በጥልቁ ላይም እንደሚያበሩ ከዋክብት ትሆን እንደ ሆነ፥ በጥልቁ መካከል እንደሚከመር እንደ ባሕር ዳር አሸዋም ትሆን እንደ ሆነ፥'),
  ('dd67922e-8fa4-51eb-aab8-21b5c274aca9', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 8, 8, 'በባሕሩም ጥልቅ ዳርቻ እንደ ጸና እንደ አድማስ ድንጋይም ትሆን እንደ ሆነ፥ በውኃ መፍሰሻ እንደ በቀለች፥ የአማረ ፍሬዋንም እንደምትሰጥ ዛፍ ትሆን እንደ ሆነ፥'),
  ('3350db58-4d5e-5fc5-a2d7-5d3ded6edc80', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 9, 9, 'ዋዕየ ፀሐይ እንደሚያቃጥለው፥ ነፋስም አንሥቶ ወደ አልበቀለበት ወደ ሌላ ቦታ እንደሚወስደው፥ ፍለጋውም እንደማይገኝ እንደ መቃ ትሆን እንደ ሆነ፥ ፍለጋው እንደማይገኝ እንደ ጉም ሽንትም ትሆን እንደ ሆነ ማን ያውቃል?'),
  ('87abbcdb-7e67-5fb0-a8f3-f9e0f86e4bc2', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 10, 10, 'የእግዚአብሔርንስ መንገድ ማን ያውቃል? መካሮቹስ እነማን ናቸው? ከማንስ ጋር መከረ?'),
  ('bdf1d139-1a4b-597f-a56c-98f867ea6b11', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 11, 11, 'የእግዚአብሔር አሳቡ ከሰው የተሰወረ ነውና ፍለጋውን ማን ይከተላል?'),
  ('dcbc4ee9-0f2b-514e-a628-ba449f297667', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 12, 12, 'የእግዚአብሔርን ምክሩንና ጥበቡን መመርመር የሚችል ማን ነው? እርሱ ምድርን በውኃ ላይ መሥርትዋታልና፥ ያለካስማም አጽንትዋታልና፥ በፍጹም ጥበቡም ሰማይን በነፋስ አጸናው፤ ተባዕታዊውንም ውኃ እንደ ድንኳን ዘረጋው።'),
  ('cf32e36f-f330-5e5a-a6ef-22d14580d546', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 13, 13, 'ደመናትንም በምድር ላይ ዝናምን ያዘንሙ ዘንድ አዘዛቸው፤ ሣርንም ያበቅላል፤ በእግዚአብሔርም በአንድነት ደስ ይለን ዘንድ ለሰው ምግብ ሊሆኑ ቍጥር የሌላቸው ፍሬዎችን ያበቅላል።'),
  ('f9f62705-7d56-56c6-a98a-0ff877b3eda3', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 14, 14, 'እግዚአብሔር ለሰው ልጆች በረከቱን ሁሉ፥ ደስታውንና ጥጋቡንም ይሰጣቸዋል ይኸውም ጠግበው ከምድር ፍሬ የሰጣቸውን እግዚአብሔርን ያመሰግኑት ዘንድ ነው።'),
  ('a36c0e05-8f51-536c-a71f-3977501a4c67', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 15, 15, 'የአማረ መጐናጸፊያንም ያለበሳቸውን፥ የሚፈለገውንም በረከት ሁሉ፥ የእግዚአብሔርን ፈቃድ ለሚፈጽሙ ሰዎች የተሰጠ ደስታውንና ተድላውንም ይሰጣቸዋል።'),
  ('56d952f5-2e13-5a41-a5e0-1eb0871f64b6', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 16, 16, 'የእግዚአብሔርንም ትእዛዝ ለሚጠብቁ፥ ለአባቶቻቸው በአዘጋጀው ማደሪያ በሰማያት ክብርንና መወደድን ደስታንም ይሰጣቸዋል።'),
  ('cf67fc35-9d6d-501a-ad02-078e6a6f4ec6', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 17, 17, 'በአምልኮቱና በፍርዱ ለኖሩ፥ ሕጉን ይጠብቁ ዘንድ፥ ሥርዐቱንም ይሹ ዘንድ ለጠበቃቸውና ለመገባቸው፥ ለአሳደጋቸውና ለአከበራቸው፥ ከእርሱም ትእዛዝ ላልወጡ ክብርንና ሞገስን ይሰጣቸዋል፤ እኔም ጠላቶቻቸውን በማድከም፥ ሰውነታቸውንም በመጠበቅ እግዚአብሔር በዚህ ዓለም ለወዳጆቹ የሚያደርገውን አየሁ።'),
  ('c4e8a11a-b2a5-5f86-ac34-1a74ec861cc2', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 18, 18, 'ሁሉንም እንደ ለመኑት ይሰጣቸዋል፥ ፈቃዳቸውንም ይፈጽምላቸዋል፤ ከእግዚአብሔር ትእዛዝ አትውጡ፤ የእግዚአብሔርንም ፈቃድ ፈጽሙ።'),
  ('82a6eac8-bd06-5a4b-a3e1-a00eb37128a9', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 19, 19, 'እንዳይቈጣባችሁ፥ በአንድ ጊዜም እንዳያጠፋችሁ፥ በቍጣውም እንዳይገርፋችሁ፥ ቀድሞ ከነበራችሁበት ከአባቶቻችሁ ርስትም እንዳትወጡ፥ ማደሪያችሁም እስከ ዘለዓለሙ ድረስ መውጫ በሌለበት በገሃነም እንዳይሆን ከትእዛዙና ከሕጉ አትውጡ።'),
  ('684593a6-0581-5513-a32e-5581b5239971', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 20, 20, 'በእግዚአብሔር ፊት በቆማችሁ ጊዜ ሥራችሁ በጎ ይሆን ዘንድ ነፍሳችሁ ከሥጋችሁ ሳትለይ የፈጣሪያችሁን የእግዚአብሔርን ፈቃድ ጠብቁ።'),
  ('e9688cf1-218b-5f87-a0d6-6e7b39b367c1', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 21, 21, 'የሰማይና የምድር መንግሥት ለእርሱ ብቻ ነውና፤ ከሃሊነትም፥ መንግሥትም ለእርሱ ነውና፤ መራራትና ይቅር ማለትም ለእርሱ ብቻ ነው።'),
  ('5941fb79-21d3-5910-af1b-f5473ec60140', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 22, 22, 'እርሱ ባለጸጋ ያደርጋልና፤ ያደኸያልምና፥ ያዋርዳልና፥ ያከብራልምና።'),
  ('be6879df-3b9d-586e-a522-71f2e29b9b7f', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 23, 23, 'ዳዊትም ስለ እርሱ እንዲህ ብሎ ተናገረ፥ “ሰው ከንቱን ይመስላል፤ ዘመኑም እንደ ጥላ ያልፋል።'),
  ('b229fd09-6711-5f43-ad45-269371217530', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 24, 24, 'አቤቱ፥ አንተ ግን ለዘለዓለም ትኖራለህ፤ ስም አጠራርህም ለልጅ ልጅ ነው።”'),
  ('31410cc6-7379-5027-ab82-fd1f0aed0b25', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 25, 25, 'ዳግመኛም እንዲህ አለ፥ “መንግሥትህ የዘለዓለም መንግሥት ነው፤ አገዛዝህም ለልጅ ልጅ ነው፥” አንተ መንግሥትን ከሳኦል ወስደህ ለዳዊት ሰጠህ።'),
  ('10d53814-600b-5df9-a152-29bee68ccae1', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 26, 26, 'አንተን ግን የሚሾምህ የለም፤ አንተንም መሻር የሚችል የለም፤ አንተን ማየት የሚችል የለም፤ አንተ ግን ሁሉን ታያለህ።'),
  ('f726c620-18fb-5c86-a599-9906ad6eb80f', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 27, 27, 'መንግሥትህም ለልጅ ልጅ ዘመንና ለዘለዓለም አይሻርም፤ እርሱን የሚገዛው የለም፤ እርሱ ግን ሁሉን ይገዛል፤ ሁሉንም ያያል።'),
  ('bc1f0262-de3e-5494-ae09-07a125a1b3a9', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 28, 28, 'ያመሰግኑት ዘንድ ያለ ጥርጥርም በቀና ልቡና አምልኮቱን ያውቁ ዘንድ፥ ከፈጠራቸውና ከመገባቸው፥ ከአከበራቸውና ከአሳደጋቸው ከእግዚአብሔርም ብቻ በቀር ለሌሎች አማልክት የሚሰግዱ እንዳይሆኑ እርሱ ሰውን በመልኩና በምሳሌው ፈጥሮታልና ልብንና ኵላሊትን ይመረምራል።'),
  ('a7326755-0059-5846-ad28-246bd8191ec9', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 29, 29, 'እነርሱ ግን የፈጠራቸውን እግዚአብሔርን ማምለክን እንቢ አሉ፤ ለድንጋይና ለእንጨት፥ የሰው እጅም ለሠራቸው ለብርና ለወርቅ ይሰግዳሉ።'),
  ('7177b5fc-9d2b-503a-af83-95401625c280', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 30, 30, 'በዚያም በእግዚአብሔር ፊት ይቆም ዘንድ የመሥዋዕታቸው ጢስ ወደ ሰማይ እስኪወጣ ድረስ ይሠዉላቸዋል፤ ጣዖታቸውንም በማምለክ ሰለ ሠሩት ኀጢአታቸው ሁሉ ይከስሳቸዋል።'),
  ('3c105b12-9d58-5911-aa70-acdefa430472', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 31, 31, 'የተማሩትንም የእግዚአብሔርን ትእዛዝ አልጠበቁም። ነገር ግን ለጣዖት መስገድን፥ የሚገባ ያይደለ የጐደፈ ሥራንም ሁሉ፥ በኮከብ ማሟረትን፥ ጥንቆላንና ጣዖት ማምለክን፥ ክፉ ፈቃድንና እግዚአብሔር የማይወድደውንም ሥራ ሁሉ ተማሩ።'),
  ('205c6510-b8c5-58fe-add4-0032369ceb5c', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 32, 32, 'በእግዚአብሔርና በመላእክቱ ፊት እንዲመሰገኑ ከኀጢአትና ከበደል ሰውነታቸውን ያድኑ ዘንድ፥ እግዚአብሔርን ማመስገንን አልወደዱምና በጎ ሥራ በማጣት ይኸን ሁሉ ይሠራሉ።'),
  ('3364c030-4543-5c23-a1a2-133b9b48cd4f', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 33, 33, 'ከተቀበሩበትና አጥንቶቻቸው ከረገፉበት ከመቃብር ሁሉም በአንድነት በተነሡ ጊዜ፥ ነፍሳቸው በእግዚአብሔር ፊት ዕራቁትዋን ትቆማለች፤ ነፍሳቸውም ለደጋጎች ሰዎች በተዘጋጁ በብርሃን ቤቶች ትኖራለች።'),
  ('7ce3cbef-ec79-5b12-ab40-cc81d9f83dee', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 34, 34, 'የኀጢአተኞች ሰዎች ነፍስ ግን በጨለማ ትኖራለች፤ መቃብራትም በተከፈቱ ጊዜ ሥጋዎች ይነሣሉ፤ ነፍሳትም ቀድሞ ወደ ተለዩአቸው ሥጋዎች ይመለሳሉ።'),
  ('7b7e1fb3-c93f-508c-a86d-57d9e2dd6303', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 35, 35, 'ዕራቁታቸውን እንደ ተወለዱ በእግዚአብሔር ፊት ዕራቁታቸውን ይቆማሉ፤ ከሕፃንነታቸው ጀምሮ እስከዚያ ጊዜ የሠሩት ኀጢአታቸውም ይገለጣል።'),
  ('0cbd2df9-e32b-564b-a590-b7f2f1f205f6', '54e8705d-21c3-5eae-a978-6729cb2c9097', 'fed47c06-34c1-5c5c-adb0-f9cd47af789b', 36, 36, 'ኀጢአታቸውን በጫንቃቸው ይሸከማሉ፤ ጥቂትም ቢሆን፥ ብዙም ቢሆን፥ ኀጢአት ቢሠሩ እንደ ሠሩት ሥራቸው ይቀበላሉ።'),
  ('fab21cc0-0879-5e84-aca9-8297002c6294', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 1, 1, 'የሙታንን ትንሣኤ ከአላመንህ ሳይወለዱ ነፍሳት በክረምት ምን ያህል እንደሚነሡ ስማ፤ ቀድሞ እፍ እንዳለባቸው የእግዚአብሔር መንፈስ በእነርሱ ላይ ያርፋልና።'),
  ('679647d7-b8a9-518b-a626-776645d12d65', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 2, 2, 'እንዲሞቱም ቀድሞ በቃሉ ያዛቸዋል።'),
  ('dadfc34b-f291-50ab-a0ce-55b5316443ae', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 3, 3, 'ሥጋቸው ፈርሶ ሳለ እርሱ እንደ ወደደ ይነሣሉ፤ ዳግመኛም ይታደሳሉ።'),
  ('bd022435-4bf1-57e1-a68c-13ee9b124ec9', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 4, 4, 'ዳግመኛም ዝናም በሚወርድ ጊዜ ምድርንም በሚአረካት ጊዜ ይነሣሉ፤ ቀድሞም እንደ ተሠራላቸው ይኖራሉ።'),
  ('49de33d2-f23a-59f6-a99c-eaf63cf0a896', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 5, 5, 'በደማዊት ነፍስ ሕያዋን የሚሆኑትና በምድር ላይ የሚንቀሳቀስ፥ ውኃም የሚያስገኛቸው ሁሉ እርሱ አዝዞአልና ተፈጠሩ፤ የእግዚአብሔርም መንፈስ በውኃው ላይ ይሰፍፍ ነበርና፤ በመንፈሱና በቃሉም ደማዊት ነፍስ ትሰጣቸዋለች።'),
  ('5f73b9a7-634a-50f7-a97e-adc9fc860fa0', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 6, 6, 'ሙታን አይነሡም የምትል አንተ ልበ-ዕውር እስኪ ተመልከት፤ በመንፈሱና በቃሉ ያለ አባትና እናት ይፈጠራሉና፤ ጥበብ ካለህስ ሙታን በፈጣሪያቸው በእግዚአብሔር ቃል አይነሡም እንዴት ትላለህ?'),
  ('c1971ee2-fb4a-5d61-a4df-ce848a2d750f', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 7, 7, 'አንተስ ንስሓ ግባ፤ ወደ እምነትህም ተመለስ፤ በመቃብር ኣመድና ትቢያ የሆኑ ሙታን በእግዚአብሔር ቃል ይነሣሉና።'),
  ('fdf564aa-2fb2-5f3c-ae84-00760502e5ba', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 8, 8, 'ቀድሞ ቃሉ እንደ ተናገረ ከእግዚአብሔር በተገኘ በይቅርታ ጠል ይነሣሉ፤ ያም ቃል ሁሉን ዞሮ ሙታንን እንደ ወደደ ያስነሣቸዋል።'),
  ('43adac27-369a-5dec-aa80-49f5deae389f', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 9, 9, 'ተነሥተህም በፊቱ እንደምትቆም ዕወቅ፤ እንደ አሳብህም በመቃብር የምትቀር አይምሰልህ።'),
  ('42bfc86b-9c98-5f85-aa73-8b1dc096696e', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 10, 10, 'እንዲህ አይደለም፥ በምድር እንደ ሠራኸው ሥራ በጎም ቢሆን፥ ክፉም ቢሆን፥ ተነሥተህ ዋጋህን ትቀበላለህ፤ ይህች የፍዳ ቀን ናትና።'),
  ('7d2650f3-ccad-5df9-ac37-6ef6bbce86bd', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 11, 11, 'በትንሣኤም ጊዜ በሠራኸው ኀጢአትህ ሁሉ ፍዳህን ትቀበላለህ፤ ከሕፃንነትህ ጀምሮ እስከዚያ ጊዜ ድረስ የተጻፈ ዕዳህን ትጨርሳለህ፤ ኀጢአትህንም ትክድ ዘንድ እንደዚህ ዓለም ሥራ በኀጢአትህ የምታመካኘው ምክንያት የለህም።'),
  ('18d741d6-4912-5171-af1d-b8ff7ab65233', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 12, 12, 'ሐሰተኛ ቃልህን በፊትህ እውነት እንደምታደርገው፥ የተናገርኸው ሐሰቱንም ነገር እውነት እንደምታደርገው፥ በዚያ የምታመካኘው ምክንያት የለህም።'),
  ('3deaf4b1-e6dd-51d7-a8cc-b2b31067ac49', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 13, 13, 'እርሷ የሠራኸውን ክፉ ሥራህን ሁሉ የምታውቅብህ ስለሆነ በፈጣሪዋ በእግዚአብሔር ፊትም የምትገልጥብህ ስለ ሆነ የእግዚአብሔር ቃሉ በአንተ አድሮ ይናገርብሃልና።'),
  ('57b024ea-992c-5d67-a81a-25c4f9c68962', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 14, 14, 'በዚያም ስለ ሠራኸው ኀጢአትህ ታፍራለህ፤ በመልካም ሥራቸው ከሚመሰገኑ ጋር ትመሰገን ዘንድ ነው እንጂ በፍርድ ቀን በመላእክትና በሰዎች ፊት እንዳታፍር ወደዚያ ሳትደርስ በዚህ ንስሓ ለመግባት ፍጠን።'),
  ('9b13805a-455c-5a6c-a3aa-f433239bcc95', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 15, 15, 'ከመላእክት ጋራ እግዚአብሔርን የሚያመሰግኑ ያለ ኀፍረት ከፈጣሪያቸው ዋጋቸውን ይቀበላሉ፤ ደስም ይላቸዋል፤ ነገር ግን በሥጋህ በሕይወት ሳለህ በጎ ሥራን ካልሠራህ ከጻድቃን ጋር እድል የለህም።'),
  ('cf9a52d0-9bd2-5dd7-a610-1269e872ca51', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 16, 16, 'ዕውቀት ሳለህ፥ ዋጋና ገብያም ሳለህ አልተዘጋጀህምና፥ ገንዘብም ሳለህ ለተራበው አላጐረስኸውምና የማይረባ ጸጸት ይሆንብሃል።'),
  ('e59385d7-9bec-5ab6-a248-b3607c8dc09c', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 17, 17, 'ልብስም ሳለህ የታረዘውን አላለበስኸውምና፥ ሥልጣንም ሳለህ የተበደለውን አላዳንኸውምና።'),
  ('3ef00f91-ad29-5334-a968-d5ec20325b87', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 18, 18, 'ዕውቀትም ሳለህ ተመልሶ ንስሓ ይገባ ዘንድ፥ ቀድሞ ባለማወቅ የሠራውንም ኀጢአቱን እግዚአብሔር ይቅር ይለው ዘንድ ኃጥኡን ሰው አላስተማርኸውምና፥ ድል መንሣትንም ትችል ዘንድ ኀይል ሳለህ ከሚጣሉህ ከአጋንንት ጋር አልተዋጋህም።'),
  ('181a5708-e24c-5234-a2fc-762947dac100', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 19, 19, 'ጽናትም ሳለህ በሥጋ ያለ የሕፃንነትህን ኀይል ታደክም ዘንድ በዓለም ያለ ሥጋን ለማስደሰት ያይደለ ለጽድቅ ራስህን ታስገዛ ዘንድ አልጾምህም፤ አልጸለይህምም።'),
  ('0b533ca8-3345-529d-afde-276625fcab53', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 20, 20, 'በዓለም በአለ ደስታ፥ በጣፋጭ ምግቦችና በማለፊያ መጠጥ አይደለም፤ በቀጭን ልብስም በወርቅና በብር በማጌጥም አይደለም።'),
  ('ded72439-9ff1-5125-a15b-ef1b8073c5dd', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 21, 21, 'በከበሩ በሕንደኬ ዕንቍዎች፥ በጳዝዮንና በመረግድ አይደለም፤ ይህ የሚገባ የሰው ጌጥ አይደለም።'),
  ('b21ab5bc-66c5-51f5-a2aa-a68acec26582', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 22, 22, 'ለሰውስ ጌጡ ንጽሕና፥ ጥበብና ዕውቅት፥ ያለ መቅናትና ያለ ምቀኝነት፥ ያለ መጠራጠርና ያለ ጠብ በሚገባ መዋደድ ነው።'),
  ('514b5143-b3f9-5c17-a310-cde7dddc379b', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 23, 23, 'ባልንጀራህን እንደ ራስህ እየወደድህ፥ ክፉ ባደረገብህ ሰውም ክፉ ነገር ሳታደርግ፥ መከራውን ለታገሡ ሰዎች ወደ ተሰጠ ማደሪያም ትገባ ዘንድ፥ ቅድስት ምድርን በትዕግሥትና በዕውቀት፥ በትንሣኤም ጊዜ መንግሥተ ሰማይን ተስፋ በማድረግ ከወረስዋት ሰዎች ጋር ዋጋህን ይሰጥህ ዘንድ ነው።'),
  ('d29a259c-d923-5ac9-af67-271ec4ab1ec7', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 24, 24, '“ከሞትን በኋላ አንነሣም” አትበሉ፤ ይኽን የሚናገሩና የሚያስቡ ሰዎችን በትንሣኤ ጊዜ እንዳይድኑ ዲያብሎስ ተስፋ ያስቈርጣቸዋልና፥ ትንሣኤም በደረሰችባቸው ጊዜ ያውቃሉ፤ ኀጢአታቸውን ያስብባቸው ዘንድ ባለ ማወቅ ኀጢአት የሠሩ ሰዎች በትንሣኤ ጊዜ ፈጽመው ያዝናሉ፤ በዚያች ቀን እንደሚነሡ አላመኑበትምና።'),
  ('7f61cf81-0ac5-545c-af97-41fe79cc0220', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 25, 25, 'ስለዚህም በምድር ላይ እንደ ሠሩት ሥራቸው ክፋት ይወቀሳሉ፤ በሥጋ በአንድነት የሚነሡባትን የካዷትንም ትንሣኤ ያዩአታል።'),
  ('a561c10d-029f-5d58-aa4b-31f11d161f00', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 26, 26, 'ሥራቸውንም ስላላሳመሩ ያንጊዜ ያለቅሳሉ፤ ቢቻላቸውስ በዚያ የሚያለቅሱ እንዳይሆኑ፥ በዚህ ዓለም ቢያለቅሱ በተሻላቸው ነበር።'),
  ('6c0b6b7f-0eb1-53b2-a33a-3c2cc5a3999f', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 27, 27, 'በዚህ በፈቃዳችን ካላለቀስን፥ በዚያ ያለፈቃዳችን ያስለቅሱናል፤ በዚህ ንስሓን ካላዘጋጀን፥ በዚያ የማይረባና የማይጠቅም ጩኸትንና ልቅሶን እናዘጋጃለን።'),
  ('168923ec-083f-5e54-a4af-3ec1a6edf523', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 28, 28, 'ከሞት ወደ ሕይወት፥ ከምታልፍ ከዚህች ዓለምም ወደ ላይኝ`ዋ መንግሥተ ሰማይ፥ ከዚች ምድራዊት ብርሃንም ወደ ሰማያዊት ብርሃን ትሸጋገሩ ዘንድ መልካም ሥራን አዘጋጁ።'),
  ('e5ddbdd3-a7c5-5cdd-a6b2-2f831b299c97', '96cc0bbe-5052-54e8-a7fa-bd44f97d48e9', '89c19a12-f6d0-53a8-a343-2c7bbcbc94f0', 29, 29, 'የሙታን ትንሣኤን ከሚያምኑ ሰዎች ጋር በማያልቅ ደስታ በመንግሥተ ሰማይ ደስ ይልህ ዘንድ በምድር ያለች ደስታን እንቢ በላት፤ ከዛሬ ጀምሮ እስከ ዘለዓለም አሜን።'),
  ('5b1b1cb3-cf97-57a5-ac47-8348dacae65e', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 1, 1, 'አውስጢድ በሚባል ሀገር ስሙ ኢዮብ የተባለ አንድ ሰው ነበረ፤ ያም ሰው ቅን፥ ንጹሕና ጻድቅ፥ እግዚአብሔርንም የሚፈራ፥ ከክፉ ሥራም ሁሉ የራቀ ነበር።'),
  ('07d87979-8169-570f-a0a1-53d89ab2c09c', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 2, 2, 'ሰባትም ወንዶች፥ ሦስትም ሴቶች ልጆች ነበሩት።'),
  ('fad683e9-35e7-53f5-a10c-a7b2633bf2e2', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 3, 3, 'ከብቶቹም፦ ሰባት ሺህ በጎች፥ ሦስት ሺህ ግመሎች፥ አምስት መቶም ጥማድ በሬ፥ አምስት መቶም እንስት አህዮች ነበሩ፤ እጅግ ብዙም አገልጋዮች ነበሩት፤ ሥራውም በምድር ላይ ታላቅ ነበረ፤ ያም ሰው በምሥራቅ ካሉ ሰዎች ሁሉ ይልቅ ገናና ነበረ።'),
  ('58624ba3-d73b-529b-aba5-75beab45fdb1', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 4, 4, 'ወንዶች ልጆቹም ሄደው በየተራ በእያንዳንዳቸው ቤት ግብዣ ያደርጉ ነበር፤ ሦስቱ እኅቶቻቸውንም ከእነርሱ ጋር ይወስዱአቸው ነበር፤ ከእነርሱም ጋር ይበሉና ይጠጡ ነበር።'),
  ('3747c29a-339c-5f3e-af7d-748c4e26cbd4', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 5, 5, 'የግብዣውም ቀኖች በተፈጸሙ ጊዜ ኢዮብ ይልክና ይቀድሳቸው ነበር፤ በማለዳም ገሥግሦ፦ ስለ ልጆቹ በቍጥራቸው መሥዋዕት ያቀርብ ነበር፤ አንድ ወይፈን ስለ ነፍሳቸው የኀጢአት መሥዋዕት ያቀርብ ነበር፤ ኢዮብ፥ “ምናልባት ልጆቼ በልባቸው በእግዚአብሔር ላይ ክፉ ነገር ያስቡ ይሆናል” ይል ነበርና።'),
  ('0fa3c6ea-7d1e-543f-a823-d7d7a9e3e804', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 6, 6, 'ከዕለታት አንድ ቀንም እንዲህ ሆነ፤ የእግዚአብሔር መላእክት በእግዚአብሔር ፊት ለመቆም መጡ፤ ሰይጣንም ደግሞ ከእነርሱ ጋር መጣ።'),
  ('2238c0ed-ead6-5039-a55f-d6fdb30146bb', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 7, 7, 'እግዚአብሔርም ሰይጣንን፥ “ከወዴት መጣህ?” አለው። ሰይጣንም፥ “ምድርን ሁሉ ዞርሁአት፥ ከሰማይ በታችም ተመላለስሁና መጣሁ።” ብሎ ለእግዚአብሔር መለሰ።'),
  ('bbd27832-3676-5715-a0e3-4604f7d98000', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 8, 8, 'እግዚአብሔርም ሰይጣንን አለው፥ “በባሪያዬ በኢዮብ ላይ የምታስበው ነገር እንዳይኖር ተጠንቀቅ! በምድር ላይ እንደ እርሱ ቅን፥ ንጹሕና ጻድቅ፥ እግዚአብሔርንም የሚፈራ፥ ከክፉ ሥራም ሁሉ የራቀ ሰው የለምና።”'),
  ('f17e7bae-1a5f-5671-a0b6-99d464ae612f', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 9, 9, 'ሰይጣንም በእግዚአብሔር ፊት እንዲህ ብሎ መለሰ፥ “በውኑ ኢዮብ እግዚአብሔርን የሚያመልከው በከንቱ ነውን?'),
  ('fb0e2685-de85-5952-a50f-23c0d375546c', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 10, 10, 'አንተ ቤቱን በውስጥም በውጭም፥ በዙሪያው ያለውንም ሁሉ አልሞላህለትምን? የእጁንም ሥራ ባርከህለታል፥ ከብቱንም በምድር ላይ አብዝተህለታል።'),
  ('f3c555d6-44f4-5a90-a18f-5e62125453ec', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 11, 11, 'ነገር ግን እጅህን ዘርግተህ ያለውን ሁሉ ዳስስ፤ በእውነት በፊትህ ይሰድብሃል።”'),
  ('668aecef-d051-508f-af5a-7a2db15cc9d2', '3ff34124-ad5f-5e65-a4d4-688236f187e1', 'e03ec81e-1bd7-5636-a310-1a5e61a19c3a', 12, 12, 'እግዚአብሔርም ሰይጣንን፥ “እነሆ፥ ለእርሱ ያለውን ሁሉ በእጅህ ሰጠሁህ፥ ነገር ግን በእርሱ ላይ እጅህን አትዘርጋ” አለው። ሰይጣንም ከእግዚአብሔር ፊት ወጣ።'),
  ('22d7caac-5c35-5ee6-aa29-d1c0c48a7239', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 1, 13, 'አንድ ቀንም እንዲህ ሆነ፤ የኢዮብ ወንዶችና ሴቶች ልጆች በታላቅ ወንድማቸው ቤት ይበሉና የወይን ጠጅ ይጠጡ ነበር።'),
  ('760cb64f-9bd5-57e7-a842-07891c41f808', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 2, 14, 'መልእክተኛም ወደ ኢዮብ መጥቶ፥ “ጥምድ በሬዎችህ እርሻ ያርሱ ነበር፥ በአጠገባቸውም ሴቶች አህዮችህ ይሰማሩ ነበር፤'),
  ('57b3898d-1b14-5465-abbd-bef17e2acca9', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 3, 15, 'ማራኪዎችም መጥተው ወሰዱአቸው፥ ብላቴኖችህንም በሰይፍ ስለት ገደሉ፥ እኔም ብቻዬን አምልጬ እነግርህ ዘንድ መጣሁ” አለው።'),
  ('1c38382b-a547-5072-a49e-a36cdaff297a', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 4, 16, 'እርሱም ገና ይህን ሲናገር ሌላ መልእክተኛ መጥቶ፦ ለኢዮብ እንዲህ አለው፥ “እሳት ከሰማይ ወደቀች፥ በጎችህንም አቃጠለች፥ ጠባቂዎችህንም በላች፤ እኔም ብቻዬን አምልጬ እነግርህ ዘንድ መጣሁ።”'),
  ('dcf194dc-c596-531c-ae10-a2b682fda3fa', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 5, 17, 'እርሱም ገና ይህን ሲናገር ሦስተኛው መልእክተኛ መጥቶ ለኢዮብ እንዲህ አለው፥ “ፈረሰኞች በሦስት ረድፍ ከብበው ግመሎችን ማርከው ወሰዱ፥ ብላቴኖችህንም በሰይፍ ስለት ገደሉ፤ እኔም ብቻዬን አምልጬ እነግርህ ዘንድ መጣሁ።”'),
  ('952161ab-2484-5150-aa4d-4a1b0fdf0ed5', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 6, 18, 'እርሱም ገና ይህን ሲናገር አራተኛው መልእክተኛ መጥቶ ለኢዮብ እንዲህ አለው፥ “ወንዶችና ሴቶች ልጆችህ በታላቅ ወንድማቸው ቤት ሲበሉና የወይን ጠጅ ሲጠጡ፥'),
  ('9f51bf4d-f361-592b-afa6-21c8f242322b', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 7, 19, 'እነሆ፥ ዐውሎ ነፋስ ከምድረ በዳ ድንገት መጥቶ ቤቱን በአራት ማዕዘኑ መታው፥ ቤቱም በብላቴኖቹ ላይ ወደቀ፥ እነርሱም ሞቱ፤ እኔም ብቻዬን አምልጬ እነግርህ ዘንድ መጣሁ።”'),
  ('a113a7c6-e024-5abd-a987-ffb4f559c3e1', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 8, 20, 'ኢዮብም ተነሣ መጐናጸፊያውንም ቀደደ፥ ራሱንም ተላጨ፥ በምድርም ላይ ተደፍቶ ሰገደ፤'),
  ('a07c131c-51bc-5645-a10a-93096853f3de', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 9, 21, 'እንዲህም አለ፥ “ከእናቴ ማኅፀን ራቁቴን ወጥቻለሁ፥ ራቁቴንም ወደ ምድር እመለሳለሁ፤ እግዚአብሔር ሰጠ፥ እግዚአብሔርም ነሣ፤ እግዚአብሔርም እንደ ፈቀደ ሆነ የእግዚአብብሔር ስም የተባረከ ይሁን።”'),
  ('eba90d15-c084-533f-a2a1-d38df09492cb', '3ff34124-ad5f-5e65-a4d4-688236f187e1', '31ce422a-b3b4-59d1-ad8d-6e17a3fe93e5', 10, 22, 'በዚህም በደረሰበት ሁሉ ኢዮብ በእግዚአብሔር ፊት አልበደለም፥ ለእግዚአብሔርም ስንፍናን አልሰጠም።'),
  ('1e268163-daa2-5343-a185-f53f69ad53ac', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 1, 1, 'ከዕለታት አንድ ቀን እንዲህ ሆነ፤ የእግዚአብሔር መላእክት መጥተው በእግዚአብሔር ፊት ቆሙ፥ ሰይጣን ደግሞ በእግዚአብሔር ፊት ለመቆም ከእነርሱ ጋር መጣ።'),
  ('e8541e0b-c15e-5937-a75b-f93c3c0924f1', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 2, 2, 'እግዚአብሔርም ሰይጣንን፥ “ከወዴት መጣህ?” አለው። ሰይጣንም፥ “ከሰማይ በታች በምድር ላይ ዞርሁ፥ በእርስዋም ተመላለስሁ” ብሎ በእግዚአብሔር ፊት መለሰ።'),
  ('7a82d370-afe2-566f-ac03-92949e79bf08', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 3, 3, 'እግዚአብሔርም ሰይጣንን አለው፥ “በባሪያዬ በኢዮብ ላይ እንዲህ እንዳታስብ ተጠንቀቅ፤ በምድር ላይ እንደ እርሱ ያለ ገር፥ ጻድቅና ንጹሕ፥ እግዚአብሔርን የሚፈራ፥ ከክፋትም ሁሉ የራቀ፥ ዳግመኛም ቅን የሆነ ሰው የለምና፤ አንተ ግን ሀብቱን በከንቱ አጠፋ ዘንድ ነገርኸኝ።”'),
  ('2a463e97-1048-5f7c-a0c2-cf6c542725bd', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 4, 4, 'ሰይጣንም መልሶ ለእግዚአብሔር፥ “ቍርበት ስለ ቍርበት ነው፤ ሰው ያለውን ሁሉ ስለ ሕይወቱ ይሰጣል።'),
  ('15ef7452-d485-55e0-abf5-206be54ec6e5', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 5, 5, 'ነገር ግን አሁን እጅህን ዘርግተህ አጥንቱንና ሥጋውን ዳስስ፤ በእውነት በፊትህ ይሰድብሃል” ብሎ መለሰ።'),
  ('a33b1847-1919-5df5-aa96-89c9fca6f8a1', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 6, 6, 'እግዚአብሔርም ሰይጣንን አለው፥ “እነሆ፥ ሥጋውንና አጥንቱን በእጅህ ሰጠሁህ። ነገር ግን ሕይወቱን ተው።”'),
  ('26b3a0cb-f744-5f75-a67b-b62f84f02c45', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 7, 7, 'ሰይጣንም ከእግዚአብሔር ፊት ወጣ፥ ኢዮብንም ከእግሩ ጀምሮ እስከ አናቱ ድረስ በክፉ ቍስል መታው።'),
  ('8369fcb5-92e4-50da-af09-1045d9631d41', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 8, 8, 'ቍስሉንም ያክክበት ዘንድ ገል ወሰደ፥ ከከተማም ወጥቶ በአመድ ላይ ተቀመጠ።'),
  ('73220797-defd-522c-a321-e53db2109a32', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 9, 9, 'ብዙ ወራትም ካለፈ በኋላ ሚስቱ እንዲህ አለችው፥ “እስከ መቼ ትታገሣለህ? 9 ‘ሀ’ ዳግመኛም እግዚአብሔርን ጥቂት ወራት ደጅ እጠናዋለሁ፤ ዳግመኛም መከራውን እታገሠዋለሁ፤ የቀድሞው ኑሬዬንም ተስፋ አደርገዋለሁ ትላለህን? 9 ‘ለ’ እንደዚህስ እንዳትል ከዚህ ዓለም እነሆ ስም አጠራርህ ጠፋ፤ ወንዶችና ሴቶች ልጆቼም ሞቱ፥ ማኅፀኔም በምጥ ተጨነቀ፥ በከንቱም ደከምሁ። 9 ‘ሐ’ አንተም በመግልና በትል ትኖራለህ፤ ሌሊቱንም ሁሉ ትዛብራለህ። 9 ‘መ’ እኔ ግን እየዞርሁ እቀላውጣለሁ። ከአንዱ መንደር ወደ አንዱ መንደር፥ ከአንዱ ቤትም ወደ አንዱ ቤት እሄዳለሁ፤ ከድካሜና በእኔ ላይ ካለ ችግሬም ዐርፍ ዘንድ ፀሐይ እስኪገባ ድረስ እጠብቃለሁ፤ ነገር ግን አሁን እግዚአብሔርን ስደብና ሙት።”'),
  ('64dc4bd2-ef42-53b0-ab8a-fa9584eaf390', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', 'b6eac0d3-3a8c-594b-a32a-78c3401cf9d4', 10, 10, 'እርሱ ግን፦ ወደ እርስዋ ተመለከተና እንዲህ አላት፥ “አንቺ ከሰነፎች ሴቶች እንደ አንዲቱ ተናገርሽ፤ ከእግዚአብሔር እጅ መልካሙን ተቀበልን፥ ክፉውን ነገርስ አንታገሥምን?” በዚህ በደረሰበት ሁሉ ኢዮብ በእግዚአብሔር ፊት በከንፈሩ አልበደለም።'),
  ('15088dbd-956b-5168-add5-1fec4585fc4e', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', '613b9c80-5fcc-502c-ac7e-02b734641c0c', 1, 11, 'ሦስቱም የኢዮብ ወዳጆች ይህን የደረሰበትን ክፉ ነገር ሁሉ ሰምተው ከየሀገራቸው ወደ እርሱ መጡ፤ እነርሱም ቴማናዊው ንጉሥ ኤልፋዝ፥ አውኬናዊው መስፍን በልዳዶስ፥ አሜናዊው ንጉሥ ሶፋር ነበሩ። እነርሱም ሊጐበኙትና ሊያጽናኑት በአንድነት ወደ እርሱ መጡ።'),
  ('843f4c94-e62f-537b-ac14-8c1febd9c9fb', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', '613b9c80-5fcc-502c-ac7e-02b734641c0c', 2, 12, 'ከሩቅም ሆነው ባዩት ጊዜ አላወቁትም፤ በታላቅ ድምፅም ጮኸው አለቀሱ፤ መጐናጸፊያቸውንም ቀደዱ፥ በራሳቸውም ላይ ትቢያ ነሰነሱ።'),
  ('a275972a-639e-5c9d-ade9-0508e0724944', '1d9b94f6-b62a-5a02-afcd-f26496a0481e', '613b9c80-5fcc-502c-ac7e-02b734641c0c', 3, 13, 'ሰባት ቀንና ሰባት ሌሊትም በአጠገቡ ተቀመጡ፤ ሕማሙ እጅግ አስፈሪና ታላቅ እንደ ነበረ አይተዋልና ከእነርሱ አንድ ቃል የሚናገረው አልነበረም።'),
  ('a319d4a3-2cf1-55d1-a9be-900cfbf67a5c', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 1, 1, 'ከዚያም በኋላ ኢዮብ አፉን ከፈተ፥ የተወለደባትንም ቀን ረገመ።'),
  ('3f5adf3e-4d19-59de-a694-8309d9045fb9', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 2, 2, 'እንዲህም አለ፦'),
  ('052c5179-042b-5a5a-a78a-596970f82dfb', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 3, 3, '“ያች የተወለድሁባት ቀን ትጥፋ፥'),
  ('3715038a-7813-5000-a3b0-e1f0c94ee10f', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 4, 4, 'ያች ቀን ጨለማ ትሁን፤'),
  ('06befb2d-c90c-56fd-a4bd-e46555f7ff9c', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 5, 5, 'ጨለማና የሞት ጥላ ያግኙአት፤'),
  ('734ef29c-4b51-5bc2-a87e-b7b75c771c79', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 6, 6, 'ያች ቀንም የተረገመች ትሁን።'),
  ('bfd34aaa-9332-552e-aaa2-c32e59d7f3cd', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 7, 7, 'ለዚያም ሌሊት ጭንቅ ይሁን፥'),
  ('779df581-93da-565f-a486-2b35276d2cb5', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 8, 8, 'ነገር ግን ሌዋታንን ለመግደል የተዘጋጀ'),
  ('71ea3550-e3cb-56d9-a05f-884c578122f3', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 9, 9, 'የዚያ ሌሊት ኮከቦች ይጨልሙ፤'),
  ('67bd8b6b-e48b-5f7a-ad00-114d7c2e4531', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 10, 10, 'የእናቴን ማኅፀን ደጅ አልዘጋምና፥'),
  ('74a956a2-7d3a-5c92-a464-57949a2b73da', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 11, 11, 'በማኅፀን ሳለሁ ስለ ምን አልሞትሁም?'),
  ('1b62751f-0c09-5bea-a638-108c357516ee', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 12, 12, 'ጕልበቶች ስለ ምን ደገፉኝ?'),
  ('89f029fe-ce50-53f1-adad-aad7482ff4d8', 'ca55a357-9463-5fb5-a35f-a8b4fc8ff915', '5802d587-e306-5b60-aa01-f2bf5313cbc6', 13, 13, 'አሁንም ተኝቼ ዝም ባልሁ ነበር፤'),
